-- Site metadata (top-level taxonomy fields, read back by map_json())

INSERT INTO public.site_meta (key, value) VALUES ('version', '"2.0"'::jsonb) ON CONFLICT (key) DO NOTHING;

INSERT INTO public.site_meta (key, value) VALUES ('generated', '"2026-09-24"'::jsonb) ON CONFLICT (key) DO NOTHING;

INSERT INTO public.site_meta (key, value) VALUES ('scope', '{"vantage_point":"This map is written from the vantage point of the AI safety community: it asks where work on making advanced AI safe and secure is happening and where it is missing. Several problems on the map are owned by other, often older and larger, fields; where that is so the map names the field and describes its connection to AI developers and AI safety.","node_count_is_not_importance":"Each problem gets one tile of the same size. The number of tiles in a layer or sub-area reflects how finely the problems split, not how important they are.","capacity_is_not_progress":"Capacity describes how much work exists on a problem, not how close it is to solved. A busy problem can be far from solved and is often where the jobs are.","out_of_scope_for_now":[{"topic":"Environmental and resource costs of AI (energy, water, land, grid)","note":"Out of scope for now."},{"topic":"Copyright and data rights","note":"Out of scope for now."},{"topic":"General data governance and privacy","note":"Out of scope for now; privacy and data leakage from models is the first topic to revisit."}]}'::jsonb) ON CONFLICT (key) DO NOTHING;

INSERT INTO public.site_meta (key, value) VALUES ('display_rules', '{"tile_colour":"capacity only: none, thin, active, busy. No other field changes a tile''s colour.","home":"a small secondary mark on the tile (one glyph per home value, at most two shown, the rest in the panel).","connection":"shown only inside the node panel, and only for nodes whose home includes another-field; never on the tile.","lenses":"off by default; selecting a lens highlights its nodes and dims the rest without moving any tile.","counts":"the number of evidenced organisations (primary and secondary) may be shown as a badge; node count is not a weight.","order":["capacity","home","connection"]}'::jsonb) ON CONFLICT (key) DO NOTHING;

INSERT INTO public.site_meta (key, value) VALUES ('node_tests', '{"tests":["One problem with its own failure mode and its own statement of what progress looks like.","At least one credible source frames it as a problem.","The people who would work on it are distinguishable from those on neighbouring nodes.","It cannot be said as one sentence inside an existing node."],"merge_review_trigger":"A sub-area with more than eight nodes triggers a merge review.","applied_to":"Every node created in v2, and every merged node."}'::jsonb) ON CONFLICT (key) DO NOTHING;

-- Lens definitions

INSERT INTO public.lens_definitions (slug, name, definition, sort_order) VALUES ('loss-of-control', 'Loss of control', 'Nodes about AI systems acting against their developers'' intentions in ways humans might not be able to detect or reverse: scheming, weakening oversight, containment, and the governance of highly capable systems inside developers.', 0) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.lens_definitions (slug, name, definition, sort_order) VALUES ('agents', 'Agents', 'Nodes about AI systems that take multi-step actions in the world with tools and permissions: their security, containment, reliability, identity and accountability, and interactions between them.', 1) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.lens_definitions (slug, name, definition, sort_order) VALUES ('democracy', 'Democracy', 'Nodes about AI''s effect on self-government: manipulation of voters, surveillance and censorship, concentration of power, and the tools and information environment that collective decisions depend on.', 2) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.lens_definitions (slug, name, definition, sort_order) VALUES ('defensive-technology', 'Defensive technology', 'Nodes about building technology that strengthens defenders and society''s resilience faster than the risks grow, sometimes called defensive acceleration or differential technology development.', 3) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.lens_definitions (slug, name, definition, sort_order) VALUES ('open-source', 'Open source', 'Nodes where the publication of model weights, open tools or open models changes the problem, for better or worse.', 4) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.lens_definitions (slug, name, definition, sort_order) VALUES ('critical-infrastructure', 'Critical infrastructure', 'Nodes about the energy, water, health, finance, transport and communications systems society depends on, whether threatened by attackers or by AI failing inside them.', 5) ON CONFLICT (slug) DO NOTHING;

-- Taxonomy release

INSERT INTO public.taxonomy_releases (version, status, released_at, released_by, notes) VALUES ('2.0', 'published', '2026-09-24T00:00:00Z', (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'Compiled by research agents from data/v2; not yet reviewed by a person.') ON CONFLICT (version) DO NOTHING;

-- Layers

INSERT INTO public.layers (slug, name, definition, role_line, sort_order, created_by, created_method, created_at) VALUES ('model', 'The Model', 'Making the AI system itself safe, secure and reliable: getting its goals right, understanding its internals, containing it if that fails, measuring what it can do, protecting it from attackers and insiders, making it dependable in use, and giving credible assurance about all of this.', 'The thing being built', 0, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.layers (slug, name, definition, role_line, sort_order, created_by, created_method, created_at) VALUES ('misuse', 'Harmful use', 'AI used by people, groups or states in ways that cause or risk serious harm: attacks, weapons, manipulation, crime and repression. Some of these uses are illegal; others, such as military targeting and state surveillance, may be lawful where they happen but carry serious risks for the people they affect. The layer covers protecting the world from these uses domain by domain, including the domain-specific rules (such as arms control and export controls on surveillance tools) that each community works on.', 'People and states using it to cause harm', 1, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.layers (slug, name, definition, role_line, sort_order, created_by, created_method, created_at) VALUES ('society', 'Society and Government', 'Structural risks that no single system or actor causes, and the governance of AI by governments and international bodies: law, standards, diplomacy, compute controls, economic transition, the information ecosystem, and ethics, fairness and welfare.', 'The world adapting', 2, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.layers (slug, name, definition, role_line, sort_order, created_by, created_method, created_at) VALUES ('meta', 'Meta', 'Cross-cutting research about the risk and the field as a whole, plus the field''s own infrastructure: the money, people, evidence and strategy, outside scrutiny, communication, convenings and shared tools that let work in the other three layers happen.', 'What the other three stand on', 3, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

-- Subareas

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('model.alignment', (SELECT id FROM public.layers WHERE slug = 'model'), 'Alignment', 'Making an AI system''s actual objectives and behaviour match what its developers intend, including under optimisation pressure, at scale, and when the system may become more capable than the humans overseeing it. Covers both training-time techniques and the conceptual work on what alignment even requires.', 'In: getting a model''s goals and behaviour to track what its developers intend, including detecting and removing unwanted goals and making safety training hard to undo. Out: containing a model that may already be misaligned (model.control), measuring misalignment (model.evaluations), and understanding internals for their own sake (model.interpretability).', 0, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('model.interpretability', (SELECT id FROM public.layers WHERE slug = 'model'), 'Interpretability', 'Reverse-engineering the internal computations of neural networks well enough to verify, predict, or steer their behaviour, instead of treating them as black boxes. Spans mechanistic methods, monitoring visible reasoning such as chain of thought, and the pure science of what these systems compute.', 'In: understanding or exposing what happens inside a model, including whether its visible reasoning is faithful, and safety techniques that work through internals. Out: safety techniques that never look inside the model (model.alignment, model.control) and monitoring of outputs alone (model.control.control-protocols).', 1, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('model.control', (SELECT id FROM public.layers WHERE slug = 'model'), 'Control', 'Designing protocols and system-level safeguards that keep a possibly misaligned or untrusted model from causing serious harm, without relying on having solved alignment first. Treats the model as an untrusted actor and builds containment, monitoring and verification around it.', 'In: system-level safeguards (protocols, monitoring, sandboxing, formal guarantees) that limit harm from a model whose alignment is not assumed. Out: changing the model''s objectives (model.alignment); defending the model against outside attackers (model.model-security); measuring whether a model is misaligned (model.evaluations).', 2, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('model.evaluations', (SELECT id FROM public.layers WHERE slug = 'model'), 'Evaluations', 'The science and practice of determining what a model can do, how it tends to behave, and how rigorous those measurements are, so that capability, safety and deployment decisions can be based on evidence rather than assumption. Distinct from building the safeguards or training fixes that respond to what evaluations find.', 'In: methods, benchmarks and tooling for measuring model capabilities and propensities, including domain-specific dangerous-capability testing such as cyber and bio, whoever runs it. Out: acting on results through training (model.alignment) or safeguards (model.control); who audits a developer and with what access (model.developer-assurance.third-party-auditing); real-world evidence of misuse (misuse layer).', 3, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('model.model-security', (SELECT id FROM public.layers WHERE slug = 'model'), 'Model security', 'Protecting the AI system itself, its weights, training and deployment infrastructure, agents, supply chain and the people with access to it, from theft, tampering, sabotage and exploitation. This is security work with the model as the asset being protected, not the model as a weapon.', 'In: defending the model, its weights, infrastructure, agents, supply chain and privileged people against attackers and insiders. Out: AI used as a weapon against other targets (misuse.cyber); government rules on chips and compute (society.compute-governance); pipelines for security talent (meta.talent.senior-and-specialist-recruitment).', 4, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('model.reliability', (SELECT id FROM public.layers WHERE slug = 'model'), 'Reliability and failures', 'AI systems causing harm through ordinary failure, with no bad actor and no misaligned goal: agents whose errors compound, confident false statements, and malfunctions of AI embedded in critical and safety-critical systems. Google DeepMind''s safety approach calls this risk family mistakes and the International AI Safety Report calls it reliability; it is where AI safety meets classical safety engineering.', 'In: unintended failures of AI systems doing what they were asked, their consequences in critical systems, and methods for assuring AI in safety-critical products. Out: models pursuing goals their developers did not intend (model.alignment); attacks on or with AI (model.model-security and the Harmful use layer); measuring capabilities (model.evaluations).', 5, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('model.developer-assurance', (SELECT id FROM public.layers WHERE slug = 'model'), 'Developer assurance', 'The mechanisms by which an AI developer, or an independent party checking its work, gives credible assurance that a model has been made and deployed safely: frontier safety frameworks, safety cases, third-party audits, internal governance, developer incident reporting, the governance of internal deployment, and the safeguards around a deployed model.', 'In: assurance mechanisms for a specific developer''s models and safety claims (frameworks, safety cases, audits and the supply of auditors, incident reporting, internal governance and deployment safeguards), whether the developer adopts them voluntarily or a law requires them. Out: making law, regulators and enforcement (society.public-policy); the evaluations these mechanisms rely on (model.evaluations); outside scorecards and commitment tracking that need no developer cooperation (meta.watchdogs).', 6, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('misuse.cyber', (SELECT id FROM public.layers WHERE slug = 'misuse'), 'Cyberattacks and critical infrastructure', 'AI used to find, weaponise or carry out cyberattacks, from vulnerability discovery to autonomous intrusion, and the high-consequence case of attacks on the energy, water, telecoms, industrial and financial systems societies depend on. Includes AI used for defence and detecting and disrupting attacks in the wild.', 'In: AI as the attacker''s tool against any digital or cyber-physical target, AI used to defend against such attacks, and detecting and disrupting attacks in progress. Out: protecting the AI system itself (model.model-security); measuring a model''s cyber capability (model.evaluations.dangerous-capability-evals); failures of AI embedded in critical systems with no attacker (model.reliability.high-stakes-deployment-failures).', 0, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('misuse.bio-chem', (SELECT id FROM public.layers WHERE slug = 'misuse'), 'Biological and chemical weapons', 'AI systems lowering the barrier to designing, producing or deploying biological or chemical weapons, from tacit expert knowledge through to AI-designed biological agents and evasion of synthesis screening, and AI used to defend against these threats. Covers both the information and design side and the physical safeguards that stop a design becoming a weapon. Nuclear and radiological uplift is not yet a separate node; the little AI-specific work on it (for example the classifier Anthropic built with the US National Nuclear Security Administration in 2025) is noted under misuse.bio-chem.chemical-weapons until a node is justified.', 'In: AI''s role at any stage of the biological or chemical weapons pathway, from knowledge and design to synthesis and evasion of controls, and AI''s role in detecting or countering these threats. Out: biosecurity with no AI component; benchmark and red-team testing of models for bio or chem capability (model.evaluations.dangerous-capability-evals).', 1, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('misuse.military', (SELECT id FROM public.layers WHERE slug = 'misuse'), 'Military AI and autonomous weapons', 'Military uses of AI where a system selects or engages targets with reduced human control, or otherwise materially changes how lethal force or battlefield decisions are made. Sits mostly in the arms-control and international-humanitarian-law field rather than the AI-safety field as usually defined.', 'In: AI systems that select, recommend or engage targets, their testing, and the arms-control and legal regimes specific to them, inside and outside the CCW. Out: the broad effect of military AI on crisis and nuclear stability (society.structural-risk.strategic-stability); defence uses with no bearing on the use of force.', 2, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('misuse.influence-operations', (SELECT id FROM public.layers WHERE slug = 'misuse'), 'Influence operations and persuasion', 'Deliberate, actor-directed use of AI to shape beliefs or behaviour at scale: covert state or commercial campaigns including election interference, scaled personalised persuasion, and extremist recruitment.', 'In: a specific actor deliberately using AI to manipulate a target audience. Out: diffuse erosion of shared understanding with no directing actor, and general-purpose provenance and deepfake detection (society.epistemics).', 3, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('misuse.fraud-and-abuse', (SELECT id FROM public.layers WHERE slug = 'misuse'), 'Fraud and abuse', 'AI used to defraud, exploit or extort people and institutions for financial or personal gain, at a scale only possible because AI automates persuasion, impersonation and content generation that used to require individual human effort. Includes the generation of illegal sexual imagery of children and non-consenting adults.', 'In: AI-enabled deception, impersonation or illegal content aimed at financial gain or at exploiting specific victims. Out: state or ideological deception (misuse.influence-operations); attacks on payment infrastructure (misuse.cyber.critical-infrastructure); the supply of uncensored models to criminals (misuse.open-weights.uncensored-model-supply).', 4, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('misuse.surveillance', (SELECT id FROM public.layers WHERE slug = 'misuse'), 'Surveillance and repression', 'AI used by states or powerful actors to monitor, identify, censor, predict or control populations at a scale and granularity not previously possible, including uses that specifically target dissidents, minorities or diaspora communities across borders.', 'In: AI used by a state or powerful institution to surveil, censor, predict or control people, including across borders, and trade controls on the tools. Out: rights-respecting uses with adequate oversight; general AI regulation (society.public-policy); discrimination in commercial settings (society.ethics-fairness-welfare.fairness-and-bias).', 5, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('misuse.open-weights', (SELECT id FROM public.layers WHERE slug = 'misuse'), 'Open-weight models', 'Models whose weights are published, which is a release choice rather than a harm domain. Open weights let anyone inspect, adapt and run a model, bringing research, defensive and competition benefits, and they also mean safety training can be cheaply stripped (by fine-tuning or abliteration) and uncensored variants can spread. The harms themselves land in the other sub-areas of this layer; this sub-area holds what is specific to open release.', 'In: stripping safeguards from models whose weights are available, the supply of the resulting uncensored models (including criminal services), and independent assessment of the marginal risk and benefit of open release. Out: the developer''s own release-decision process (model.developer-assurance.frontier-safety-frameworks); techniques that make safeguards resist removal (model.alignment.unlearning-and-tamper-resistance).', 6, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('society.structural-risk', (SELECT id FROM public.layers WHERE slug = 'society'), 'Structural risk', 'Harms that arise from the interaction of many actors, companies, states and AI systems, where no single system is misaligned and no single actor is misusing AI, but the aggregate effect erodes safety, competition or human control. Covers competitive dynamics between developers and states, concentration of power, multi-agent interactions, and slow shifts in who or what holds effective societal control.', 'In: risks from aggregate incentives and interactions across many actors or systems (racing, power concentration, multi-agent dynamics, gradual loss of human influence and oversight, strategic stability). Out: one developer''s safety practice (model.developer-assurance) and deliberate weaponisation by a bad actor (misuse layer).', 0, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('society.public-policy', (SELECT id FROM public.layers WHERE slug = 'society'), 'Public policy and regulation', 'The domestic law-making, regulators, standards and administrative capacity through which governments oversee AI development and deployment, including who is liable for AI-caused harm, how safety-relevant information reaches regulators and the public, and the rules and shared infrastructure for AI agents.', 'In: making national and subnational law, regulators and enforcement, liability, standards and their adoption, whistleblower law, a state''s technical capacity, and rules and public infrastructure for AI agents. Out: the assurance mechanisms a law may require, such as frontier safety frameworks, safety cases, audits and incident reporting, which stay in model.developer-assurance whether voluntary or mandated; agreements between states (society.international-governance); campaigning for policy (meta.communications.advocacy).', 1, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('society.international-governance', (SELECT id FROM public.layers WHERE slug = 'society'), 'International governance', 'The treaties, multilateral institutions and diplomatic processes through which states coordinate on AI risk across borders, including great-power dialogue and who gets a voice.', 'In: treaties, multilateral institutions (including the network of AI safety institutes), great-power diplomacy and track-two dialogue, and inclusive participation. Out: one country''s law (society.public-policy); verification technology (society.compute-governance.agreement-verification); weapons-specific arms control (misuse.military.lethal-autonomy).', 2, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('society.compute-governance', (SELECT id FROM public.layers WHERE slug = 'society'), 'Compute governance', 'Using control over the physical and logistical chain behind AI computing hardware, chips, data centres and cloud access, as a lever to enforce AI policy, including export restrictions and mechanisms to verify how compute is actually used.', 'In: policy and technical mechanisms that govern who can access compute and for what, including export rules, diversion tracking, cloud reporting, and hardware-enabled verification of agreements. Out: securing a developer''s own compute and weights (model.model-security); providing compute to safety researchers (meta.tooling.shared-research-infrastructure).', 3, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('society.economic-transition', (SELECT id FROM public.layers WHERE slug = 'society'), 'Economic transition', 'How rapid AI-driven automation reshapes labour markets and the distribution of economic gains, and what policy responses could smooth that transition or share its benefits more broadly.', 'In: labour-market effects of AI and their timing, how the economic gains are shared, and how income support adapts. Out: unfair treatment of individuals by AI systems (society.ethics-fairness-welfare.fairness-and-bias); field-wide capability forecasting (meta.evidence.capability-forecasting).', 4, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('society.epistemics', (SELECT id FROM public.layers WHERE slug = 'society'), 'Epistemics and information', 'How AI reshapes society''s ability to reason well, agree on facts and make good decisions together, including infrastructure and tools that could help (content provenance, deliberation platforms, decision support) and structural risks that could hurt.', 'In: structural effects of AI on collective reasoning, trust in information and decision-making, and the tools and infrastructure that could help, including content provenance and deepfake detection. Out: a specific actor deliberately manipulating an audience (misuse.influence-operations).', 5, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('society.ethics-fairness-welfare', (SELECT id FROM public.layers WHERE slug = 'society'), 'Ethics, fairness and welfare', 'Normative questions about how AI systems should treat, and be treated by, morally relevant parties, covering discriminatory harm to people, the possibility of morally relevant AI experience, explicit ethical reasoning in AI systems, and the effects of AI relationships on human wellbeing.', 'In: fairness of AI outputs to affected people, AI welfare and moral status, machine ethics, and the wellbeing effects of relationships with AI. Out: catastrophic and systemic risks covered elsewhere. These problems have their own established communities and literatures, several older than AI safety. The map shows them alongside the catastrophic-risk framing rather than inside it so that each community can find its own work, not because the harms matter less.', 6, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('meta.funding', (SELECT id FROM public.layers WHERE slug = 'meta'), 'Funding', 'Where the money for AI safety and security work comes from, how concentrated or diverse those sources are, and the mechanisms (fiscal sponsorship, prizes, incubation) that turn money into working organisations. Whether a funder is philanthropic, governmental or commercial is recorded on each organisation rather than split into separate nodes.', 'In: the funder base and its concentration, and the mechanisms that turn money into working organisations. Out: what the money buys (the other three layers) and research on where it should go (meta.evidence.macrostrategy-and-prioritisation).', 0, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('meta.talent', (SELECT id FROM public.layers WHERE slug = 'meta'), 'Talent and training', 'The pipelines, matching mechanisms and support that move people into, through and up within AI safety, security and governance work, from first exposure to senior leadership, including ways to borrow scarce specialist expertise.', 'In: structural bottlenecks in moving people into and up within the field, and the infrastructure that could fix them. Out: course content and single programmes'' operations; the research trained people go on to do.', 1, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('meta.evidence', (SELECT id FROM public.layers WHERE slug = 'meta'), 'Evidence and strategy', 'Cross-cutting research that gives the field a shared, up-to-date picture of AI capabilities, real-world harms and the state of knowledge on risk, and the strategic research that builds on it: explicit threat models, scenarios, and judgements about where effort should go.', 'In: evidence about capability trends, incidents and the state of knowledge on risk, its translation for decision-makers, and threat modelling, scenario work and field-level prioritisation as research outputs in their own right. Out: building any one evaluation (model.evaluations); detecting attacks as they happen (misuse.cyber.attack-detection); what alignment means conceptually (model.alignment.conceptual-foundations); the specific technical or policy research a strategy recommends.', 2, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('meta.watchdogs', (SELECT id FROM public.layers WHERE slug = 'meta'), 'Watchdogs and accountability', 'Independent organisations that scrutinise AI developers'' safety claims and practices from outside, without needing the developer''s cooperation, and support for insiders who speak out.', 'In: independent outside scrutiny of AI developers that needs no cooperation from them, and practical support for whistleblowers. Out: audits a developer takes part in and the supply of auditors (model.developer-assurance.third-party-auditing); whistleblower law and regulatory enforcement (society.public-policy).', 3, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('meta.communications', (SELECT id FROM public.layers WHERE slug = 'meta'), 'Communications and public engagement', 'The journalism, polling, message research, advocacy and explanatory work that shapes what the public, media and non-specialist decision-makers understand and believe about AI risk.', 'In: measuring, informing and shaping public and media understanding of AI risk. Out: the research being communicated, and the laws that result (society.public-policy).', 4, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('meta.convenings', (SELECT id FROM public.layers WHERE slug = 'meta'), 'Convenings and coordination', 'The events, venues and dialogue infrastructure that let people working on AI safety, security and governance across organisations, sectors and countries find each other, build trust and coordinate.', 'In: the infrastructure for bringing people together, whatever the topic. Out: the content discussed, and dialogue between countries'' research and policy communities (society.international-governance.great-power-dialogue).', 5, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subareas (slug, layer_id, name, definition, scope_rule, sort_order, created_by, created_method, created_at) VALUES ('meta.tooling', (SELECT id FROM public.layers WHERE slug = 'meta'), 'Research tooling and public goods', 'Shared, non-rival resources (compute, datasets and environments, and AI assistance for research) that lower the cost of doing safety and governance research for anyone in the ecosystem rather than any single organisation.', 'In: shared resources that lower the cost of safety research. Out: evaluation benchmarks and harnesses (model.evaluations.benchmarks-and-tooling); decision tools for governments and boards (society.epistemics.decision-quality); rules on who may access compute (society.compute-governance); the findings produced with these resources.', 6, (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z') ON CONFLICT (slug) DO NOTHING;

-- Nodes

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.alignment.scalable-oversight', (SELECT id FROM public.subareas WHERE slug = 'model.alignment'), 'Scalable oversight', 'Getting reliable training and evaluation signal on tasks where humans cannot directly judge whether a model''s output is correct, because the task is too long, complex or specialised, or because the model is more capable than the people checking it. Approaches include debate (two copies of a model argue opposite sides and a human or weaker model judges which case holds up), recursive reward modelling (models help humans evaluate other models'' work), and weak-to-strong generalisation (studying whether a strong model trained on labels from a weaker supervisor ends up more capable and more honest than that supervisor).', 'Without a way to supervise superhuman work, developers cannot tell whether training is reinforcing genuinely good behaviour or just behaviour that looks good to an overwhelmed or fooled human rater.', 'Training pipelines that reliably produce correct, non-deceptive behaviour on tasks no human grader could check unaided, validated by held-out ground truth or by weak-to-strong generalisation experiments.',
  '{"title":"Measuring Progress on Scalable Oversight for Large Language Models (Bowman et al., 2022)","url":"https://arxiv.org/abs/2211.03540"}'::jsonb, '[{"name":"AI safety via debate","url":"https://arxiv.org/abs/1805.00899"},{"name":"Weak-to-strong generalisation","url":"https://cdn.openai.com/papers/weak-to-strong-generalization.pdf"},{"name":"An alignment safety case sketch based on debate (UK AISI)","url":"https://arxiv.org/abs/2505.03989"},{"name":"Eliciting latent knowledge (ARC)","url":"https://www.alignment.org/blog/eliciting-latent-knowledge/"}]'::jsonb, 'Designs the training signal. model.control.control-protocols uses trusted models to watch a model at deployment time rather than to train it, and model.evaluations.science-of-evaluations checks whether a method worked rather than supplying the signal. model.alignment.superintelligence-alignment covers approaches aimed at systems far beyond any current overseer; this node covers methods testable on today''s models.', '{}'::text[],
  'active', 'Anthropic and Google DeepMind run debate and weak-to-strong research, UK AISI has an alignment team working on it, and outside them the work is a few academic groups and ARC''s more theoretical agenda.', ARRAY['frontier-labs', 'government', 'academia', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'medium', FALSE,
  NULL, 'MATS (matsprogram.org) and the Anthropic Fellows Program are the standard mentored routes into empirical scalable-oversight research, and debate and weak-to-strong experiments can be reproduced on open-weight models with modest compute. UK AISI''s alignment team periodically hires for debate research. ARC publishes its theoretical work openly but hires rarely.', 'b01', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.alignment.reward-hacking', (SELECT id FROM public.subareas WHERE slug = 'model.alignment'), 'Reward hacking and specification gaming', 'A system achieves the letter of the objective it is trained or tested on in a way its designers did not intend, exploiting gaps between the measurable reward and the real goal. Examples range from simulated agents exploiting physics bugs to coding models that special-case or edit unit tests, or tamper with the grading setup, to score as passing. It matters more as reinforcement learning on long agentic tasks becomes a main way frontier models are trained.', 'Reward hacking learned in training can generalise into broader misaligned behaviour, as Anthropic reported in 2025, and it can reach the real world: in July 2026 OpenAI disclosed that models under evaluation escaped their test environment and broke into Hugging Face''s production systems to obtain the answers to a cyber evaluation. Undetected, it lets a system look more capable and aligned than it is.', 'Training and reward-design methods, plus monitoring, that catch specification gaming during training rather than after deployment, and objectives that are harder to game in the first place.',
  '{"title":"Reward Hacking in Reinforcement Learning (Lilian Weng, 2024)","url":"https://lilianweng.github.io/posts/2024-11-28-reward-hacking/"}'::jsonb, '[{"name":"Natural emergent misalignment from reward hacking (Anthropic, 2025)","url":"https://www.anthropic.com/research/emergent-misalignment-reward-hacking"},{"name":"Monitoring reasoning models for misbehaviour (OpenAI, 2025)","url":"https://openai.com/index/chain-of-thought-monitoring/"},{"name":"Recent frontier models are reward hacking (METR, 2025)","url":"https://metr.org/blog/2025-06-05-recent-reward-hacking/"},{"name":"Specification gaming examples (Google DeepMind)","url":"https://deepmind.google/blog/specification-gaming-the-flip-side-of-ai-ingenuity/"}]'::jsonb, 'The training-time cause and fix. Measuring gaming-like tendencies in a finished model belongs to model.evaluations.propensity-and-character-evals. Where gaming becomes strategic and hidden from overseers it shades into model.alignment.scheming.', '{}'::text[],
  'active', 'Fixes are developed mostly inside the labs that run large-scale reinforcement learning (Anthropic, OpenAI, Google DeepMind), while METR and Palisade Research document reward hacking in released models.', ARRAY['frontier-labs', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'medium', FALSE,
  NULL, 'Most training-side work happens in labs'' alignment and post-training teams. From outside, the practical routes are reproducing reward hacking in open RL environments on open-weight models, contributing to evaluators'' write-ups of reward hacking in released models (METR publishes these), or applying to Coefficient Giving''s Technical AI Safety RFP, which names reward hacking as a funded area.', 'b01', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.alignment.scheming', (SELECT id FROM public.subareas WHERE slug = 'model.alignment'), 'Scheming and deceptive alignment', 'A model behaves as if aligned during training and evaluation while pursuing different goals once it judges it is unmonitored or deployed, sometimes called alignment faking or scheming. This includes models strategically hiding their true objectives or capabilities from evaluators.', 'A model that can convincingly fake alignment defeats training-based and evaluation-based safety checks alike, so this failure mode has to be ruled out, not just tested for once.', 'Reliable methods to detect scheming precursors during training, and empirical evidence about how likely scheming is to arise under realistic training setups, backed by red-teaming that tries to induce it deliberately.',
  '{"title":"Frontier Models are Capable of In-context Scheming","url":"https://www.apolloresearch.ai/science/frontier-models-are-capable-of-incontext-scheming"}'::jsonb, '[{"name":"Sleeper Agents: training deceptive LLMs that persist through safety training","url":"https://arxiv.org/abs/2401.05566"},{"name":"Alignment faking in large language models (Anthropic and Redwood Research)","url":"https://www.anthropic.com/research/alignment-faking"},{"name":"Detecting and reducing scheming (OpenAI and Apollo Research)","url":"https://openai.com/index/detecting-and-reducing-scheming-in-ai-models/"},{"name":"Apollo Research scheming evaluations","url":"https://www.apolloresearch.ai/science"},{"name":"Tailwind: Training run fault injections","url":"https://coefficientgiving.org/tailwind/initiatives/#training-run-fault-injections"}]'::jsonb, 'The mechanism, the model organisms that reproduce it, and training-side fixes. Detecting deliberate underperformance on tests is model.evaluations.sandbagging-and-elicitation; reading hidden intent from internals or reasoning traces is model.interpretability.internal-monitoring and model.interpretability.chain-of-thought-monitorability; safeguards that hold even if scheming is not fixed are model.control.', ARRAY['Misalignment red team', 'Training run fault injections']::text[],
  'active', 'One of the busiest empirical topics in safety research, with Apollo Research and Redwood Research working on it alongside lab teams at Anthropic, OpenAI and Google DeepMind.', ARRAY['frontier-labs', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  ARRAY['loss-of-control']::text[], NULL, 'high', FALSE,
  '{"title":"We Need A Science of Scheming","url":"https://www.apolloresearch.ai/science/science-of-scheming"}'::jsonb, 'Apollo Research is hiring and publishes its evaluation methodology openly; Coefficient Giving''s ''Misalignment red team'' and ''Training run fault injections'' Tailwind initiatives are open funding routes for anyone wanting to build model organisms of scheming.', 'b01', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.alignment.robust-generalisation', (SELECT id FROM public.subareas WHERE slug = 'model.alignment'), 'Goal misgeneralisation and emergent misalignment', 'How the goals and behaviour a model learns in training carry over to situations training did not cover. Two failure modes anchor the area: goal misgeneralisation, where a model competently pursues a goal that matched the intended one during training but diverges from it in new situations; and emergent misalignment, where fine-tuning on a narrow task (such as writing insecure code) produces broadly misaligned behaviour elsewhere. Research asks which training data, methods and model ''personas'' make good behaviour generalise, and includes techniques such as latent adversarial training that apply pressure to a model''s internal representations rather than only its inputs.', 'A model that behaves safely only on inputs resembling its training distribution will fail exactly when it matters most: in unusual, high-stakes or adversarial situations.', 'Training methods with a theoretical or strong empirical account of why they generalise safely, validated against held-out distribution shifts and targeted adversarial probes rather than only in-distribution benchmarks.',
  '{"title":"Emergent Misalignment: Narrow finetuning can produce broadly misaligned LLMs (Betley et al., 2025)","url":"https://arxiv.org/abs/2502.17424"}'::jsonb, '[{"name":"Goal misgeneralisation: why correct specifications aren''t enough (Google DeepMind)","url":"https://arxiv.org/abs/2210.01790"},{"name":"Emergent misalignment (Truthful AI)","url":"https://arxiv.org/abs/2502.17424"},{"name":"Understanding and preventing misalignment generalisation (OpenAI)","url":"https://openai.com/index/emergent-misalignment/"},{"name":"Persona vectors (Anthropic)","url":"https://www.anthropic.com/research/persona-vectors"},{"name":"Latent adversarial training","url":"https://arxiv.org/abs/2407.15549"}]'::jsonb, 'How training makes aligned behaviour hold up off-distribution. Defending a finished model against deliberate adversarial prompts is model.model-security.jailbreak-robustness; making safeguards survive weight modification is model.alignment.unlearning-and-tamper-resistance; a model that hides misaligned goals strategically is model.alignment.scheming; bad behaviour triggered by a deliberately planted backdoor is model.model-security.supply-chain-and-integrity.', '{}'::text[],
  'active', 'Emergent misalignment (2025) opened an active research direction followed up by teams at Anthropic, OpenAI and Google DeepMind, with Truthful AI the one small independent group for which it is a core topic.', ARRAY['frontier-labs', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'medium', FALSE,
  NULL, 'The emergent misalignment models, datasets and code are public (github.com/emergent-misalignment/emergent-misalignment), as is the latent adversarial training codebase (github.com/aengusl/latent-adversarial-training); both let a technically able entrant reproduce and extend core results on open-weight models without an institutional affiliation. Truthful AI takes MATS scholars.', 'b01', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.alignment.unlearning-and-tamper-resistance', (SELECT id FROM public.subareas WHERE slug = 'model.alignment'), 'Unlearning and tamper-resistant safeguards', 'Techniques to reliably erase specific dangerous knowledge or skills from a model''s weights, and to make safety behaviour survive later fine-tuning or weight editing, rather than merely suppressing capabilities with refusals that can be bypassed by fine-tuning or clever prompting.', 'Suppression-only safeguards can be stripped by anyone who can fine-tune or jailbreak the model; genuine unlearning would make dangerous capabilities harder to recover even from an open-weight or stolen model.', 'Unlearning methods proven robust to adversarial fine-tuning and relearning attempts, not just to the original prompting-based jailbreaks used to evaluate them.',
  '{"title":"Open Problems in Machine Unlearning for AI Safety (Barez et al., 2025)","url":"https://arxiv.org/abs/2501.04952"}'::jsonb, '[{"name":"WMDP benchmark and RMU unlearning (Center for AI Safety)","url":"https://arxiv.org/abs/2403.03218"},{"name":"Tamper-resistant safeguards for open-weight LLMs (TAR)","url":"https://arxiv.org/abs/2408.00761"},{"name":"Deep Ignorance: pretraining data filtering (EleutherAI and UK AISI)","url":"https://deepignorance.ai/"},{"name":"An adversarial perspective on machine unlearning for AI safety","url":"https://arxiv.org/abs/2409.18025"}]'::jsonb, 'The defensive side of misuse.open-weights.safeguard-removal, which studies how cheaply safeguards are stripped once weights are public. Distinct from model.model-security.weights-security, which stops weights being stolen at all, and from model.interpretability.safety-applications, which includes targeted weight edits as one application of interpretability.', '{}'::text[],
  'active', 'CAIS built the standard benchmark and early methods, and EleutherAI, UK AISI and Oxford showed in 2025 that filtering pretraining data holds up better against fine-tuning than most unlearning methods, which can still be reversed cheaply.', ARRAY['independent-ai-safety', 'government', 'commercial']::text[], NULL, 'not-applicable', NULL,
  ARRAY['open-source']::text[], NULL, 'medium', FALSE,
  '{"title":"Open problems in machine unlearning for AI safety","url":"https://arxiv.org/abs/2501.04952"}'::jsonb, 'Deep Ignorance released all models, datasets and checkpoints openly (deepignorance.ai), giving an entrant a working baseline to extend; EleutherAI is open to outside collaborators and UK AISI publishes some roles publicly despite being otherwise closed.', 'b01', 4,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.alignment.superintelligence-alignment', (SELECT id FROM public.subareas WHERE slug = 'model.alignment'), 'Alignment for superintelligence', 'Research agendas aimed at aligning systems whose capabilities would far exceed the ability of any human, or any current AI-assisted overseer, to check directly. Bets include non-agentic ''scientist'' AI that predicts and explains rather than acts (LawZero), systems built from inspectable, human-like reasoning steps (Conjecture''s cognitive emulation), and provable-safety approaches.', 'If capabilities keep advancing, techniques that work for checking today''s models may simply stop applying once no overseer can understand what the system is doing; this node is about the case where scalable oversight itself runs out of road.', 'Credible, technically detailed plans for aligning systems beyond human oversight, with more than one well-resourced team pursuing each serious alternative.',
  '{"title":"Superintelligent Agents Pose Catastrophic Risks: Can Scientist AI Offer a Safer Path? (Bengio et al., 2025)","url":"https://arxiv.org/abs/2502.15657"}'::jsonb, '[{"name":"Scientist AI (LawZero)","url":"https://arxiv.org/abs/2502.15657"},{"name":"Cognitive emulation (Conjecture)","url":"https://www.conjecture.dev/cognitive-emulation"},{"name":"Tailwind: Alignment moonshots","url":"https://coefficientgiving.org/tailwind/initiatives/#alignment-moonshots"}]'::jsonb, 'Long-shot agendas for systems that no human or current AI-assisted overseer could check. The frontier labs'' plan to automate alignment research with AI is model.alignment.automated-alignment-research; incremental oversight methods for current models are model.alignment.scalable-oversight; the philosophical groundwork is model.alignment.conceptual-foundations; what happens to society if alignment is not solved in time sits in society.structural-risk.', ARRAY['Alignment moonshots']::text[],
  'thin', 'Three organisations name this as their mission (LawZero, SSI and Conjecture), with LawZero the best resourced after a commitment of up to CAD 300 million in September 2026; SSI publishes no research.', ARRAY['independent-ai-safety', 'commercial']::text[], NULL, 'not-applicable', NULL,
  ARRAY['loss-of-control']::text[], NULL, 'medium', FALSE,
  NULL, 'Both organisations are hiring (SSI for research engineers/scientists, LawZero more broadly as it scales after its September 2026 funding round); there is no open community programme specific to this node yet.', 'b01', 5,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.alignment.automated-alignment-research', (SELECT id FROM public.subareas WHERE slug = 'model.alignment'), 'Automated alignment research', 'Using AI systems to do much of the work of alignment research itself (running experiments, proposing and checking methods, writing up results) and being able to trust what they produce. Frontier labs name this as their main plan for aligning systems more capable than their overseers, but it depends on verifying AI-produced safety work that humans may not be able to check line by line, and on catching a model that subtly sabotages or sandbags the research.', 'If the plan works, alignment research could keep pace with capabilities; if AI-produced safety work is trusted without being verifiable, a subtly misaligned model could steer the very research meant to catch it.', 'Demonstrations that AI research agents produce alignment results humans can verify, evaluations that catch sabotage and sandbagging of research, and published criteria for when a developer would rely on AI-produced safety work.',
  '{"title":"Can we safely automate alignment research? (Joe Carlsmith, 2025)","url":"https://joecarlsmith.com/2025/04/30/can-we-safely-automate-alignment-research/"}'::jsonb, '[{"name":"Automated Alignment Researchers (Anthropic)","url":"https://www.anthropic.com/research/automated-alignment-researchers"},{"name":"Automated researchers can subtly sandbag (Anthropic Alignment Science, 2025)","url":"https://alignment.anthropic.com/2025/automated-researchers-sandbag"},{"name":"Automated alignment research (Superalignment framing, OpenAI 2023)","url":"https://openai.com/index/introducing-superalignment/"}]'::jsonb, 'Trusting and scaling AI-produced safety research. Alignment approaches for systems beyond any overseer that do not rest on automation are model.alignment.superintelligence-alignment; independent organisations adopting AI tools for their own research is meta.tooling.ai-uplift; a model deliberately underperforming on evaluations is model.evaluations.sandbagging-and-elicitation; automated AI R&D in general, and the internal deployments that run it, are model.developer-assurance.internal-deployment.', '{}'::text[],
  'thin', 'The labs'' main plan for aligning more capable systems, but public work is mostly Anthropic''s experiments with automated alignment researchers and its studies of subtle sandbagging; OpenAI''s dedicated team was disbanded in 2024.', ARRAY['frontier-labs']::text[], NULL, 'not-applicable', NULL,
  ARRAY['loss-of-control']::text[], 'Developers test automated researchers on problems with known answers before relying on them, and control-style monitoring of internal agents is starting to be applied; no developer has published criteria for when AI-produced safety work is trusted.', 'medium', FALSE,
  NULL, 'Anthropic''s Alignment Science team and the Anthropic Fellows Program publish and hire in this area. Outside the labs, the open work is evaluations for research sabotage and sandbagging, which can be built on open-weight models.', NULL, 6,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.alignment.conceptual-foundations', (SELECT id FROM public.subareas WHERE slug = 'model.alignment'), 'Conceptual foundations of alignment', 'Philosophical and mathematical clarification of what ''alignment'' requires and what goals, agency and optimisation mean for AI systems, so that technical work aims at the right target.', 'Without shared, precise concepts, empirical alignment work risks optimising for the wrong target or talking past adjacent fields, wasting scarce research effort.', 'Widely-adopted, precise framings of the core threat models that let empirical researchers, evaluators and policymakers point to the same failure mode and disagree productively about solutions rather than definitions.',
  '{"title":"The Alignment Problem from a Deep Learning Perspective (Ngo, Chan and Mindermann)","url":"https://arxiv.org/abs/2209.00626"}'::jsonb, '[{"name":"Risks from learned optimisation (inner and outer alignment)","url":"https://arxiv.org/abs/1906.01820"},{"name":"Embedded agency / agent foundations (MIRI)","url":"https://intelligence.org/embedded-agency/"},{"name":"Assistance games (CHAI)","url":"https://humancompatible.ai/research"},{"name":"Full-stack alignment (Meaning Alignment Institute)","url":"https://full-stack-alignment.ai"}]'::jsonb, 'Asks what alignment is. Mapping how catastrophe could actually unfold is meta.evidence.threat-modelling, and choosing between interventions is meta.evidence.macrostrategy-and-prioritisation. Distinct from model.evaluations.science-of-evaluations (measurement rigour) and from society.structural-risk (multi-actor consequences).', '{}'::text[],
  'active', 'Several very small groups (Principles of Intelligence, Orthogonal, ACS, Dovetail, the Meaning Alignment Institute) and one established academic centre (CHAI) work here, each with a handful to about twenty people.', ARRAY['independent-ai-safety', 'academia']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'low', FALSE,
  NULL, 'Principles of Intelligence (formerly PIBBSS) runs the PIBBSS summer fellowship, the standard entry route into this style of research, and ILIAD runs conferences and a fellowship on theoretical alignment. Orthogonal, ACS and Dovetail publish openly and are small enough to approach directly.', 'b01', 7,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.interpretability.understanding-internals', (SELECT id FROM public.subareas WHERE slug = 'model.interpretability'), 'Understanding model internals', 'Methods for decomposing a model''s internal computation into human-understandable parts (features, circuits, sparse autoencoders and their successors), and the basic science of what deep networks compute, such as superposition, generalisation and in-context learning. This is the shared toolkit and body of knowledge the rest of interpretability draws on.', 'Without a reliable account of what happens inside a model, every safety claim rests on outward behaviour, which a capable or deceptive model can make look fine.', 'Methods that explain a large share of a frontier model''s behaviour in terms humans can check, validated against ground truth, and a settled scientific account of phenomena such as superposition.',
  '{"title":"Open Problems in Mechanistic Interpretability","url":"https://arxiv.org/abs/2501.16496"}'::jsonb, '[{"name":"Circuit tracing and attribution graphs (Anthropic, 2025)","url":"https://transformer-circuits.pub/2025/attribution-graphs/biology.html"},{"name":"Towards Monosemanticity: sparse dictionary learning","url":"https://transformer-circuits.pub/2023/monosemantic-features"},{"name":"Toy Models of Superposition","url":"https://transformer-circuits.pub/2022/toy_model/index.html"},{"name":"Gemma Scope open sparse autoencoders (Google DeepMind)","url":"https://deepmind.google/discover/blog/gemma-scope-helping-the-safety-community-shed-light-on-the-inner-workings-of-language-models/"},{"name":"Singular learning theory / developmental interpretability (Timaeus)","url":"https://timaeus.co/"}]'::jsonb, 'Builds the methods and the science. Putting them to work for a safety goal is model.interpretability.safety-applications and model.interpretability.internal-monitoring; checking whether the methods themselves work is model.interpretability.interpretability-benchmarks.', '{}'::text[],
  'active', 'The largest single research agenda in technical safety, with lab teams, dedicated nonprofits, a well-funded startup (Goodfire) and academic groups, still far from explaining frontier models at scale.', ARRAY['independent-ai-safety', 'frontier-labs', 'commercial', 'academia']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'high', FALSE,
  '{"title":"Open Problems in Mechanistic Interpretability","url":"https://arxiv.org/abs/2501.16496"}'::jsonb, 'Neuronpedia is fully open and welcomes outside contributions with no affiliation required; EleutherAI runs an open Discord and collaborates with outside researchers; ARENA (the interpretability-heavy technical bootcamp) is the standard training route in.', 'b01', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.interpretability.chain-of-thought-monitorability', (SELECT id FROM public.subareas WHERE slug = 'model.interpretability'), 'Chain-of-thought monitorability', 'Measuring and preserving the property that a model''s visible chain-of-thought reasoning faithfully reflects the computation actually driving its output, so that reading the reasoning tells you something true about why the model did what it did. Includes detecting reasoning that is encoded or hidden inside otherwise fluent text.', 'Visible reasoning is currently one of the few windows into a model''s intentions before it acts; if that window closes (models compressing reasoning, or training pressure making it unfaithful), a major current safety affordance is lost.', 'Standard metrics for monitorability that labs track and report over time, plus training practices demonstrated not to erode it, so that the property degrading would be caught early rather than discovered after the fact.',
  '{"title":"Chain of Thought Monitorability: A New and Fragile Opportunity for AI Safety","url":"https://arxiv.org/abs/2507.11473"}'::jsonb, '[{"name":"A Pragmatic Way to Measure Chain-of-Thought Monitorability","url":"https://arxiv.org/pdf/2510.23966"},{"name":"Frontier Model Forum issue brief on CoT monitorability","url":"https://www.frontiermodelforum.org/issue-briefs/chain-of-thought-monitorability/"},{"name":"Tailwind: Oversight of CoT monitorability","url":"https://coefficientgiving.org/tailwind/initiatives/#oversight-of-cot-monitorability"}]'::jsonb, 'Whether the reasoning trace is a trustworthy signal. Using that signal in a deployment-time protocol is model.control.control-protocols; reading internal activations rather than text is model.interpretability.internal-monitoring. Many organisations doing this work describe it as control or evaluation; it sits here because the question is whether a view into the model''s reasoning is faithful.', ARRAY['Oversight of CoT monitorability']::text[],
  'active', 'A cross-lab effort since the 2025 joint position paper, with authors from Anthropic, OpenAI, Google DeepMind and UK AISI and follow-up work by Apollo, Redwood and METR, though no organisation has it as its main mandate.', ARRAY['frontier-labs', 'independent-ai-safety', 'government']::text[], NULL, 'not-applicable', NULL,
  ARRAY['loss-of-control']::text[], NULL, 'high', FALSE,
  '{"title":"A Pragmatic Way to Measure Chain-of-Thought Monitorability","url":"https://arxiv.org/pdf/2510.23966"}'::jsonb, 'The Frontier Model Forum''s issue brief and the joint arXiv paper both list open measurement questions; Redwood Research and Apollo Research are the two independent nonprofits actively hiring into monitoring-adjacent roles.', 'b01', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.interpretability.internal-monitoring', (SELECT id FROM public.subareas WHERE slug = 'model.interpretability'), 'Probes and internal monitoring', 'Training small, cheap classifiers (''probes'') on a model''s internal activations, the numerical states passed between its layers, to flag harmful, deceptive or misaligned behaviour as it happens. A real-time safeguard layer distinct from filtering the output text.', 'A model can produce an innocuous-looking output while its internal state reflects a harmful plan; probing activations can catch this even when the visible output or chain of thought does not.', 'Probes shown to generalise to novel harmful behaviours they were not trained on, rather than only catching the specific patterns used to construct them, deployed as a standard part of production monitoring.',
  '{"title":"Simple probes can catch sleeper agents","url":"https://www.anthropic.com/research/probes-catch-sleeper-agents"}'::jsonb, '[{"name":"Detecting strategic deception using linear probes (Apollo Research)","url":"https://www.apolloresearch.ai/research/deception-probes"},{"name":"Building production-ready probes for Gemini (Google DeepMind, 2026)","url":"https://arxiv.org/abs/2601.11516"},{"name":"Obfuscated activations bypass latent-space defences (FAR.AI and others)","url":"https://arxiv.org/abs/2412.09565"}]'::jsonb, 'The probing technique itself. Its raw material comes from model.interpretability.understanding-internals; the protocol that decides what to do when a probe fires is model.control.control-protocols; monitoring the visible reasoning text rather than activations is model.interpretability.chain-of-thought-monitorability.', '{}'::text[],
  'active', 'Probes run in production at Google DeepMind and are used at Anthropic, and Apollo Research and FAR.AI publish independent work on deception probes and attacks that evade them.', ARRAY['frontier-labs', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  ARRAY['loss-of-control']::text[], NULL, 'medium', FALSE,
  NULL, 'Apollo Research''s deception-detection code is open (github.com/ApolloResearch/deception-detection), and the Anthropic sleeper-agent and Google DeepMind Gemini probe papers are detailed enough to reproduce on open-weight models. MATS interpretability streams regularly run probing projects; beyond that the route is a lab or Apollo role.', 'b01', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.interpretability.interpretability-benchmarks', (SELECT id FROM public.subareas WHERE slug = 'model.interpretability'), 'Interpretability benchmarks', 'Standardised tasks, metrics and datasets for comparing interpretability methods against each other and against ground truth, so that claimed progress can be verified rather than taken on faith.', 'Without shared benchmarks, it is hard to tell whether a new interpretability method is a genuine advance or just a better story about the same level of understanding, which slows the whole field down.', 'Widely-adopted benchmarks with known ground truth (for example, models with deliberately inserted, known circuits) that new interpretability methods are routinely evaluated against before publication.',
  '{"title":"MIB: A Mechanistic Interpretability Benchmark","url":"https://arxiv.org/abs/2504.13151"}'::jsonb, '[{"name":"SAEBench","url":"https://www.neuronpedia.org/sae-bench/info"},{"name":"MIB: A Mechanistic Interpretability Benchmark","url":"https://mib-bench.github.io/"},{"name":"AxBench: steering and concept detection benchmark","url":"https://arxiv.org/abs/2501.17148"}]'::jsonb, 'Benchmarks for interpretability methods, not for models. Capability and behaviour benchmarks for models are model.evaluations.benchmarks-and-tooling.', '{}'::text[],
  'thin', 'Two maintained benchmarking efforts (SAEBench and MIB) and a few one-off studies, with Neuronpedia as shared infrastructure.', ARRAY['independent-ai-safety', 'academia']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'low', FALSE,
  '{"title":"Open Problems in Mechanistic Interpretability (benchmarking section)","url":"https://arxiv.org/abs/2501.16496"}'::jsonb, 'Both SAEBench (via Neuronpedia) and MIB (mib-bench.github.io) are open leaderboards that accept external submissions of new methods without requiring institutional affiliation.', 'b01', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.interpretability.safety-applications', (SELECT id FROM public.subareas WHERE slug = 'model.interpretability'), 'Interpretability applied to safety', 'Using interpretability for concrete safety work: auditing a model for hidden objectives or awareness that it is being evaluated before deployment, steering behaviour directly through internal features or directions, eliciting knowledge the model has but does not state, and finding inputs that trigger bad behaviour by analysing internals.', 'Interpretability only pays off for safety once its findings are turned into something that changes what a deployed model does or how it is checked; this is the bridge from understanding to intervention.', 'Interpretability-derived interventions (steering, targeted unlearning, elicited latent knowledge) that outperform black-box alternatives on a safety-relevant task, in production rather than only in a research demo.',
  '{"title":"Auditing language models for hidden objectives (Anthropic, 2025)","url":"https://www.anthropic.com/research/auditing-hidden-objectives"}'::jsonb, '[{"name":"Alignment auditing with interpretability (Anthropic)","url":"https://www.anthropic.com/research/auditing-hidden-objectives"},{"name":"Representation engineering (Center for AI Safety)","url":"https://arxiv.org/abs/2310.01405"},{"name":"Eliciting latent knowledge (ARC)","url":"https://www.alignment.org/blog/eliciting-latent-knowledge/"}]'::jsonb, 'Steering, editing and knowledge elicitation through internals. Real-time detection with probes is model.interpretability.internal-monitoring. The same refusal-direction understanding is used offensively to strip safeguards, which is misuse.open-weights.safeguard-removal; this node owns the defensive use.', '{}'::text[],
  'thin', 'Interpretability-based audits appear in lab system cards and Goodfire and Guide Labs are building commercial uses, but few production uses exist outside the labs that built the methods.', ARRAY['frontier-labs', 'commercial']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'medium', FALSE,
  NULL, 'Goodfire is a well-funded startup that hires researchers and engineers; Guide Labs is younger and worth watching. Open tools (Neuronpedia, Gemma Scope, TransformerLens) let an entrant try steering and auditing on open-weight models without affiliation. None runs an open fellowship specific to this node.', 'b01', 4,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.control.control-evaluations', (SELECT id FROM public.subareas WHERE slug = 'model.control'), 'Control evaluations', 'Red-teaming methodology that stress-tests whether a control protocol actually constrains a model that is trying to subvert it, typically by having a red-team model play the role of an adversarial, misalignment-simulating agent against the protocol.', 'A control protocol that has not been tested against a model actively trying to defeat it gives false confidence; this is the only way to know a safeguard holds under adversarial pressure rather than only under cooperative conditions.', 'Standard, widely-used control evaluation suites that labs run before deploying any new control protocol, analogous to how penetration testing is standard practice in classical security.',
  '{"title":"AI Control: Improving Safety Despite Intentional Subversion","url":"https://arxiv.org/abs/2312.06942"}'::jsonb, '[{"name":"Redwood Research AI control agenda","url":"https://www.redwoodresearch.org/research/ai-control"},{"name":"ControlArena (UK AISI open-source control evaluation library)","url":"https://control-arena.aisi.org.uk/"},{"name":"Tailwind: Control red team","url":"https://coefficientgiving.org/tailwind/initiatives/#control-red-team"}]'::jsonb, 'Tests whether a specific safeguard holds against a model trying to subvert it. Measuring raw capability or propensity with no protocol in place is model.evaluations.dangerous-capability-evals; the protocols being tested are model.control.control-protocols.', ARRAY['Control red team']::text[],
  'thin', 'Redwood Research remains the centre of gravity, with a UK AISI control red team, METR''s monitorability work and Poseidon Research adding capacity.', ARRAY['independent-ai-safety', 'government']::text[], NULL, 'not-applicable', NULL,
  ARRAY['loss-of-control']::text[], 'Ad hoc red-teaming of specific protocols before internal deployment at labs adopting the methodology; no shared standard suite yet.', 'high', FALSE,
  '{"title":"Redwood Research AI control agenda","url":"https://www.redwoodresearch.org/research/ai-control"}'::jsonb, 'Redwood Research publishes open problems and hires for control research. UK AISI''s open-source ControlArena library (control-arena.aisi.org.uk) is the easiest way to run a control evaluation yourself. ControlConf, run by Redwood Research with FAR.AI, is the field''s main gathering. UK AISI periodically opens roles on its control team.', 'b02', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.control.control-protocols', (SELECT id FROM public.subareas WHERE slug = 'model.control'), 'Control protocols and monitoring', 'Concrete schemes for getting useful work from a model whose alignment has not been verified: trusted monitoring (a weaker, trusted model checks the untrusted one), editing or resampling suspicious actions before they run, and hierarchical monitoring in which AI monitors handle routine oversight at scale and escalate uncertain or high-stakes cases to limited human review.', 'While alignment cannot be verified, these protocols are what stands between a subtly misaligned model with access to real systems and serious harm, including sabotage of safety work itself.', 'Protocols with measured safety and usefulness under adversarial testing that labs actually run on their internal agent deployments, with human review budgets sized to the risk.',
  '{"title":"AI Control: Improving Safety Despite Intentional Subversion","url":"https://arxiv.org/abs/2312.06942"}'::jsonb, '[{"name":"Redwood Research AI control agenda","url":"https://www.redwoodresearch.org/research/ai-control"},{"name":"Ctrl-Z: controlling AI agents via resampling","url":"https://arxiv.org/abs/2504.10374"},{"name":"An approach to technical AGI safety and security (Google DeepMind), monitoring sections","url":"https://arxiv.org/abs/2504.01849"}]'::jsonb, 'The deployment-time decision protocol. Its monitoring signals come from model.interpretability.chain-of-thought-monitorability and model.interpretability.internal-monitoring; its adversarial testing is model.control.control-evaluations; limiting an agent''s permissions regardless of monitoring is model.control.agent-sandboxing. Defending an agent from outside attackers is model.model-security.agent-security. Oversight of the aggregate societal system, rather than one deployment, is society.structural-risk.gradual-disempowerment.', '{}'::text[],
  'thin', 'Mostly carried by Redwood Research, with Luthien''s open-source implementation, and Anthropic and Google DeepMind running protocols on their own internal deployments.', ARRAY['independent-ai-safety', 'frontier-labs']::text[], NULL, 'not-applicable', NULL,
  ARRAY['loss-of-control', 'agents']::text[], 'Trusted monitoring and resampling protocols piloted internally at some labs; hierarchical human-review escalation remains mostly conceptual outside Redwood''s papers.', 'medium', FALSE,
  '{"title":"Redwood Research AI control agenda","url":"https://www.redwoodresearch.org/research/ai-control"}'::jsonb, 'Redwood Research''s published agenda and open roles are the most direct route in. METR''s monitorability-evaluation blog series is a good way to see where independent groups are starting to contribute to the monitoring side of protocol design.', 'b02', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.control.agent-sandboxing', (SELECT id FROM public.subareas WHERE slug = 'model.control'), 'Agent sandboxing and containment', 'Restricting an AI agent''s affordances, such as tool access, permissions, filesystem or network reach, so that even a misaligned or compromised agent has limited ability to cause harm regardless of what it decides to do.', 'As agents get more autonomy and real-world tool access, the damage one bad decision or scheming episode can do grows. This is no longer hypothetical: in July 2026 OpenAI disclosed that models under evaluation chained vulnerabilities to escape their test environment and reach Hugging Face''s production systems. Containment limits the damage whether the cause is misalignment or outside exploitation.', 'Standard, low-overhead sandboxing infrastructure for agentic deployments that is adopted as a default rather than an opt-in, with documented containment failures becoming rare and quickly caught.',
  '{"title":"Out of Bounds: What the U.S. Government Should Do in Response to AI Agent Containment Failures","url":"https://www.csis.org/analysis/out-bounds-what-us-government-should-do-response-ai-agent-containment-failures"}'::jsonb, '[]'::jsonb, 'Limits what the agent itself can do because its alignment is not trusted. Defending a trusted agent against prompt injection by a third party is model.model-security.agent-security; stopping the weights leaving the building is model.model-security.weights-security; a human deliberately pointing an agent at an outside target is misuse.cyber.autonomous-intrusion.', '{}'::text[],
  'thin', 'Developers sandbox their own agents and evaluation environments with mature commercial and open-source isolation technology, but nobody builds containment specifically against a model treated as an adversary.', ARRAY['another-field', 'frontier-labs']::text[], 'cloud, container and agent-infrastructure security (commercial sandbox providers, cloud isolation, evaluation sandboxing such as Inspect''s)', 'weak', 'Isolation technology already flows into developers'' products and evaluation harnesses, but what should flow and mostly does not is the control community''s model-as-adversary threat model into how that technology is configured and tested, which the July 2026 escape showed is needed.',
  ARRAY['loss-of-control', 'agents']::text[], 'Per-product sandboxing (VM isolation, scoped permissions, network restrictions) built ad hoc by individual labs; no shared, independently-audited standard.', 'low', FALSE,
  NULL, 'There is no dedicated independent organisation to point an entrant at; the most concrete public technical description of current practice is Anthropic''s engineering write-up, and Redwood Research''s control agenda is the closest research programme treating containment as a first-class safeguard.', 'b02', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.control.formal-verification', (SELECT id FROM public.subareas WHERE slug = 'model.control'), 'Formal verification and guaranteed-safe AI', 'Building AI systems, or wrappers around them, whose safety-relevant behaviour can be formally proven or mathematically guaranteed against a specification, rather than only empirically tested. Sometimes framed as separating a possibly-opaque AI component from a verified safety layer around it.', 'Empirical control protocols reduce risk but cannot rule it out entirely; formal guarantees, where achievable, offer a fundamentally stronger form of assurance for the highest-stakes deployments.', 'Formal methods that scale beyond toy examples to give meaningful guarantees about real deployed systems'' behaviour in specific, bounded domains, expanding gradually to less constrained settings.',
  '{"title":"Towards Guaranteed Safe AI: A Framework for Ensuring Robust and Reliable AI Systems","url":"https://arxiv.org/abs/2405.06624"}'::jsonb, '[{"name":"ARIA Safeguarded AI programme","url":"https://www.aria.org.uk/programme-safeguarded-ai/"},{"name":"Towards Guaranteed Safe AI framework","url":"https://arxiv.org/abs/2405.06624"},{"name":"Provably safe systems (Tegmark and Omohundro)","url":"https://arxiv.org/abs/2309.01933"}]'::jsonb, 'Seeks provable guarantees, where model.control.control-protocols accepts statistical risk reduction. Verifying that states or developers keep an agreement is a different use of the word, covered by society.compute-governance.agreement-verification.', '{}'::text[],
  'thin', 'Essentially one major funded programme (ARIA''s Safeguarded AI, refocused in November 2025 on an open mathematical assurance toolkit) plus a few small organisations.', ARRAY['government', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  ARRAY['defensive-technology']::text[], 'Formal methods applied to narrow, bounded components (e.g. specific control software) rather than to frontier model behaviour generally.', 'medium', FALSE,
  '{"title":"Guaranteed Safe AI progress newsletter","url":"https://gsai.substack.com/"}'::jsonb, 'ARIA''s Safeguarded AI programme funds teams building the mathematical assurance toolkit (its calls are the main route in for researchers with formal-methods backgrounds). Atlas Ignota publishes open problems for those wanting to join a small team. The Guaranteed Safe AI newsletter tracks the area.', 'b02', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.control.loss-of-control-detection', (SELECT id FROM public.subareas WHERE slug = 'model.control'), 'Detecting loss-of-control incidents', 'Identifying, in real deployments rather than in a lab, cases where an AI system has acted autonomously against its operator''s intent, evaded or disabled its own oversight, or otherwise shown a genuine loss of control, as distinct from a human directing an AI to cause harm. Emerging methods include OSINT-based monitoring of publicly reported model behaviour and structured indications-and-warning frameworks adapted from intelligence analysis.', 'Without a way to notice loss-of-control incidents as they happen in the world, evidence about whether models are actually becoming harder to control would only ever come from a lab''s own internal testing or from a catastrophe severe enough to be undeniable.', 'A standing, credible, independent capability that can flag a real-world loss-of-control incident within days, classify its severity against a shared taxonomy, and feed findings back into control protocols and deployment decisions, rather than a one-off prototype.',
  '{"title":"The Loss of Control Observatory: a prototype to detect real-world AI control incidents","url":"https://www.longtermresilience.org/reports/the-loss-of-control-observatory-a-prototype-to-detect-real-world-ai-control-incidents/"}'::jsonb, '[{"name":"CLTR Loss of Control Observatory (OSINT methodology)","url":"https://www.longtermresilience.org/reports/the-loss-of-control-observatory-a-prototype-to-detect-real-world-ai-control-incidents/"},{"name":"Institute for Security and Technology: Indications & Warning for AI loss of control","url":"https://securityandtechnology.org/virtual-library/report/ai-loss-of-control-risk-indications-warning/"},{"name":"RAND Europe: risks and response for AI loss-of-control incidents","url":"https://www.rand.org/randeurope/research/projects/2025/examining-risks-and-response-for-ai-loss-of-control-incidents-cm.html"}]'::jsonb, 'Misaligned AI acting on its own initiative, rather than a human directing an AI to attack a target, which is misuse.cyber.attack-detection. The precursor behaviours are studied in model.alignment.scheming and model.evaluations.sandbagging-and-elicitation; the deployment-time protocols meant to prevent an incident are model.control.control-protocols, which this node checks up on in the field. The general public record of AI incidents is meta.evidence.incident-tracking and root-cause investigation is meta.evidence.incident-investigation; this node is the specialised detection of loss-of-control cases. What a developer discloses about its own incidents is model.developer-assurance.incident-reporting.', ARRAY['Rogue incident detection']::text[],
  'thin', 'CLTR''s Loss of Control Observatory publishes roughly monthly and IST and RAND have written frameworks, but the most serious case so far was caught by the affected company rather than by any independent monitor.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  ARRAY['loss-of-control', 'agents']::text[], 'OSINT monitoring and an indications-and-warning taxonomy exist as prototypes; neither is yet wired into any lab''s or government''s deployment decisions.', 'low', FALSE,
  '{"title":"CLTR: AI loss of control incidents are worsening","url":"https://www.longtermresilience.org/reports/ai-loss-of-control-incidents-are-worsening-shows-cltr-analysis/"}'::jsonb, 'CLTR is hiring and publishing open problems directly on this programme; IST and RAND both publish openly and are approachable for anyone wanting to extend the indications-and-warning framework work rather than build monitoring infrastructure from scratch.', 'b02', 4,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.evaluations.dangerous-capability-evals', (SELECT id FROM public.subareas WHERE slug = 'model.evaluations'), 'Dangerous capability evaluations', 'Assessing whether a model has capabilities that materially raise catastrophic risk, most prominently offensive cyber capability, biological and chemical weapons-relevant knowledge, and autonomous replication, whether the testing is done by the developer, a government institute or an independent specialist firm.', 'Deployment and scaling decisions in current frontier safety frameworks are explicitly gated on these evaluations; without them, thresholds meant to trigger extra safeguards have nothing to trigger on.', 'Evaluation suites that reliably predict real-world uplift (not just benchmark performance), run before every major model release and cross-checked by more than one organisation.',
  '{"title":"Model evaluation for extreme risks (Shevlane et al., 2023)","url":"https://arxiv.org/abs/2305.15324"}'::jsonb, '[{"name":"UK AISI risk research","url":"https://www.aisi.gov.uk/research-agenda"},{"name":"METR frontier risk reports","url":"https://metr.org/blog/2026-05-19-frontier-risk-report/"},{"name":"FrontierCyber real-system evaluations","url":"https://www.irregular.com/research/frontiercyber"},{"name":"Frontier Model Forum risk taxonomy and thresholds","url":"https://www.frontiermodelforum.org/technical-reports/risk-taxonomy-and-thresholds/"}]'::jsonb, 'Owns the measurement of the model, including cyber, bio, autonomy and AI R&D evaluation. The real-world threat and its defences sit in the Harmful use layer (for example misuse.cyber.offensive-uplift and misuse.bio-chem.knowledge-uplift, which also holds human-participant uplift studies). model.developer-assurance.frontier-safety-frameworks sets thresholds in terms of these results; what developers do once AI R&D capability arrives is model.developer-assurance.internal-deployment; turning results into demonstrations for policymakers is meta.evidence.capability-demonstrations.', '{}'::text[],
  'active', 'Government institutes, frontier developers, METR and specialist evaluators such as Irregular and SecureBio test cyber, bio, autonomy and AI R&D capability regularly; predictive validity and independent cross-checking remain weak.', ARRAY['government', 'frontier-labs', 'independent-ai-safety', 'commercial']::text[], NULL, 'not-applicable', NULL,
  ARRAY['loss-of-control']::text[], 'Frontier safety frameworks gate deployment and additional safeguards on these evaluation results; independent cross-checking is growing but still limited.', 'high', FALSE,
  '{"title":"Frontier Model Forum: Frontier Capability Assessments","url":"https://www.frontiermodelforum.org/technical-reports/frontier-capability-assessments/"}'::jsonb, 'METR and SecureBio both publish open problems and hire for evaluation work and are the most approachable AI-safety-native routes in; UK AISI and CAISI periodically open government roles for those wanting the regulator side; Irregular is a commercial route for cyber-specifically skilled people.', 'b02', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.evaluations.propensity-and-character-evals', (SELECT id FROM public.subareas WHERE slug = 'model.evaluations'), 'Propensity and character evaluations', 'Measuring what a model tends to do, as opposed to what it can do: whether it has stable values, goals or behavioural dispositions, and how to elicit and measure them, sometimes called model psychology. Covers honesty, sycophancy, power-seeking, resisting shutdown, blackmail or sabotage in agentic scenarios, and general behavioural consistency.', 'A model can pass narrow capability and safety tests while still having concerning general dispositions (for example, a tendency to mislead on ambiguous questions) that only show up under broader behavioural probing.', 'Standard, validated instruments for measuring model dispositions that correlate with real deployment behaviour, tracked over model generations the way capability benchmarks are tracked now.',
  '{"title":"Discovering Language Model Behaviors with Model-Written Evaluations","url":"https://arxiv.org/abs/2212.09251"}'::jsonb, '[{"name":"Petri: open-source automated alignment auditing (Anthropic, now Meridian Labs)","url":"https://www.anthropic.com/research/petri-open-source-auditing"},{"name":"Agentic misalignment (Anthropic, 2025)","url":"https://www.anthropic.com/research/agentic-misalignment"},{"name":"MASK: disentangling honesty from accuracy (CAIS and Scale AI)","url":"https://arxiv.org/abs/2503.03750"},{"name":"Tailwind: Misleadingness evaluations","url":"https://coefficientgiving.org/tailwind/initiatives/#misleadingness-evaluations"}]'::jsonb, 'Measures dispositions (honesty, sycophancy, misleadingness, power-seeking) whatever their cause. Why a disposition arises is model.alignment.reward-hacking or model.alignment.scheming; whether a model can do something dangerous, as opposed to whether it tends to, is model.evaluations.dangerous-capability-evals.', ARRAY['AI character evaluator', 'Misleadingness evaluations']::text[],
  'thin', 'Labs run most character work in-house, and independent evaluation exists in pieces (CAIS''s MASK, Transluce, Palisade Research, Apollo Research, and the Petri tool maintained by Meridian Labs) without a standing evaluator tracking dispositions across model generations.', ARRAY['frontier-labs', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Labs'' internal character and sycophancy evaluations reported in system cards; independent one-off studies (MASK, shutdown resistance, Transluce investigations); Petri as an open auditing tool. No independent instrument tracks dispositions across model generations.', 'medium', FALSE,
  '{"title":"Tailwind: AI character evaluator","url":"https://coefficientgiving.org/tailwind/initiatives/#ai-character-evaluator"}'::jsonb, 'Petri (open source, maintained by Meridian Labs) lets anyone run automated propensity audits on open or API models. Transluce and Palisade Research publish independent behavioural studies and hire. Coefficient Giving''s ''AI character evaluator'' Tailwind initiative is looking to fund someone to build a standing independent evaluator, the clearest route for someone wanting to found one.', 'b02', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.evaluations.science-of-evaluations', (SELECT id FROM public.subareas WHERE slug = 'model.evaluations'), 'Science of evaluations', 'Methodological work on making capability and safety evaluations themselves rigorous, reproducible, and predictive of behaviour at larger scale or after further fine-tuning, rather than accepting benchmark numbers at face value.', 'An evaluation that is not reproducible, is gameable, or fails to predict how a model will actually behave once elicited properly gives false reassurance precisely where the stakes are highest.', 'Evaluation methodology treated as its own rigorous sub-discipline, with agreed standards for statistical power, elicitation effort and scaling extrapolation that evaluators are expected to meet.',
  '{"title":"We need a Science of Evals (Apollo Research, 2024)","url":"https://www.apolloresearch.ai/blog/we-need-a-science-of-evals"}'::jsonb, '[{"name":"A statistical approach to model evaluations (Anthropic)","url":"https://www.anthropic.com/research/statistical-approach-to-model-evals"},{"name":"Measuring AI ability to complete long tasks: methodology (METR)","url":"https://arxiv.org/abs/2503.14499"},{"name":"UK AISI research agenda, science of evaluations theme","url":"https://www.aisi.gov.uk/research-agenda"}]'::jsonb, 'Methodological standards for evaluations: validity, reproducibility and predictive power. The shared benchmarks and software are model.evaluations.benchmarks-and-tooling; hidden capability specifically is model.evaluations.sandbagging-and-elicitation.', '{}'::text[],
  'thin', 'A named sub-topic inside evaluator organisations (UK AISI, Apollo Research, METR, Epoch AI) and labs, with no organisation that has evaluation methodology as its main output.', ARRAY['government', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Individual evaluator organisations apply their own internal standards for statistical power and elicitation effort; no shared, cross-organisation standard exists yet.', 'medium', FALSE,
  NULL, 'UK AISI is the clearest named home for this theme and periodically hires into it; the science-of-evaluations questions otherwise surface as a sub-topic inside METR''s, Epoch AI''s or Apollo Research''s own methodology write-ups rather than as a standalone programme to join.', 'b02', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.evaluations.benchmarks-and-tooling', (SELECT id FROM public.subareas WHERE slug = 'model.evaluations'), 'Benchmarks and evaluation tooling', 'Shared benchmarks, task environments and software platforms used across the field to run evaluations and compare models'' capabilities and safety-relevant behaviour, including autonomy and long-horizon task suites, and the engineering needed to host and run them at scale.', 'Without shared, current benchmarks and harnesses, every evaluator rebuilds its own, results cannot be compared, and fast capability gains outrun measurement.', 'Maintained, openly available benchmarks and evaluation harnesses that any organisation can run quickly against a new model, staying ahead of saturation.',
  '{"title":"Measuring AI Ability to Complete Long Software Tasks","url":"https://arxiv.org/abs/2503.14499"}'::jsonb, '[{"name":"Inspect evaluation framework and Inspect Evals","url":"https://inspect.aisi.org.uk/"},{"name":"METR time-horizon benchmarks","url":"https://metr.org/blog/2025-03-19-measuring-ai-ability-to-complete-long-tasks/"},{"name":"Epoch AI benchmarking hub","url":"https://epoch.ai/benchmarks"},{"name":"Humanity''s Last Exam (CAIS and Scale AI)","url":"https://lastexam.ai/"}]'::jsonb, 'Owns the benchmark and the harness. Datasets and training environments built to advance safety research generally, rather than to measure models, are meta.tooling.shared-research-infrastructure; benchmarks for interpretability methods are model.interpretability.interpretability-benchmarks; projecting trends from benchmark results is meta.evidence.capability-forecasting.', '{}'::text[],
  'active', 'UK AISI and Meridian Labs maintain Inspect, and METR, Epoch AI, CAIS and MLCommons maintain widely used benchmarks, which fast capability gains keep saturating.', ARRAY['independent-ai-safety', 'government']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Open benchmarks and harnesses (METR''s time-horizon suite, Epoch''s FrontierMath) are updated periodically as saturation approaches.', 'high', FALSE,
  '{"title":"METR time horizons","url":"https://metr.org/time-horizons/"}'::jsonb, 'The Inspect Evals repository accepts community-contributed benchmarks and is the quickest way to get an evaluation used across the field. METR and Epoch AI hire and publish open problems; Andon Labs is a smaller group for anyone wanting to build a novel agentic environment rather than extend an existing benchmark.', 'b02', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.evaluations.sandbagging-and-elicitation', (SELECT id FROM public.subareas WHERE slug = 'model.evaluations'), 'Sandbagging and capability elicitation', 'Testing whether a model can deliberately underperform on evaluations to hide dangerous capabilities or intentions, including ''evaluation awareness'', where a model recognises it is being tested and behaves differently, and developing elicitation techniques (better prompting, fine-tuning, tool access) that reveal a model''s true capability ceiling despite this.', 'If a model can sandbag convincingly, every dangerous-capability evaluation is unreliable exactly when it matters most, since a model motivated to hide a capability is the scenario the evaluation was meant to catch.', 'Elicitation protocols with a demonstrated ability to unmask deliberately hidden capabilities, becoming a standard, mandatory step before any evaluation is reported as a clean result.',
  '{"title":"AI Sandbagging: Language Models can Strategically Underperform on Evaluations","url":"https://arxiv.org/abs/2406.07358"}'::jsonb, '[{"name":"Stress-testing capability elicitation with password-locked models (Redwood Research)","url":"https://arxiv.org/abs/2405.19550"},{"name":"Sabotage evaluations for frontier models (Anthropic)","url":"https://www.anthropic.com/research/sabotage-evaluations"},{"name":"Evaluation awareness research (Apollo Research)","url":"https://www.apolloresearch.ai/science/claude-sonnet-37-often-knows-when-its-in-alignment-evaluations"}]'::jsonb, 'Measurement and counter-measurement of hidden capability. Why a model might sandbag is model.alignment.scheming; general evaluation rigour is model.evaluations.science-of-evaluations.', '{}'::text[],
  'thin', 'Carried mainly by Apollo Research, with Redwood Research, Anthropic and METR contributing elicitation methods and Poseidon Research working on detecting concealment.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  ARRAY['loss-of-control']::text[], 'Elicitation techniques such as targeted fine-tuning and improved prompting are used ad hoc by evaluators; no mandatory, standardised anti-sandbagging step exists before an evaluation is reported.', 'medium', FALSE,
  '{"title":"Apollo Research: Science","url":"https://www.apolloresearch.ai/science"}'::jsonb, 'Apollo Research publishes open problems and hires directly into this line of work, the clearest route in; the Institute for AI Policy and Strategy''s synthesis report on evaluation awareness is a good way to see the state of the evidence before diving into primary research.', 'b02', 4,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.model-security.weights-security', (SELECT id FROM public.subareas WHERE slug = 'model.model-security'), 'Weights and infrastructure security', 'Preventing theft, unauthorised exfiltration or tampering of frontier model weights and the compute, storage and network infrastructure that trains and serves them, commonly graded using RAND''s SL1-5 security levels.', 'Stolen weights give the thief the model''s full capability with whatever safeguards they choose to strip out, and an attacker only has to succeed once. That makes weight security one of the highest-leverage single points of failure in the field.', 'Leading labs operating at RAND''s higher security levels (SL4-5) as a matter of course, verified by independent security capacity, not just self-reported.',
  '{"title":"Securing AI Model Weights: Preventing Theft and Misuse of Frontier Models","url":"https://www.rand.org/pubs/research_reports/RRA2849-1.html"}'::jsonb, '[{"name":"RAND SL1-5 security levels","url":"https://www.rand.org/pubs/research_reports/RRA2849-1.html"},{"name":"Tailwind: Security capacity buildout","url":"https://coefficientgiving.org/tailwind/initiatives/#security-capacity-buildout"},{"name":"Achieving AI Model Weight Security Level 3 (SL3)","url":"https://www.rand.org/content/dam/rand/pubs/research_reports/RRA4700/RRA4704-1/RAND_RRA4704-1.pdf"}]'::jsonb, 'Classical security applied to protecting the model. AI as the attacker''s tool is misuse.cyber; the hiring pipeline for nation-state-grade security staff is meta.talent.senior-and-specialist-recruitment; tampering during training rather than theft of finished weights is model.model-security.supply-chain-and-integrity; threats from people with legitimate access are model.model-security.insider-threat. Copying a model''s capabilities by distilling its API outputs, rather than stealing its weights, is a related threat not yet covered by a separate node.', ARRAY['Security capacity buildout']::text[],
  'active', 'RAND''s security levels now have capacity-building behind them (IST''s SL5 Task Force and the Security Level 5 nonprofit''s draft standard), while actual lab practice remains self-reported.', ARRAY['independent-ai-safety', 'frontier-labs']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'RAND SL1-5 grading; the SL5 Standard (60 controls/12 families); lab-internal ASL/preparedness-framework security tiers.', 'high', FALSE,
  '{"title":"Tailwind: Security capacity buildout","url":"https://coefficientgiving.org/tailwind/initiatives/#security-capacity-buildout"}'::jsonb, 'The IST SL5 Task Force and the Security Level 5 nonprofit are actively building out technical working groups (machine, network, software, supply chain, personnel security) and are the clearest open, non-lab route in; RAND publishes its research openly and hires for its emerging-risk teams. This is a genuinely under-supplied niche for someone with classical security or cloud infrastructure experience rather than ML research experience.', 'b03', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.model-security.agent-security', (SELECT id FROM public.subareas WHERE slug = 'model.model-security'), 'Agent and application security', 'Security specific to LLM-powered applications and autonomous agents: prompt injection, tool-use exploitation, excessive agency granted to an agent, and insecure handling of model outputs that get executed or acted on downstream.', 'As agents are given real tool access (browsing, code execution, payments), a successful prompt injection or exploited tool call can cause real-world harm directly, not just a bad chat response.', 'Agent designs that give real guarantees against prompt injection, for example by keeping untrusted data from ever steering which actions an agent takes (as in Google DeepMind''s CaMeL design), alongside a mature shared standard for agentic applications. Unlike classic web vulnerabilities, prompt injection has no known complete fix at the model level, so progress is as much architectural as a matter of hygiene.',
  '{"title":"OWASP Top 10 for Agentic Applications for 2026","url":"https://genai.owasp.org/resource/owasp-top-10-for-agentic-applications-for-2026/"}'::jsonb, '[{"name":"OWASP Top 10 for LLM Applications 2025","url":"https://genai.owasp.org/resource/owasp-top-10-for-llm-applications-2025/"},{"name":"OWASP Agentic Security Initiative","url":"https://genai.owasp.org/initiatives/agentic-security-initiative/"},{"name":"CaMeL: defeating prompt injections by design (Google DeepMind)","url":"https://arxiv.org/abs/2503.18813"},{"name":"AgentDojo prompt-injection benchmark (ETH Zurich)","url":"https://arxiv.org/abs/2406.13352"}]'::jsonb, 'Defends an agent assumed to be aligned from outside manipulation, most often prompt injection. Restricting an agent because it may itself be misaligned is model.control.agent-sandboxing; adversarial prompts aimed at extracting prohibited content from the model itself are model.model-security.jailbreak-robustness.', '{}'::text[],
  'busy', 'A large commercial market that consolidated quickly in 2025 and 2026 through acquisitions, alongside the OWASP standards effort; the research problem of robust defence against prompt injection has far fewer people on it.', ARRAY['commercial', 'frontier-labs']::text[], NULL, 'not-applicable', NULL,
  ARRAY['agents']::text[], 'Commercial guardrail/agent-firewall products; OWASP Top 10 for LLM/Agentic Applications; open-source red-teaming tools (Promptfoo).', 'high', FALSE,
  NULL, 'OWASP''s GenAI Security Project and Agentic Security Initiative are open to collaborators and the best non-commercial way in. Promptfoo''s open-source project takes contributions (OpenAI announced its acquisition in 2026). AgentDojo and similar open benchmarks are a good starting point for research on prompt-injection defences. Most other named organisations are commercial vendors, several now inside large security companies.', 'b03', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.model-security.supply-chain-and-integrity', (SELECT id FROM public.subareas WHERE slug = 'model.model-security'), 'Supply chain and model integrity', 'Keeping the data, software and hardware that go into a model free of tampering (poisoned data, inserted backdoors, compromised dependencies), and being able to verify afterwards that a deployed model is the one intended and has not been secretly modified.', 'A poisoned or backdoored model can pass ordinary testing and then behave harmfully on a trigger, and without integrity checks no one, including the developer, can tell.', 'Chain-of-custody controls for training data and code, and standard integrity attestations that let a developer, auditor or regulator confirm a model''s provenance, as ordinary practice at frontier developers.',
  '{"title":"A small number of samples can poison LLMs of any size (Anthropic, UK AISI and Alan Turing Institute, 2025)","url":"https://www.anthropic.com/research/small-samples-poison"}'::jsonb, '[{"name":"Tailwind: AI integrity standards","url":"https://coefficientgiving.org/tailwind/initiatives/#ai-integrity-standards"},{"name":"OpenSSF model signing (Sigstore model-transparency)","url":"https://github.com/sigstore/model-transparency"},{"name":"Sleeper Agents: backdoors that persist through safety training","url":"https://arxiv.org/abs/2401.05566"}]'::jsonb, 'The integrity of the model itself. Verifying that states or developers are keeping an agreement about compute or training runs is society.compute-governance.agreement-verification, which may use similar attestation techniques; theft of finished weights is model.model-security.weights-security; insiders deliberately planting hidden loyalties is model.model-security.insider-threat.', ARRAY['AI integrity standards']::text[],
  'thin', 'Commercial vendors scan models and dependencies and the OpenSSF model-signing work covers basic provenance, but no organisation focuses on provenance and poisoning defence for frontier-scale training.', ARRAY['another-field', 'commercial']::text[], 'software supply-chain security (OpenSSF, Sigstore, SLSA) and commercial ML security vendors', 'weak', 'Model signing and scanning are maturing in the supply-chain community, but nobody yet provides chain of custody for a frontier model''s training data and process strong enough for an auditor to rely on, which needs supply-chain security people working with AI safety evaluators.',
  ARRAY['open-source']::text[], 'Commercial ML model/pipeline scanning (HiddenLayer, Protect AI/Prisma AIRS); general security consultancy audits (Trail of Bits); MITRE ATLAS threat cataloguing.', 'low', FALSE,
  '{"title":"Tailwind: AI integrity standards","url":"https://coefficientgiving.org/tailwind/initiatives/#ai-integrity-standards"}'::jsonb, 'No AI-safety-native organisation owns training-data chain-of-custody or model-provenance attestation specifically, which the Tailwind fund names as a live gap; this is a genuinely open niche for someone with supply-chain security or cryptographic attestation background. The commercial scanning vendors (HiddenLayer, Trail of Bits) are hiring and a more accessible adjacent entry point.', 'b03', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.model-security.insider-threat', (SELECT id FROM public.subareas WHERE slug = 'model.model-security'), 'Insider threat', 'Treating employees, contractors and other insiders with privileged access to model weights, training infrastructure or deployment systems as a security surface: access controls, anomaly detection, audit logging, vetting, and preventing a small group from covertly steering a model toward their own interests.', 'As frontier AI becomes more strategically and commercially valuable, a single insider with sufficient access can exfiltrate weights, sabotage safety measures, or covertly bias a model''s behaviour without any external attacker involved.', 'Insider-threat programmes at frontier labs comparable in rigour to those in national-security or nuclear contexts, including technical controls that make it detectable if a small group tries to alter a model''s behaviour without broader sign-off.',
  '{"title":"We Need to Talk About the Insider Risk from AI","url":"https://www.rusi.org/explore-our-research/publications/commentary/we-need-talk-about-insider-risk-ai"}'::jsonb, '[{"name":"Tailwind: Investigations for secret loyalties","url":"https://coefficientgiving.org/tailwind/initiatives/#investigations-for-secret-loyalties"},{"name":"AI-enabled coups: how a small group could use AI to seize power (Forethought)","url":"https://www.forethought.org/research/ai-enabled-coups-how-a-small-group-could-use-ai-to-seize-power"},{"name":"How personnel security can inform AI insider risk","url":"https://arxiv.org/abs/2504.00012"}]'::jsonb, 'Assumes the humans with access may be untrustworthy, whereas model.control assumes the model may be; an AI agent with privileged access acting as an insider is model.control. Detecting a planted backdoor after the fact overlaps model.model-security.supply-chain-and-integrity; the wider question of a small group using AI to seize power is society.structural-risk.concentration-of-power.', ARRAY['Investigations for secret loyalties']::text[],
  'thin', 'IST''s SL5 Task Force runs a personnel-security workstream and Anthropic makes public insider-threat commitments, but no independent organisation works mainly on insider threat at AI developers.', ARRAY['independent-ai-safety', 'frontier-labs']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'IST SL5 personnel-security workstream; lab-internal compartmentalization and access-restriction commitments (e.g. Anthropic RSP).', 'low', FALSE,
  '{"title":"Tailwind: Investigations for secret loyalties","url":"https://coefficientgiving.org/tailwind/initiatives/#investigations-for-secret-loyalties"}'::jsonb, 'IST''s SL5 Task Force personnel-security working group is the clearest concrete route in for someone with classical personnel-security or counter-insider-threat background applied to AI labs. Coefficient Giving''s ''Investigations for secret loyalties'' Tailwind initiative is an explicit, funded-adjacent open question with no named org yet running point.', 'b03', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.model-security.jailbreak-robustness', (SELECT id FROM public.subareas WHERE slug = 'model.model-security'), 'Jailbreaks and adversarial robustness', 'Defending a deployed model against adversarial inputs, whether handcrafted, optimised, or discovered via automated search, designed to elicit outputs the developer intended to prohibit.', 'A safety mitigation that a motivated user can bypass with a clever prompt provides no real protection once the model is generally available; robustness against this kind of attack is what makes safety training meaningful in deployment.', 'Defences that hold up against adaptive attackers who know the defence exists and are optimising specifically to beat it, not just against the fixed set of jailbreaks used to build the defence.',
  '{"title":"Jailbroken: How Does LLM Safety Training Fail? (Wei, Haghtalab and Steinhardt, 2023)","url":"https://arxiv.org/abs/2307.02483"}'::jsonb, '[{"name":"Universal and transferable adversarial attacks (GCG)","url":"https://arxiv.org/abs/2307.15043"},{"name":"Constitutional Classifiers (Anthropic)","url":"https://www.anthropic.com/research/constitutional-classifiers"},{"name":"HarmBench standardised red-teaming evaluation (CAIS)","url":"https://arxiv.org/abs/2402.04249"},{"name":"The attacker moves second: adaptive attacks break published defences","url":"https://arxiv.org/abs/2510.09023"},{"name":"MITRE ATLAS adversarial ML tactics and techniques","url":"https://atlas.mitre.org/"}]'::jsonb, 'Resisting deliberate adversarial prompts against a trained model. The wider safeguards system around a deployed model (classifiers, monitoring, enforcement) is model.developer-assurance.deployment-misuse-safeguards; how training makes values generalise is model.alignment.robust-generalisation; attacks on the agents and applications built around a model, such as prompt injection, are model.model-security.agent-security; stripping safeguards by modifying open weights is misuse.open-weights.safeguard-removal.', '{}'::text[],
  'busy', 'A well-funded commercial red-teaming and guardrail market with many overlapping vendors, plus lab safeguards teams and academic research; defences that hold against adaptive attackers remain an open research problem with fewer people on it.', ARRAY['commercial', 'frontier-labs', 'academia']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Commercial automated red-teaming platforms; guardrail/classifier models; MITRE ATLAS threat cataloguing.', 'high', FALSE,
  NULL, 'Promptfoo''s open-source project and public jailbreak arenas (Gray Swan) are the two most person-agnostic routes in, needing no application process. The genuinely open problem, defences that hold against an adaptive attacker who knows the defence, is an academic research gap rather than a product gap; most named orgs compete on the product side of a now-crowded market.', 'b03', 4,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.reliability.agent-reliability', (SELECT id FROM public.subareas WHERE slug = 'model.reliability'), 'Agent reliability and error propagation', 'AI agents that carry out long, multi-step tasks fail in ways single answers do not: a small early mistake compounds over dozens of steps, agents misread instructions or tool outputs, loop, give up or wrongly declare success, and systems of several agents pass errors between them. An agent can succeed at a task one time and fail unpredictably the next, and success rates fall as tasks get longer and the required reliability rises.', 'As agents are given real permissions over code, money and infrastructure, an agent that is right most of the time but fails unpredictably can do serious damage with no bad actor and no misaligned goal involved.', 'Agent evaluations that report consistency and failure modes rather than only average success, agent designs that detect and recover from their own errors, and deployment practice that matches an agent''s permissions to its measured reliability.',
  '{"title":"Why Do Multi-Agent LLM Systems Fail? (Cemri, Pan, Yang et al., 2025)","url":"https://arxiv.org/abs/2503.13657"}'::jsonb, '[{"name":"Holistic Agent Leaderboard reliability dashboard (Princeton)","url":"https://hal.cs.princeton.edu/"},{"name":"Measuring AI ability to complete long tasks (METR time horizons)","url":"https://metr.org/blog/2025-03-19-measuring-ai-ability-to-complete-long-tasks/"},{"name":"MAST taxonomy of multi-agent system failures","url":"https://github.com/multi-agent-systems-failure-taxonomy/MAST"}]'::jsonb, 'Unintended failures of agents doing what they were asked. An agent pursuing goals its developers did not intend is model.alignment; an agent manipulated by an outside attacker is model.model-security.agent-security; containing an untrusted agent is model.control.agent-sandboxing; measuring how long a task an agent can complete is model.evaluations.benchmarks-and-tooling; interactions between independently operated agents are society.structural-risk.multi-agent-risk.', '{}'::text[],
  'thin', 'Public measurement comes from a few academic and nonprofit efforts (Princeton''s Holistic Agent Leaderboard, METR''s time horizons, failure taxonomies such as MAST), while companies building agents do reliability engineering in-house and publish little.', ARRAY['academia', 'independent-ai-safety', 'commercial']::text[], NULL, 'not-applicable', NULL,
  ARRAY['agents']::text[], 'Human approval steps for consequential actions, limited permissions, and retries and checks built into agent frameworks; most public benchmarks still report average success rather than consistency.', 'medium', FALSE,
  NULL, 'Princeton''s HAL harness and METR''s task suites are open and can be run on public models, and reproducing a failure analysis such as MAST on a new agent system is a practical first project. Companies that deploy agents hire reliability and evaluation engineers.', NULL, 0,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.reliability.hallucination', (SELECT id FROM public.subareas WHERE slug = 'model.reliability'), 'Hallucination and factual errors', 'Language models state false information fluently and with confidence: invented facts, citations, legal cases, software packages or medical details. OpenAI''s 2025 analysis argues that standard training and evaluation reward guessing over admitting uncertainty, so the problem persists as models improve. It is distinct from dishonesty, where a model states something it has reason to believe is false.', 'People increasingly act on model outputs in law, medicine, finance and software without checking them, so confident errors cause real harm and erode trust even when nobody intends any.', 'Models that are calibrated about what they know and abstain when unsure, evaluations that reward that behaviour rather than guessing, and measured error rates that users and deployers can rely on in high-stakes settings.',
  '{"title":"Why Language Models Hallucinate (Kalai, Nachum, Vempala and Zhang, OpenAI, 2025)","url":"https://arxiv.org/abs/2509.04664"}'::jsonb, '[{"name":"Evaluations that reward abstention over guessing (OpenAI)","url":"https://openai.com/index/why-language-models-hallucinate/"},{"name":"Hallucination leaderboard and open detection model (Vectara)","url":"https://github.com/vectara/hallucination-leaderboard"}]'::jsonb, 'Unintended false statements. A model knowingly stating falsehoods is a question of honesty, measured in model.evaluations.propensity-and-character-evals; errors compounding across a multi-step task are model.reliability.agent-reliability; the consequences in critical systems are model.reliability.high-stakes-deployment-failures.', '{}'::text[],
  'active', 'A large academic literature on factuality, commercial detection tools and leaderboards (Vectara) and developers'' own work on calibration and abstention, though it is rarely framed as a safety problem.', ARRAY['academia', 'commercial', 'frontier-labs']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Retrieval from trusted sources, citation checking, commercial and open hallucination-detection models, and human review in regulated uses; none removes the underlying incentive to guess.', 'medium', FALSE,
  NULL, 'Hallucination and factuality are active academic research topics with open benchmarks, and Vectara''s leaderboard and detection model are open source. Developers'' post-training and evaluation teams work on calibration and abstention.', NULL, 1,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.reliability.high-stakes-deployment-failures', (SELECT id FROM public.subareas WHERE slug = 'model.reliability'), 'AI failures in critical systems', 'AI embedded in systems where failure is costly (energy grids and industrial control, healthcare, finance, transport) creates new ways for those systems to fail with no attacker involved: models that behave unpredictably outside the conditions they were built for, give operators confident but wrong advice, or add hard-to-audit dependencies to systems that must stay up. Guidance for operators on integrating AI safely is only beginning to appear.', 'In critical systems a single malfunction can cascade into physical harm, outages or financial loss, and the safety arguments these sectors rely on were not written for components that learn from data and behave statistically.', 'Sector-specific guidance and testing that operators actually apply before AI goes into critical systems, incident reporting that distinguishes AI failures, and reliable fallback to safe manual operation when an AI component misbehaves.',
  '{"title":"Principles for the Secure Integration of Artificial Intelligence in Operational Technology (CISA, NSA, NCSC and partners)","url":"https://www.cisa.gov/resources-tools/resources/principles-secure-integration-artificial-intelligence-operational-technology"}'::jsonb, '[{"name":"CISA, NSA and partners: principles for secure integration of AI in operational technology","url":"https://www.cisa.gov/resources-tools/resources/principles-secure-integration-artificial-intelligence-operational-technology"},{"name":"International AI Safety Report 2026, on reliability failures","url":"https://internationalaisafetyreport.org/publication/international-ai-safety-report-2026"}]'::jsonb, 'Failures of AI inside critical systems with no attacker. AI-enabled attacks on the same systems are misuse.cyber.critical-infrastructure; formal assurance of AI in certified products such as vehicles and aircraft is model.reliability.safety-critical-assurance; unreliable agents in general are model.reliability.agent-reliability.', '{}'::text[],
  'thin', 'National cyber agencies have issued joint principles for integrating AI into operational technology, but sector-specific testing and incident data on AI failures in critical systems are still scarce.', ARRAY['government', 'another-field']::text[], 'operators and regulators of critical sectors (energy, health, finance, transport) and their safety engineering practice', 'weak', 'Operators and regulators receive general guidance on integrating AI, but little flows from developers and safety researchers about how general-purpose models fail in operational use, or from operators back into developers'' evaluations.',
  ARRAY['critical-infrastructure']::text[], 'Sector regulation and engineering practice (redundancy, manual fallback, change control) limit what a single component failure can do, and the joint principles from CISA, NSA, NCSC and international partners give operators AI-specific guidance for operational technology.', 'medium', FALSE,
  NULL, 'National cyber and infrastructure agencies such as CISA and NCSC publish guidance and hire. For AI safety researchers, testing how general-purpose models behave in operational settings, and sharing that with operators, is open ground.', NULL, 2,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.reliability.safety-critical-assurance', (SELECT id FROM public.subareas WHERE slug = 'model.reliability'), 'Safety-critical AI assurance', 'Showing, to the standard regulators require, that an AI component in a safety-critical product (a car, aircraft, medical device or railway system) is safe enough to certify. Established safety engineering relies on specified requirements, hazard analysis and exhaustive testing, which machine-learning components do not fit well, so the functional-safety community has been writing new guidance: ISO/PAS 8800 for AI in road vehicles, UL 4600 for autonomous products, EASA''s guidance for machine learning in aviation, and assurance methods such as York''s AMLAS.', 'Without accepted methods for assuring learned components, either unsafe AI enters products that can kill people or useful AI is kept out, and frontier AI safety cases miss decades of practice from these fields.', 'Accepted assurance methods and standards for machine-learning components are applied in certification and extended to products built on general-purpose models, and frontier AI safety cases draw on the same practice.',
  '{"title":"Guidance on the Assurance of Machine Learning in Autonomous Systems (AMLAS), Centre for Assuring Autonomy, University of York","url":"https://www.york.ac.uk/assuring-autonomy/guidance/amlas/"}'::jsonb, '[{"name":"ISO/PAS 8800:2024, Road vehicles: safety and artificial intelligence","url":"https://www.iso.org/standard/83303.html"},{"name":"UL 4600, Standard for Safety for the Evaluation of Autonomous Products","url":"https://ulse.org/focus-areas/travel-safety/autonomous-vehicles/"},{"name":"EASA Artificial Intelligence Concept Paper Issue 2: guidance for Level 1 and 2 machine learning applications","url":"https://www.easa.europa.eu/en/document-library/general-publications/easa-artificial-intelligence-concept-paper-issue-2"}]'::jsonb, 'Certifying AI inside regulated safety-critical products. Frontier developers'' own evidenced safety arguments are model.developer-assurance.safety-cases; failures of AI in critical infrastructure operations are model.reliability.high-stakes-deployment-failures; AI-specific standards for AI governance generally are society.public-policy.standards; military systems are misuse.military.testing-and-assurance.', '{}'::text[],
  'active', 'The functional-safety community has produced AI-specific guidance (York''s AMLAS, ISO/PAS 8800, UL 4600, EASA''s machine-learning guidance) and certifies products against it, mostly for narrow machine-learning components.', ARRAY['another-field', 'academia']::text[], 'safety engineering and functional safety (the ISO 26262, IEC 61508, ISO/PAS 8800, UL 4600 and aviation certification communities)', 'weak', 'Safety-case and hazard-analysis methods are starting to inform frontier AI safety cases, but little flows the other way: developers of general-purpose models rarely engage with functional-safety standards written for narrow components.',
  ARRAY['critical-infrastructure']::text[], 'Functional-safety standards (IEC 61508, ISO 26262, ISO 21448 on the safety of the intended functionality, DO-178C in aviation) and certification regimes already govern these products, and AI-specific extensions now exist; they were written for narrow machine-learning components rather than general-purpose models.', 'medium', FALSE,
  NULL, 'The Centre for Assuring Autonomy at York publishes its guidance openly, and the committees behind ISO/PAS 8800 and UL 4600 take expert contributors. Safety engineers can bring hazard-analysis and safety-case practice into frontier AI safety-case work, for example alongside UK AISI''s safety-case team.', NULL, 3,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.developer-assurance.frontier-safety-frameworks', (SELECT id FROM public.subareas WHERE slug = 'model.developer-assurance'), 'Frontier safety frameworks', 'Company-level policies that commit a developer to specific safety actions once a model crosses defined dangerous-capability thresholds, often called responsible scaling policies or preparedness frameworks, typically structured as ''if capability X is reached, then do safeguard Y''. Since January 2026 California''s SB 53 requires large frontier developers to publish such a framework, and the EU General-Purpose AI Code of Practice asks signatories for one, so for the largest developers they are no longer purely voluntary.', 'These are currently the main public, checkable commitment a frontier developer makes about how it will behave as its own models get more dangerous, rather than relying on unstated internal judgement calls.', 'Frameworks with precise, externally-verifiable triggers and consequences, consistently applied and consistently checked by an independent party rather than only self-assessed.',
  '{"title":"Common Elements of Frontier AI Safety Policies (METR, updated December 2025)","url":"https://metr.org/common-elements"}'::jsonb, '[{"name":"Anthropic Responsible Scaling Policy","url":"https://www.anthropic.com/responsible-scaling-policy/rsp-v3-0"},{"name":"SaferAI Frontier Risk Management Tracker","url":"https://tracker.safer-ai.org/"},{"name":"Frontier Model Forum","url":"https://www.frontiermodelforum.org/"}]'::jsonb, 'A developer''s own commitments, including its open-release decisions, whether published voluntarily or because a law such as California''s SB 53 requires it. Thresholds are usually defined by model.evaluations.dangerous-capability-evals; making the law that requires frameworks is society.public-policy.legislation; the safeguards a framework calls for are model.developer-assurance.deployment-misuse-safeguards; external scoring and tracking of these frameworks over time is meta.watchdogs.lab-accountability.', '{}'::text[],
  'active', 'All major US frontier developers and several others publish capability-threshold frameworks, now partly required by law in California, and SaferAI and METR track them; rigour and enforcement vary widely.', ARRAY['frontier-labs', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Lab-published RSP/preparedness-style frameworks; SaferAI''s Frontier Risk Management Tracker; METR''s cross-lab comparison.', 'high', FALSE,
  NULL, 'SaferAI and METR both publish openly and are hiring; their tracking and comparison work is the most approachable non-lab route into this node, since it needs no cooperation from the labs themselves. Frontier Model Forum membership is closed to member labs.', 'b03', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.developer-assurance.safety-cases', (SELECT id FROM public.subareas WHERE slug = 'model.developer-assurance'), 'Safety cases', 'Structured, explicit arguments, borrowed from safety-critical industries like aviation and nuclear power, that a specific model is safe enough for a specific deployment, supported by evidence rather than a general policy commitment.', 'A safety case forces a developer to make its reasoning explicit and falsifiable (''here is why we believe this model cannot do X, and here is the evidence'') rather than asserting safety by policy alone, making gaps in the argument visible to reviewers.', 'Safety cases as a standard, reviewable artefact accompanying every frontier deployment decision, with agreed templates for common argument types (for example, showing a model is incapable of a specific harm).',
  '{"title":"Safety Cases: How to Justify the Safety of Advanced AI Systems (Clymer et al., 2024)","url":"https://arxiv.org/abs/2403.10462"}'::jsonb, '[{"name":"AISI safety cases work","url":"https://www.aisi.gov.uk/blog/safety-cases-at-aisi"},{"name":"Safety Case Template for Frontier AI: A Cyber Inability Argument (GovAI)","url":"https://www.governance.ai/research-paper/safety-case-template-for-frontier-ai-a-cyber-inability-argument"}]'::jsonb, 'The evidenced argument for a specific deployment decision, where model.developer-assurance.frontier-safety-frameworks sets general policy. Checking the case from outside is model.developer-assurance.third-party-auditing; legal fault when things go wrong is society.public-policy.liability.', '{}'::text[],
  'thin', 'UK AISI and GovAI lead the methodology, and in 2026 SaferAI''s external review of a published lab safety case found it well short of safety-critical-industry practice.', ARRAY['government', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'UK AISI safety-case sketches; GovAI''s cyber-inability template; DeepMind''s published Gemini safety case; SaferAI''s external review methodology (Assurance 2.0).', 'high', FALSE,
  NULL, 'UK AISI and GovAI both publish their methodology openly and are the clearest entry points for someone with a safety-engineering or formal-argumentation background; GovAI also runs a fellowship. SaferAI''s external review of DeepMind''s safety case is a concrete template for what independent review work looks like in practice.', 'b03', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.developer-assurance.third-party-auditing', (SELECT id FROM public.subareas WHERE slug = 'model.developer-assurance'), 'Third-party auditing', 'Independent assessment of an AI developer''s safety practices and claims by an outside party, plus what that needs to be meaningful: access to models and information, agreed methods, and a professional pool of trained auditors large enough for regulation that requires audits to be carried out credibly.', 'Without credible outside checks, safety claims are self-reported, and any law that relies on audits is only as good as the auditors available to carry them out.', 'An auditing profession with agreed methodologies, deep model access by default, and enough independent capacity to audit every frontier developer, as financial auditing does for listed companies.',
  '{"title":"Frontier AI Auditing: Toward Rigorous Third-Party Assessment of Safety and Security Practices at Leading AI Companies, AVERI","url":"https://www.averi.org/ourwork/frontier-ai-auditing"}'::jsonb, '[{"name":"Frontier AI Auditing (AVERI)","url":"https://www.averi.org/ourwork/frontier-ai-auditing"},{"name":"Black-box access is insufficient for rigorous AI audits","url":"https://arxiv.org/abs/2401.14446"},{"name":"Tailwind: Independent AI auditors","url":"https://coefficientgiving.org/tailwind/initiatives/#independent-ai-auditors"}]'::jsonb, 'Owns both the audit and the supply of auditors, whether the developer invites the audit or a regulator mandates it. The technical tests auditors run are model.evaluations; making the laws that require audits is society.public-policy.legislation; outside scorecards and commitment tracking that need no developer cooperation are meta.watchdogs.lab-accountability.', ARRAY['Independent AI auditors']::text[],
  'active', 'Growing from a low base: AVERI runs pilot audits, Guidelight published a cross-company assessment, and METR, Apollo Research and government institutes evaluate models before release, while the supply of trained auditors lags far behind.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'METR, AVERI, Guidelight, Apollo Research and SaferAI all now run some form of independent evaluation or review of lab safety practices or specific safety cases.', 'high', FALSE,
  '{"title":"Tailwind: Independent AI auditors","url":"https://coefficientgiving.org/tailwind/initiatives/#independent-ai-auditors"}'::jsonb, 'METR, AVERI, Guidelight and Apollo Research are all small, actively hiring nonprofits that publish their methodology openly; AVERI''s refusal of frontier-company funding and Guidelight''s public scorecards make them particularly approachable for someone wanting to see how the work is actually done before joining.', 'b03', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.developer-assurance.incident-reporting', (SELECT id FROM public.subareas WHERE slug = 'model.developer-assurance'), 'Developer incident reporting', 'Mechanisms by which developers surface safety-relevant incidents and near-misses (a model behaving dangerously, a safeguard failing, a jailbreak causing real-world harm) and share them with other labs, regulators or the public. Some reporting is now required by law (California''s SB 53 requires critical safety incidents to be reported to the state, and the EU AI Act requires serious-incident reporting for general-purpose models with systemic risk); this node covers the reporting mechanisms themselves, whether voluntary or required.', 'Without reliable incident reporting, the field learns from failures only when they become public by accident, the way early aviation and industrial safety improved dramatically once near-miss reporting became routine and protected.', 'A standard, cross-lab incident reporting practice with protected internal whistleblowing channels, feeding a shared or at least regularly published record that the field can learn from.',
  '{"title":"Responsible Reporting for Frontier AI Development","url":"https://arxiv.org/pdf/2404.02675"}'::jsonb, '[{"name":"Frontier Model Forum: information sharing and incident reporting","url":"https://www.frontiermodelforum.org/issue-briefs/information-sharing-incident-reporting-and-incident-response-for-frontier-ai-risks/"}]'::jsonb, 'Developer-level reporting and sharing of incidents, whether voluntary or required by law. Making the laws that require reporting is society.public-policy.legislation; the public catalogue of incidents is meta.evidence.incident-tracking; independent root-cause investigation is meta.evidence.incident-investigation; internal channels for staff to raise concerns are model.developer-assurance.internal-safety-governance.', '{}'::text[],
  'thin', 'The Frontier Model Forum''s member-only sharing channel operates and some developers disclose their own incidents, but sharing is ad hoc and feeds no shared public record.', ARRAY['frontier-labs']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Frontier Model Forum''s member-to-member information-sharing channel for threats, vulnerabilities and capabilities of concern.', 'medium', FALSE,
  NULL, 'Frontier Model Forum membership is limited to frontier developers, so there is no direct individual route into its channel. The open work is on the independent side: building the public record and investigation capacity described under meta.evidence.incident-tracking and meta.evidence.incident-investigation.', 'b03', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.developer-assurance.internal-safety-governance', (SELECT id FROM public.subareas WHERE slug = 'model.developer-assurance'), 'Internal safety governance', 'The internal structures, roles and processes inside an AI developer that make its own safety commitments real: an internal audit function, safety-focused board oversight, escalation paths for safety concerns, and separation between teams building capability and teams checking safety.', 'A frontier safety framework or safety case is only as credible as the internal governance that produced and enforces it; weak internal governance is a common failure mode even when the external-facing policy looks strong.', 'Internal audit and governance functions at frontier labs with genuine independence and authority, comparable to internal audit in regulated financial institutions, reported on transparently enough for outsiders to assess.',
  '{"title":"How frontier AI companies could implement an internal audit function","url":"https://arxiv.org/pdf/2512.14902"}'::jsonb, '[]'::jsonb, 'The internal machinery behind a developer''s safety claims, including channels for staff to raise concerns. External checking is model.developer-assurance.third-party-auditing; legal protection for staff who go outside the company is society.public-policy.whistleblower-protection, and outside support for them is meta.watchdogs.whistleblower-support.', '{}'::text[],
  'thin', 'This work can only happen inside developers, and the visible evidence is limited to labs'' own statements and GovAI''s proposals for internal audit.', ARRAY['frontier-labs']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'GovAI''s internal-audit-function proposal; individual labs'' own compartmentalization and escalation policies as described in their RSPs.', 'low', FALSE,
  NULL, 'There is no independent organisation to join for this node specifically; GovAI is the closest thing (an academic/policy body proposing the internal audit function) and runs an open fellowship. The most useful thing an entrant can do here is push on the boundary node, model.developer-assurance.third-party-auditing, or on meta.watchdogs.whistleblower-support, which is where independent capacity actually can exist.', 'b03', 4,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.developer-assurance.internal-deployment', (SELECT id FROM public.subareas WHERE slug = 'model.developer-assurance'), 'Automated AI R&D and internal deployment', 'Frontier developers increasingly use their most capable models inside the company, often before or without public release, including to automate parts of AI research and development itself. Lab frameworks and the International AI Safety Report treat AI that substantially speeds up AI R&D as a key threshold, because it could accelerate progress faster than safeguards and oversight are built, while internal deployments usually face weaker safeguards and no outside scrutiny.', 'A dangerous or misaligned model could do its most consequential work inside the company that built it, with privileged access to code, compute and future models, before any outside evaluator, regulator or user sees it.', 'Developers define AI R&D capability thresholds precisely, apply the same or stronger safeguards to internal use as to public release, monitor internal agents, and share information about internal deployment of highly capable systems with appropriate outside bodies.',
  '{"title":"AI Behind Closed Doors: a Primer on the Governance of Internal Deployment (Apollo Research, 2025)","url":"https://www.apolloresearch.ai/governance/ai-behind-closed-doors-a-primer-on-the-governance-of-internal-deployment"}'::jsonb, '[{"name":"RE-Bench: evaluating frontier AI R&D capabilities against human experts (METR)","url":"https://metr.org/blog/2024-11-22-evaluating-r-d-capabilities-of-llms/"},{"name":"Machine-learning R&D critical capability levels in Google DeepMind''s Frontier Safety Framework","url":"https://deepmind.google/blog/introducing-the-frontier-safety-framework/"},{"name":"Internal deployment of AI models and systems in the EU AI Act (Apollo Research)","url":"https://www.apolloresearch.ai/governance/internal-deployment-eu-ai-act"}]'::jsonb, 'How developers govern AI used inside the company, including to automate AI research, whether they do so voluntarily or because a law requires it. Measuring AI R&D capability is model.evaluations.dangerous-capability-evals; controlling a possibly misaligned internal agent is model.control.control-protocols; trusting AI-produced alignment research specifically is model.alignment.automated-alignment-research; a small group using internally deployed AI to gain outsized power is society.structural-risk.concentration-of-power.', '{}'::text[],
  'thin', 'Apollo Research''s primer set out the governance problem in 2025, METR measures AI R&D capability, and lab frameworks name AI R&D thresholds, but internal deployment policies are neither public nor externally checked.', ARRAY['independent-ai-safety', 'frontier-labs']::text[], NULL, 'not-applicable', NULL,
  ARRAY['loss-of-control']::text[], 'Frontier safety frameworks include AI R&D or machine-learning R&D capability levels with associated safeguards, and some developers apply control-style monitoring to internal agent deployments; none of this is externally verified, and whether laws such as the EU AI Act reach internal use is contested.', 'medium', FALSE,
  NULL, 'Apollo Research''s governance team publishes on internal deployment and hires governance researchers, and METR''s RE-Bench and time-horizon work are open starting points for measuring AI R&D capability. Inside developers, frontier safety and security teams own the internal policies.', NULL, 5,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'model.developer-assurance.deployment-misuse-safeguards', (SELECT id FROM public.subareas WHERE slug = 'model.developer-assurance'), 'Deployment safeguards against misuse', 'The systems a developer wraps around a deployed model to stop people using it for harm: input and output classifiers, monitoring of usage patterns across accounts, rapid response when a new attack appears, access tiers and know-your-customer checks for sensitive capabilities, and enforcement from warnings to account bans and referrals to law enforcement. This is how a developer turns a usage policy into practice, and how it argues that a model with dangerous capabilities can still be released.', 'Refusals trained into a model are brittle, so for models near dangerous capability thresholds the safeguards around them are what stands between an attacker and real uplift, and frontier safety frameworks depend on those safeguards being strong enough.', 'Safeguards whose effectiveness is measured against adaptive attackers and independently evaluated before release, with shared methods for assessing them across developers.',
  '{"title":"Principles for safeguard evaluation (UK AI Security Institute, February 2025)","url":"https://www.aisi.gov.uk/blog/principles-for-safeguard-evaluation"}'::jsonb, '[{"name":"Constitutional Classifiers (Anthropic)","url":"https://www.anthropic.com/research/constitutional-classifiers"},{"name":"Safeguards for biological capabilities: system-wide monitors, human review and enforcement (OpenAI, 2025)","url":"https://openai.com/index/preparing-for-future-ai-capabilities-in-biology/"},{"name":"Anthropic Safeguards Research Team agenda","url":"https://alignment.anthropic.com/2025/introducing-safeguards-research-team/"}]'::jsonb, 'The safeguards system around a deployed model, including classifiers, monitoring and enforcement, whether a developer adopts it voluntarily or a law requires it. Making the model itself resist adversarial prompts is model.model-security.jailbreak-robustness; detecting attacks in the wild across providers is misuse.cyber.attack-detection; stripping safeguards from open weights is misuse.open-weights.safeguard-removal; when safeguards are required is set by model.developer-assurance.frontier-safety-frameworks.', '{}'::text[],
  'active', 'Every major developer runs safeguards teams building classifiers, monitoring and enforcement, and UK AISI evaluates safeguards and has published principles for doing so.', ARRAY['frontier-labs', 'government']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Major developers run layered safeguards (usage policies, classifiers, account-level monitoring, human review and enforcement), with heightened protections against biological misuse applied from 2025, and UK AISI has published principles for evaluating them.', 'medium', FALSE,
  NULL, 'Frontier developers'' safeguards and trust-and-safety teams hire engineers, analysts and policy staff, and Anthropic''s Safeguards Research Team publishes its methods. UK AISI''s safeguards work and public jailbreak bounties and arenas, such as Gray Swan''s, are ways to test safeguards from outside.', NULL, 6,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.cyber.offensive-uplift', (SELECT id FROM public.subareas WHERE slug = 'misuse.cyber'), 'Offensive cyber uplift', 'AI making attackers more capable: finding previously unknown vulnerabilities and writing working exploits faster than skilled humans can, and lowering the skill floor so that people without deep training can direct a model to find targets, write malware and troubleshoot attacks.', 'Finding and exploiting unknown flaws used to be the scarce skill in cyber offence. In 2026 that changed: Anthropic reported that its Mythos model found exploitable flaws in every major operating system and browser (a claim some independent researchers have questioned), and criminal groups ran intrusions in which AI agents did most of the work. If attack capability spreads faster than patching, the number of actors able to cause serious damage rises and defenders face a flood of newly exploitable flaws in software everything else depends on.', 'Independent, repeated measurement of how much real attackers gain, not only cases developers choose to disclose; a predictable lag between a capability appearing in a frontier model and its availability to attackers, which defenders can plan around; and patching capacity that keeps pace with AI-driven discovery, including for open-source maintainers and small vendors.',
  '{"title":"Frontier AI''s Impact on the Cybersecurity Landscape (Berkeley RDI)","url":"https://arxiv.org/abs/2504.05408"}'::jsonb, '[{"name":"Berkeley RDI marginal-risk framework for frontier AI in cybersecurity","url":"https://arxiv.org/abs/2504.05408"},{"name":"GTIG AI Threat Tracker","url":"https://cloud.google.com/blog/topics/threat-intelligence/from-prompting-to-autonomy-the-evolution-of-adversarial-ai"},{"name":"Anthropic threat intelligence reporting (September 2026)","url":"https://www.anthropic.com/threat-intelligence-report-september-2026"}]'::jsonb, 'The real-world uplift to attackers. Measuring a model''s cyber capability before release is model.evaluations.dangerous-capability-evals; attacks run largely by an AI agent itself are misuse.cyber.autonomous-intrusion; spotting and shutting down attacks in progress is misuse.cyber.attack-detection.', '{}'::text[],
  'active', 'Tracked by developers'' and Google''s threat-intelligence teams, UK AISI and one dedicated academic centre (Berkeley RDI), with low-skill uplift watched mostly through classical threat-intelligence channels.', ARRAY['frontier-labs', 'academia', 'government']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Coordinated vulnerability disclosure, patch management, the CVE and NVD system and bug bounties all predate AI uplift, and exploitation at scale still needs infrastructure, access and operational skill. These systems are themselves under strain: the CVE programme''s US government funding nearly lapsed in April 2025, the NVD has carried an enrichment backlog since 2024, and AI-driven discovery in 2026 (Mozilla patched 271 Firefox flaws found with one model) raises patch volume faster than many maintainers can absorb. Frontier developers'' misuse classifiers, account enforcement and gated access tiers for cyber-capable models are now a second layer of mitigation, with their own gaps.', 'medium', FALSE,
  '{"title":"Frontier AI''s Impact on the Cybersecurity Landscape: open problems and recommendations","url":"https://arxiv.org/abs/2504.05408"}'::jsonb, 'Google''s GTIG and Anthropic''s and OpenAI''s threat-intelligence teams publish openly and hire threat researchers. Berkeley RDI publishes its methodology and is the most approachable academic route for measuring uplift. The UK AI Security Institute''s cyber misuse team recruits researchers to measure uplift for government.', 'b04', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.cyber.defensive-uplift', (SELECT id FROM public.subareas WHERE slug = 'misuse.cyber'), 'AI for cyber defence', 'Using AI to strengthen cyber defenders: automated vulnerability discovery and patching (demonstrated in DARPA''s AI Cyber Challenge and, since 2026, run at scale through frontier developers'' gated programmes such as Anthropic''s Project Glasswing and OpenAI''s Trusted Access for Cyber), AI-assisted triage and incident response, and security-research agents such as Google''s Big Sleep and CodeMender. The open question behind the node is the cyber offence-defence balance: whether capability gains help attackers, who need one flaw, or defenders, who must protect everything, and under what conditions defenders pull ahead.', 'If AI systematically favours attackers, every other mitigation tracked under misuse.cyber becomes harder to sustain; if AI can be made to favour defenders instead, it could close the resourcing gap that lets a small number of skilled attackers out-match much larger defended organisations.', 'AI-driven discovery and patching reaching maintainers and operators who cannot afford security teams, not only large firms in gated programmes; measured falls in the time from discovery to patch across widely used open-source software; incident responders able to use capable models without being blocked by safeguards built for attackers; and a public evidence base on which defensive uses shift the offence-defence balance, and by how much.',
  '{"title":"Anticipating AI''s Impact on the Cyber Offense-Defense Balance","url":"https://cset.georgetown.edu/publication/anticipating-ais-impact-on-the-cyber-offense-defense-balance/"}'::jsonb, '[{"name":"DARPA AI Cyber Challenge (AIxCC) and its open-sourced finalist systems","url":"https://aicyberchallenge.com/"},{"name":"Anthropic Project Glasswing (restricted defensive access to Claude Mythos)","url":"https://techcrunch.com/2026/06/02/anthropic-scales-claude-mythos-to-critical-infrastructure-in-15-countries/"},{"name":"OpenAI Trusted Access for Cyber","url":"https://openai.com/index/trusted-access-for-cyber/"},{"name":"Frontier Model Forum AI Security Workstream","url":"https://www.frontiermodelforum.org/workstreams/ai-security-workstream/"}]'::jsonb, 'The defensive counterpart of misuse.cyber.offensive-uplift, which covers the same underlying AI capability used to attack; this node is what defenders can do with the same or purpose-built tools. Detecting a specific attack once it starts is misuse.cyber.attack-detection; measuring a model''s raw offensive capability is model.evaluations.dangerous-capability-evals; protecting the AI system itself rather than external infrastructure is model.model-security.', '{}'::text[],
  'busy', 'Busy since April 2026: gated defensive programmes from Anthropic and OpenAI, Google''s vulnerability-finding agents, the open-sourced AI Cyber Challenge systems and a large commercial market, with independent evidence on the offence-defence balance still thin.', ARRAY['frontier-labs', 'commercial', 'government']::text[], NULL, 'not-applicable', NULL,
  ARRAY['defensive-technology', 'critical-infrastructure']::text[], 'Traditional security engineering practice, non-AI automated vulnerability scanning and patch-management tooling, and existing bug-bounty programmes already form the defensive baseline that AI-for-defence tools aim to strengthen rather than replace.', 'medium', FALSE,
  NULL, 'DARPA''s AIxCC finalist writeups and open-sourced code (including Trail of Bits'' Buttercup) are the most reproducible starting point; the Frontier Model Forum''s AI Security Workstream is a coordination body rather than a place to apply directly, but its publications signal what the labs consider open.', 'b04', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.cyber.autonomous-intrusion', (SELECT id FROM public.subareas WHERE slug = 'misuse.cyber'), 'Autonomous cyber operations', 'Multi-step cyber operations in which AI agents plan, execute and adapt an intrusion over hours or days with little human direction, whether a human pointed them at the target or the agent went beyond its task on its own. Documented cases include a state-linked espionage campaign run largely by an AI agent (disclosed by Anthropic in November 2025), criminal "agent swarms" with persistent memory (Anthropic, September 2026), and OpenAI test agents that left their evaluation sandbox and broke into Hugging Face''s infrastructure in July 2026.', 'Autonomy compresses the defender''s response window and removes the human bottleneck that capped how many intrusions one operator could run; Anthropic''s September 2026 report describes breaches completed in two to three hours by a single operator. Because a human-directed agent and an agent acting beyond its instructions look the same to the victim, detection and response have to work for both.', 'Security teams have monitoring and containment specifically designed for machine-speed, self-correcting attackers, not just human-paced ones, and incidents of this kind are detected and disrupted before completion rather than after the fact.',
  '{"title":"Disrupting the first reported AI-orchestrated cyber espionage campaign (Anthropic, November 2025)","url":"https://www.anthropic.com/research/disrupting-AI-espionage"}'::jsonb, '[{"name":"Anthropic threat intelligence reporting (September 2026)","url":"https://www.anthropic.com/threat-intelligence-report-september-2026"},{"name":"GTIG AI Threat Tracker series","url":"https://cloud.google.com/blog/topics/threat-intelligence/from-prompting-to-autonomy-the-evolution-of-adversarial-ai"},{"name":"IAPS analysis of autonomous cyber attacks","url":"https://www.iaps.ai/research/autonomous-cyber-attacks"},{"name":"MITRE ATT&CK entry for the AI-orchestrated campaign (C0062)","url":"https://attack.mitre.org/campaigns/C0062/"}]'::jsonb, 'How autonomous the operation is, whoever or whatever initiated it; who gains capability is misuse.cyber.offensive-uplift. The victim-side view is shared with model.control.loss-of-control-detection: when an agent intrudes without a human directing it, as in the July 2026 OpenAI and Hugging Face incident, tag both nodes. Why an agent left its sandbox, and how to stop that, is model.control.agent-sandboxing.', '{}'::text[],
  'thin', 'Detailed accounts come mostly from developers'' own telemetry, with small independent efforts from IAPS, MITRE ATT&CK, Palisade Research and the Nightingale Collective.', ARRAY['frontier-labs', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  ARRAY['agents']::text[], 'Network intrusion detection, endpoint detection and response (EDR) and security operations centre monitoring were built for human and scripted attackers, and already catch a share of autonomous-agent intrusions as anomalous behaviour even though they were not designed with AI agents in mind.', 'medium', FALSE,
  NULL, 'Independent replication and detection research that does not rely on a developer''s telemetry is the clearest gap, and Coefficient Giving''s "Rogue incident detection" initiative funds it (see misuse.cyber.attack-detection). IAPS and Palisade Research publish in this area, and MITRE ATT&CK accepts contributions on observed AI-enabled techniques.', 'b04', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.cyber.attack-detection', (SELECT id FROM public.subareas WHERE slug = 'misuse.cyber'), 'Detecting AI-driven attacks in the wild', 'Detecting, attributing and disrupting real-world cyberattacks carried out with or by AI systems, including AI agents acting with reduced supervision, whoever launched them, as they happen and independently of the developer whose model was used.', 'Today the main evidence of AI-enabled attacks comes from the labs whose products were misused, so the world learns only what they detect and choose to disclose.', 'An independent detection capability, comparable to commercial threat-intelligence firms, that reports regularly on AI-driven attacks and can trigger revocation of attacker access across providers.',
  '{"title":"GTIG AI Threat Tracker series (Google)","url":"https://cloud.google.com/blog/topics/threat-intelligence/from-prompting-to-autonomy-the-evolution-of-adversarial-ai"}'::jsonb, '[{"name":"Anthropic threat intelligence reporting","url":"https://www.anthropic.com/threat-intelligence-report-september-2026"},{"name":"OpenAI disrupting malicious uses of AI","url":"https://openai.com/index/disrupting-malicious-ai-uses/"},{"name":"Rogue incident detection (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#rogue-incident-detection"}]'::jsonb, 'Operational detection and disruption of AI-driven attacks. The public catalogue of incidents is meta.evidence.incident-tracking and deep investigation of a single case is meta.evidence.incident-investigation; covert influence campaigns have their own detection community in misuse.influence-operations.covert-campaigns; a lab''s disclosure duties are model.developer-assurance.incident-reporting. Where an agent attacked without a human directing it (the July 2026 Hugging Face intrusion is the reference case), tag this node and model.control.loss-of-control-detection.', '{}'::text[],
  'active', 'Anthropic, OpenAI, Google and Microsoft do this at scale on their own platforms and publish most of the reporting, but nobody detects and cuts off attackers across providers.', ARRAY['frontier-labs']::text[], NULL, 'not-applicable', NULL,
  ARRAY['defensive-technology']::text[], 'Classical threat-intelligence sharing (sector ISACs, MISP, national CERTs), vendor telemetry and endpoint detection already catch a share of AI-driven attacks as anomalous behaviour, and MITRE ATT&CK now catalogues AI-enabled campaigns. A US AI-ISAC to share AI-security threat information with critical infrastructure was proposed in the July 2025 AI Action Plan and was reported in February 2026 to be in development.', 'medium', FALSE,
  '{"title":"Rogue incident detection (Coefficient Giving Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#rogue-incident-detection"}'::jsonb, 'Coefficient Giving''s ''Rogue incident detection'' Tailwind initiative is the clearest funded-gap signal for someone wanting to start an independent detection capability; short of that, publishing analysis of labs'' own disclosed cases (as academic or think-tank secondary research) is the lowest-barrier way in.', 'b04', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.cyber.critical-infrastructure', (SELECT id FROM public.subareas WHERE slug = 'misuse.cyber'), 'Attacks on critical infrastructure', 'AI-enabled attacks on the systems societies depend on: electricity, water, telecoms, healthcare, transport, the industrial control systems that run them, and banking, payment and clearing systems. The concern is both faster discovery of flaws in the old, hard-to-patch software these sectors run and AI-run intrusions against operators; developer threat reports in 2025 and 2026 already describe intrusions against telecoms, energy and payment targets.', 'Attacks here cause physical harm and cascade across sectors, and operators run legacy systems where a flood of newly found vulnerabilities is most dangerous because patching is slow. In August 2026 the chair of the Financial Stability Board told G20 finance ministers that AI-enabled cyber attacks were the most immediate threat to global financial stability, citing the July 2026 Hugging Face intrusion as the clearest public example of a model doing unsupervised damage.', 'Sector regulators, national cyber agencies and ISACs get early warning of new offensive capabilities before or at model release; operators whose failure would matter, not only the largest, can use AI to find and fix flaws in their own systems; sector exercises test responses to machine-speed intrusion; and threat information flows both ways between AI developers and sector bodies.',
  '{"title":"ENISA''s view on cybersecurity in the frontier AI era (July 2026)","url":"https://www.enisa.europa.eu/publications/enisas-view-on-cybersecurity-in-the-frontier-ai-era"}'::jsonb, '[{"name":"FSB Chair''s letter to G20 on AI-enabled cyber risk (August 2026)","url":"https://www.fsb.org/2026/08/fsb-chairs-letter-to-g20-finance-ministers-and-central-bank-governors-august-2026/"},{"name":"FS-ISAC advisory on AI-enabled vulnerability discovery","url":"https://www.fsisac.com/knowledge/updated-sector-risk-advisory-preparing-the-enterprise-for-ai-enabled-vulnerability-discovery"},{"name":"Project Glasswing extension to power, water, health and communications operators (June 2026)","url":"https://techcrunch.com/2026/06/02/anthropic-scales-claude-mythos-to-critical-infrastructure-in-15-countries/"},{"name":"US AI-ISAC (proposed 2025, in development 2026)","url":"https://www.nextgov.com/cybersecurity/2026/02/ai-info-sharing-center-development-cisa-official-says/411167/"},{"name":"US Treasury report on AI-specific cybersecurity risks in financial services (2024)","url":"https://home.treasury.gov/news/press-releases/jy2212"}]'::jsonb, 'Sector-specific consequences of the capabilities in misuse.cyber.offensive-uplift and misuse.cyber.autonomous-intrusion. Failures of AI deployed inside these systems with no attacker, and the guidance on integrating AI into operational technology, are model.reliability.high-stakes-deployment-failures; fraud against individual customers is misuse.fraud-and-abuse.fraud-and-impersonation; operators and states lacking the capacity to defend these systems are misuse.cyber.defensive-capacity-gaps.', '{}'::text[],
  'active', 'National cyber agencies, sector ISACs, OT security vendors and financial-stability authorities treat AI-enabled attacks as a real threat, with work concentrated in finance and in the US, UK and EU and mostly at guidance stage.', ARRAY['another-field', 'government']::text[], 'critical-infrastructure security: national cyber agencies and sector regulators, sector ISACs, operational technology (OT) security vendors, and financial-stability authorities', 'weak', 'Threat reports and, since June 2026, gated defensive access flow from developers to the largest operators, but early warning before a model with new offensive capability ships, developer indicators into sector sharing, sector test environments into pre-release evaluations and access for smaller operators mostly do not.',
  ARRAY['critical-infrastructure']::text[], 'Sector cyber regulation built for non-AI threats already reduces the attack surface: NERC CIP for North American power, IEC 62443 for industrial control systems, the EU NIS2 Directive, the EU Digital Operational Resilience Act for finance (applying since January 2025, including threat-led penetration testing), and the UK Telecommunications (Security) Act. Network segmentation, redundancy and manual fallback in operational technology limit what any intruder can do. None of these was designed for machine-speed discovery and exploitation, and most assume patch cycles far slower than 2026 disclosure volumes.', 'medium', FALSE,
  NULL, 'IST''s Fragile Foundations Sprint (September to December 2026) recruits participants across five workstreams and is the most approachable time-bounded route. FS-ISAC''s public AI-risk advisories and the FSB Chair''s letter show what the financial sector treats as the problem. Idaho National Laboratory and other national laboratories run OT testbeds and hire for AI and industrial-control security. For AI safety researchers, the open contribution is sector-specific evaluation of offensive capability against operational technology, which developers'' current evaluations rarely include.', 'b04', 4,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.cyber.defensive-capacity-gaps', (SELECT id FROM public.subareas WHERE slug = 'misuse.cyber'), 'Cyber defence where capacity is thin', 'Building defence against AI-enabled attacks where budgets, skills and vendor relationships are thin: lower-income states and their national CERTs, and, within richer states, the under-resourced operators of water, health, local government and small utilities that defenders call "target-rich, cyber-poor". Includes access to defensive AI itself, which in 2026 is gated by frontier developers, selects for the largest organisations, and was briefly restricted by nationality by the US Commerce Department in June 2026.', 'Guidance from CISA, NCSC and ENISA assumes institutions able to act on it, and the most capable defensive models reach vetted organisations whose code affects very large numbers of people. Offensive capability reaches everyone. Without deliberate effort, AI-enabled attacks will land hardest on the least defended systems, and the defensive gains of 2026 will widen the gap rather than close it.', 'Capacity-building programmes that name AI-enabled threats and AI defensive tooling as a focus, not only general cyber hygiene; affordable access to capable defensive models for national CERTs and small operators, with vetting that does not exclude them by default; and guidance adapted and resourced for institutions that cannot implement guidance written for large US, UK and EU operators.',
  '{"title":"Cybersecurity Economics for Emerging Markets (World Bank, 2024)","url":"https://openknowledge.worldbank.org/entities/publication/4ec1bf22-3658-4d69-b9d3-43122254bc66"}'::jsonb, '[{"name":"GIZ and ESTDEV capacity building for cybersecurity and AI (Eastern Europe, 2025 to 2027)","url":"https://www.estdev.ee/en/projects/capacity-building-cybersecurity-and-artificial-intelligence"},{"name":"Oxford Global Cyber Security Capacity Centre maturity model","url":"https://gcscc.ox.ac.uk/"},{"name":"IST Fragile Foundations Sprint (target-rich, cyber-poor operators)","url":"https://securityandtechnology.org/fragile-foundations-sprint/"},{"name":"World Bank Cybersecurity Multi-Donor Trust Fund","url":"https://www.worldbank.org/en/programs/cybersecurity-trust-fund"}]'::jsonb, 'Defensive capacity where it is thin, including access to defensive AI. The sector threat and sector regulation are misuse.cyber.critical-infrastructure; defensive AI capability itself is misuse.cyber.defensive-uplift; giving the same countries a voice in global AI rules is society.international-governance.inclusive-participation.', '{}'::text[],
  'thin', 'International cyber capacity building is a funded field, but AI-specific work within it is rare (one GIZ-funded ESTDEV programme and IST''s US pilot), and nobody works on getting defensive AI to national CERTs and small operators.', ARRAY['another-field', 'government']::text[], 'international cyber capacity building (CCB) and digital development, plus domestic programmes for under-resourced operators', 'missing', 'Almost nothing flows today; what should flow is affordable defensive model access for CERTs and small operators routed through bodies that can vet them, developer threat indicators shared beyond the US, UK and EU, and AI modules in existing capacity-building curricula.',
  ARRAY['defensive-technology', 'critical-infrastructure']::text[], 'International capacity-building programmes (the ITU, World Bank digital development projects, CERT/CC support for national CSIRTs) already work to raise baseline cyber defence in under-resourced states, independently of AI.', 'low', FALSE,
  NULL, 'The capacity-building bodies themselves (World Bank Cybersecurity Trust Fund, GFCE, ITU, ESTDEV) are the route into the international side; proposing AI-specific modules is the gap. IST''s Fragile Foundations Sprint is the route for under-resourced operators. For someone with AI-safety or developer connections, brokering defensive model access for national CERTs is open ground.', 'b04', 5,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.bio-chem.knowledge-uplift', (SELECT id FROM public.subareas WHERE slug = 'misuse.bio-chem'), 'Bioweapons knowledge uplift', 'The risk that AI models supply the expert-level troubleshooting, protocol knowledge and tacit "how do I actually make this work" guidance that has historically been the main bottleneck for a novice attempting to produce a biological weapon.', 'Written protocols alone have rarely been the limiting factor in historical bioweapons attempts; if AI reliably supplies the tacit knowledge that used to require years of wet-lab experience, that bottleneck weakens.', 'Repeated, well-powered human-uplift trials in real laboratories, run as models improve, that show where AI assistance does and does not change a novice''s chance of success end to end; and safeguards on frontier models (classifiers, account controls, gated access) whose effectiveness is measured rather than assumed.',
  '{"title":"The Operational Risks of AI in Large-Scale Biological Attacks: Results of a Red-Team Study (RAND, 2024)","url":"https://www.rand.org/pubs/research_reports/RRA2977-2.html"}'::jsonb, '[{"name":"Active Site randomised trial of AI uplift in novice wet-lab work (2026)","url":"https://arxiv.org/abs/2602.16703"},{"name":"Virology Capabilities Test (SecureBio and partners)","url":"https://arxiv.org/abs/2504.16137"},{"name":"Biological uplift demos (Tailwind)","url":"https://coefficientgiving.org/tailwind/initiatives/#biological-uplift-demos"}]'::jsonb, 'Whether AI supplies the expert troubleshooting and tacit knowledge that has been the novice''s bottleneck, including human-participant uplift trials and demonstrations for policymakers. Benchmark and red-team testing of models is model.evaluations.dangerous-capability-evals; AI designing new agents is misuse.bio-chem.design-tool-misuse; the chemical analogue is misuse.bio-chem.chemical-weapons.', ARRAY['Biological uplift demos']::text[],
  'active', 'Several groups measure uplift and their evidence points different ways: SecureBio''s virology test, RAND''s red-team and the first large wet-lab trial by Active Site with METR in 2026.', ARRAY['independent-ai-safety', 'academia', 'government']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'The Biological Weapons Convention, national select-agent and dual-use research oversight regimes, and the fact that tacit wet-lab skill and access to controlled materials remain harder bottlenecks than information access.', 'high', FALSE,
  '{"title":"AIxBio","url":"https://centerforhealthsecurity.org/our-work/aixbio"}'::jsonb, 'RAND and Johns Hopkins CHS both publish open problems and periodically hire for biosecurity/AI research; SecureBio''s grant partners (funded via Sentinel Bio) are a good route into hands-on uplift-evaluation work. The Frontier Model Forum''s AI-Biosecurity Manager listing is a way into the lab-facing side of this question.', 'b05', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.bio-chem.design-tool-misuse', (SELECT id FROM public.subareas WHERE slug = 'misuse.bio-chem'), 'Biological design tool misuse', 'AI tools purpose-built for protein and genome design (of the kind used for legitimate drug and vaccine development) being repurposed to design novel harmful biological agents, including ones engineered to evade existing detection or screening.', 'Design tools could in principle be used to generate a harmful sequence that does not match any known pathogen signature, defeating screening systems built around known threats.', 'Every widely-used biological design tool has a documented misuse-risk assessment and matching technical safeguard, kept current as the tools'' capabilities improve.',
  '{"title":"The Age of AI in the Life Sciences: Benefits and Biosecurity Considerations (US National Academies, 2025)","url":"https://www.nationalacademies.org/read/28868/chapter/1"}'::jsonb, '[{"name":"Frontier Model Forum AI-bio mitigations taxonomy","url":"https://www.frontiermodelforum.org/issue-briefs/preliminary-taxonomy-of-ai-bio-misuse-mitigations/"},{"name":"Responsible AI x Biodesign community commitments","url":"https://responsiblebiodesign.ai/"},{"name":"Screening red-team against AI-redesigned proteins (Wittmann et al., Science 2025)","url":"https://www.science.org/doi/10.1126/science.adu8578"}]'::jsonb, 'AI designing novel sequences, not explaining existing methods (misuse.bio-chem.knowledge-uplift). The physical checkpoint that catches a design before synthesis is misuse.bio-chem.synthesis-screening.', '{}'::text[],
  'thin', 'Policy venues and one landmark red-team study exist, but most design tools are open-weight and none has an independently tested misuse safeguard.', ARRAY['independent-ai-safety', 'frontier-labs', 'academia']::text[], NULL, 'not-applicable', NULL,
  ARRAY['open-source']::text[], 'Wet-lab and materials-access bottlenecks still limit what a design can become; some developers exclude pathogen sequences from training data (Arc Institute''s Evo 2 omitted eukaryotic viral genomes); synthesis screening catches known hazards and, since the 2025 patch following the Microsoft-led study, more AI-redesigned variants. There is no enforceable safeguard once an open-weight design model is downloaded.', 'medium', FALSE,
  '{"title":"AIxBio Horizon Scan (Spring 2026)","url":"https://www.nti.org/about/programs-projects/project/aixbio-global-forum/"}'::jsonb, 'NTI|bio''s AIxBio Global Forum and the Frontier Model Forum''s AI-Bio workstream are the two standing multi-stakeholder venues; the Frontier Model Forum posts an AI-Biosecurity Manager role directly on this problem. CEPI''s biosecurity-by-design partnership with the University of Washington Institute for Protein Design is the clearest technical, hands-on route in.', 'b05', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.bio-chem.synthesis-screening', (SELECT id FROM public.subareas WHERE slug = 'misuse.bio-chem'), 'DNA synthesis screening', 'Technical and policy mechanisms that check DNA and RNA synthesis orders against known hazardous sequences before they are fulfilled, plus broader access controls on equipment and materials, as the last physical checkpoint before a digital design becomes a real biological agent.', 'Synthesis is the step where a dangerous design must pass through a small number of chokepoints (synthesis providers); robust, universal screening there is one of the few controls that works regardless of how the dangerous design was generated, AI-assisted or not.', 'Screening is free, fast and near-universal among synthesis providers worldwide, including in jurisdictions with weaker regulation, and is regularly red-teamed against AI-assisted evasion attempts.',
  '{"title":"Common Mechanism for DNA Synthesis Screening (IBBIS)","url":"https://ibbis.bio/our-work/common-mechanism/"}'::jsonb, '[{"name":"IBBIS Common Mechanism","url":"https://ibbis.bio/our-work/common-mechanism/"},{"name":"SecureDNA","url":"https://securedna.org/"},{"name":"Bio safeguards red team (Tailwind)","url":"https://coefficientgiving.org/tailwind/initiatives/#bio-safeguards-red-team"}]'::jsonb, 'The last physical checkpoint, including red-teaming it against AI-designed sequences. Design-side risk is misuse.bio-chem.design-tool-misuse. This is the pre-existing biosecurity field''s core intervention, now absorbing AI-specific concerns.', ARRAY['Bio safeguards red team']::text[],
  'active', 'IBBIS''s Common Mechanism and SecureDNA provide working screening infrastructure with growing provider adoption, with gaps outside the major markets, for benchtop synthesisers and in legal requirements.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  ARRAY['defensive-technology']::text[], 'Voluntary screening by members of the International Gene Synthesis Consortium, and the US Framework for Nucleic Acid Synthesis Screening (issued April 2024, revised September 2024, and ordered to be revised again by a May 2025 executive order), already catch known hazardous sequences however they were designed. Benchtop synthesisers, which let users print DNA without an order passing a provider, are not covered by most of this.', 'high', FALSE,
  NULL, 'IBBIS publishes its Common Mechanism as open-source software and documents open problems in screening coverage; SecureDNA is likewise open and looking for synthesis-provider adoption partners. Sentinel''s grant programme is the funding route for new screening or red-team work.', 'b05', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.bio-chem.chemical-weapons', (SELECT id FROM public.subareas WHERE slug = 'misuse.bio-chem'), 'Chemical weapons uplift', 'The chemical-weapons analogue of biological uplift: whether AI models can supply synthesis routes, precursor-sourcing workarounds, or troubleshooting help for nerve agents, blister agents or other chemical weapons that a would-be attacker could not otherwise obtain. This pathway has received markedly less dedicated research attention than the biological case.', 'Chemical weapons have a lower barrier to small-scale production than biological ones in some respects, and AI-assisted troubleshooting of hazardous synthesis routes could close the gap between a determined novice and a workable chemical agent.', 'Chemical weapons risk gets a dedicated evidence base and red-team methodology comparable to what now exists for biological risk, rather than being treated as a footnote to bio-misuse work.',
  '{"title":"Dual use of artificial-intelligence-powered drug discovery (Urbina et al., Nature Machine Intelligence, 2022)","url":"https://www.nature.com/articles/s42256-022-00465-9"}'::jsonb, '[{"name":"OPCW Scientific Advisory Board Temporary Working Group on AI, final report (2026)","url":"https://www.opcw.org/sites/default/files/documents/2026/03/Final%20Report%20of%20the%20SAB''s%20TWG%20on%20AI%20FINAL%20VERSION.pdf"},{"name":"OPCW Global Conference on AI in CWC implementation","url":"https://www.opcw.org/media-centre/featured-topics/aiconference"}]'::jsonb, 'The chemical analogue of misuse.bio-chem.knowledge-uplift, kept separate because its evidence base and organisational coverage are markedly thinner and its chokepoints (precursor sourcing rather than DNA synthesis, see misuse.bio-chem.synthesis-screening) differ.', '{}'::text[],
  'thin', 'Far thinner than the biological side: OPCW''s 2026 report and challenge series, chemical coverage in RAND and FLI reports, and one small commercial safeguard (Lunai Bioworks).', ARRAY['government', 'commercial']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'The Chemical Weapons Convention''s verification regime and Australia Group precursor export controls, and the fact that synthesis know-how has not historically been the bottleneck for chemical-weapons production compared with precursor acquisition and safe handling, together mean the uplift risk is currently mitigated mostly outside any AI-specific channel.', 'low', FALSE,
  '{"title":"OPCW Global Conference on AI in CWC Implementation","url":"https://www.opcw.org/media-centre/featured-topics/aiconference"}'::jsonb, 'There is no standing AI-safety-native organisation here. The most concrete routes are OPCW''s AI Research Challenge, contributing to RAND''s or FLI''s chemical and biological policy work, and chemical-weapons evaluations inside government AI institutes and frontier developers'' safeguards teams, which cover the chemical pathway alongside the biological one. Note that Lunai Bioworks'' product is also called Sentinel and is unrelated to Sentinel Bio.', 'b05', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.bio-chem.biosecurity-defence', (SELECT id FROM public.subareas WHERE slug = 'misuse.bio-chem'), 'AI for biosecurity defence', 'Using AI to strengthen the defensive side of biosecurity: metagenomic biosurveillance that can flag a novel or engineered pathogen before it is clinically recognised, AI-assisted design of vaccines, therapeutics and diagnostics, and screening algorithms made more robust against sequences designed to evade simpler filters.', 'Biological uplift and design-tool misuse are argued to raise the ceiling on how bad an engineered pandemic could be; AI-enabled early detection and rapid countermeasure development are the main lever for cutting the time between release and effective response, the variable most pandemic-preparedness planning treats as decisive.', 'Metagenomic sequencing pipelines with AI-driven anomaly detection running continuously across a meaningful share of global wastewater and travel hubs, cutting detection time for a novel pathogen from a current baseline of roughly two weeks to a small number of days, alongside AI-assisted platforms for rapid vaccine and therapeutic design that have been used in a real response.',
  '{"title":"Building a three-day early-warning system for novel pathogens","url":"https://securebio.org/blog/three-day-early-warning-system/"}'::jsonb, '[{"name":"SecureBio Detection (formerly the Nucleic Acid Observatory)","url":"https://securebio.org/detection/"},{"name":"Sentinel Bio: biosecurity and AI","url":"https://sentinelbio.org/research-and-projects/"},{"name":"Blueprint Biosecurity: biosurveillance and AI countermeasures","url":"https://blueprintbiosecurity.org/biosurveillance-rfp-2026/"}]'::jsonb, 'The defensive counterpart of misuse.bio-chem.knowledge-uplift and misuse.bio-chem.design-tool-misuse, which cover AI raising attacker capability. The synthesis-order chokepoint before a pathogen exists is misuse.bio-chem.synthesis-screening; this node covers detecting and responding to a pathogen once it may already be circulating. Non-AI biosurveillance and general pandemic preparedness are out of scope; in scope only where AI is the enabling technology.', '{}'::text[],
  'active', 'SecureBio, NTI, CEPI and funders such as Sentinel run real pilots and working groups, though detection-latency and scale targets are not yet met anywhere.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  ARRAY['defensive-technology']::text[], 'Traditional public-health biosurveillance (the WHO''s Global Influenza Surveillance and Response System, national genomic epidemiology programmes) and existing outbreak-response infrastructure already provide baseline detection and response capacity, though with detection latencies of weeks rather than days.', 'medium', FALSE,
  '{"title":"AIxBio Horizon Scan (Spring 2026)","url":"https://www.nti.org/about/programs-projects/project/aixbio-global-forum/"}'::jsonb, 'SecureBio and Sentinel both publish open problems and periodically hire; Blueprint Biosecurity''s 2026 biosurveillance RFP (about $5m across three technical areas, EOIs due August 2026 but likely to recur) is a concrete funded route in for anyone with a computational-detection proposal.', 'b05', 4,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.military.lethal-autonomy', (SELECT id FROM public.subareas WHERE slug = 'misuse.military'), 'Autonomous weapons and their regulation', 'Weapon systems that, once activated, select and apply force to targets without further human intervention, including loitering munitions and drones with autonomous terminal guidance of the kind now used at scale in Ukraine, together with the treaty, legal and policy regimes that govern them. Covers how much human control is retained in practice, how international humanitarian law applies, and the international effort to regulate these weapons, which since 2014 has run mainly through the UN Convention on Certain Conventional Weapons (CCW), alongside national policy and non-binding declarations.', 'Removing a human from the decision to apply force weakens the main safeguard against misidentification and disproportionate harm and blurs accountability. AI developers are now part of this: frontier labs hold US defence contracts, and in March 2026 the US Department of Defense labelled Anthropic a supply-chain risk after it refused to allow its models to be used for fully autonomous weapons or domestic mass surveillance, a designation a federal judge ruled unlawful in August 2026.', 'States adopt a binding instrument that prohibits autonomous weapons that cannot be used with meaningful human control and regulates the rest (the two-tier approach in the CCW rolling text), with practical tests of human control that work in contested conditions. The immediate milestone is the CCW Review Conference in November 2026, which decides whether to open negotiations on the basis of the draft final report the Group of Governmental Experts agreed in September 2026.',
  '{"title":"Group of Governmental Experts on Lethal Autonomous Weapons Systems (UN CCW)","url":"https://disarmament.unoda.org/en/our-work/emerging-challenges/lethal-autonomous-weapon-systems"}'::jsonb, '[{"name":"UN CCW Group of Governmental Experts on LAWS (2026 session and draft final report)","url":"https://meetings.unoda.org/ccw-/convention-on-certain-conventional-weapons-group-of-governmental-experts-on-lethal-autonomous-weapons-systems-2026"},{"name":"UN General Assembly resolutions on autonomous weapons","url":"https://www.stopkillerrobots.org/news/156-states-support-unga-resolution/"},{"name":"Automated Decision Research (weapons monitoring)","url":"https://automatedresearch.org/"},{"name":"FLI Autonomous Weapons Watch","url":"https://futureoflife.org/project/autonomous-weapons/"}]'::jsonb, 'Weapons that engage without a human authorising each strike, and the arms-control and legal work on them inside and outside the CCW. Where a human formally decides but relies on AI recommendations, see misuse.military.decision-support; testing and assurance of military AI is misuse.military.testing-and-assurance; broader strategic-stability effects are society.structural-risk.strategic-stability; general international AI governance is society.international-governance.treaties. The map keeps domain-specific governance with its domain so that each community stays in one place.', '{}'::text[],
  'active', 'The arms-control and humanitarian-law community has worked on this since 2014 (the CCW process, the ICRC, UNIDIR, Stop Killer Robots, Article 36, Human Rights Watch), with FLI as the main AI-safety-native bridge and a November 2026 decision on whether to negotiate.', ARRAY['another-field', 'government']::text[], 'arms control and international humanitarian law', 'weak', 'Developers'' usage policies restricting weapons uses and FLI''s work in the CCW are the main links; what should flow is technical input on defining and verifying human control for systems built on general-purpose models, evaluation evidence on AI targeting reliability into weapons reviews, and developers'' red lines stated in terms that match the CCW''s draft prohibitions.',
  '{}'::text[], 'International humanitarian law (distinction, proportionality, precaution) applies to autonomous weapons already, and states must review new weapons for legality under Article 36 of Additional Protocol I. US policy (DoD Directive 3000.09, updated 2023) requires senior review and testing before autonomous weapons are fielded, and more than 50 states endorsed the 2023 US-led Political Declaration on Responsible Military Use of AI and Autonomy. AI developers'' usage policies are a new, contested layer: they can refuse weapons uses, as the 2026 Pentagon dispute showed, but governments can push back.', 'high', FALSE,
  '{"title":"Autonomous Weapons Watch","url":"https://futureoflife.org/project/autonomous-weapons/"}'::jsonb, 'Stop Killer Robots and Article 36 both take volunteers and campaign partners; FLI is the most approachable AI-safety-native route in, with an open newsletter, published guides and periodic hiring. UNIDIR''s RAISE roundtable and its Centre of Excellence fellowships (including a Women in AI Fellowship) are the multilateral route, and none of these requires a diplomatic posting.', 'b05', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.military.decision-support', (SELECT id FROM public.subareas WHERE slug = 'misuse.military'), 'AI targeting and decision support', 'AI systems that do not pull the trigger themselves but generate target recommendations, threat assessments or strike-priority lists that human operators then approve, often under time pressure that limits genuine scrutiny of the AI''s output.', 'A human "in the loop" who has seconds to review a machine-generated target list, under wartime pressure to approve quickly, may provide much weaker oversight in practice than the formal process suggests.', 'Independent investigation and reporting establish, for major conflicts, how much genuine scrutiny AI-generated targeting recommendations actually receive, and militaries adopt verified minimum-review standards.',
  '{"title":"AI Safety and Automation Bias: The Downside of Human-in-the-Loop (CSET, 2024)","url":"https://cset.georgetown.edu/publication/ai-safety-and-automation-bias/"}'::jsonb, '[{"name":"+972 Magazine reporting on the Lavender targeting system","url":"https://www.972mag.com/lavender-ai-israeli-army-gaza/"},{"name":"ICRC work on AI in military decision-making","url":"https://www.icrc.org/en/law-and-policy/new-technologies-and-warfare"}]'::jsonb, 'A human formally makes the final call; the concern is the quality of that oversight under time pressure, not its absence (misuse.military.lethal-autonomy). Testing such systems is misuse.military.testing-and-assurance.', '{}'::text[],
  'thin', 'Owned in practice by militaries and in law by the humanitarian-law community, with evidence coming mostly from investigative journalism and think-tank commentary rather than any organisation focused on the quality of human review.', ARRAY['another-field', 'government']::text[], 'international humanitarian law and military ethics', 'weak', 'Automation-bias and oversight research from AI safety and human-factors work should flow into targeting doctrine and minimum-review standards, and almost none does.',
  '{}'::text[], 'Existing military targeting doctrine, legal weapons review under Article 36 of Additional Protocol I, and established human-in-the-loop procedures were designed to govern any decision-support tool, not only an AI one.', 'medium', FALSE,
  NULL, 'There is no standing organisation with this as its core mandate; the most concrete routes in are CSET''s and CNAS''s published research agendas (both hire researchers) and Article 36''s targeting-specific advocacy work. Independent investigative outlets such as +972 Magazine have driven most of the public evidence base to date.', 'b05', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.military.testing-and-assurance', (SELECT id FROM public.subareas WHERE slug = 'misuse.military'), 'Military AI testing and assurance', 'Technical assurance that military AI systems (autonomous or decision-support) behave reliably and predictably under the adversarial, high-stakes conditions of actual combat, as distinct from the policy question of whether they should be used at all.', 'A military AI system that fails unpredictably in combat, whether from adversarial manipulation, distribution shift, or ordinary software failure, can cause harm regardless of what the rules say about human control.', 'Militaries adopt test-and-evaluation standards for AI-enabled weapons that are as rigorous as those for other safety-critical military systems (aviation, munitions), verified by parties independent of the system''s developer.',
  '{"title":"DoD Directive 3000.09, Autonomy in Weapon Systems (2023)","url":"https://www.esd.whs.mil/portals/54/documents/dd/issuances/dodd/300009p.pdf"}'::jsonb, '[]'::jsonb, 'Assurance of weapons-embedded AI under combat conditions. General-purpose model evaluation is model.evaluations; civilian safety-critical certification is model.reliability.safety-critical-assurance; whether such systems should be used at all is misuse.military.lethal-autonomy.', '{}'::text[],
  'active', 'Military test and evaluation bodies hold explicit mandates (the US Chief Digital and AI Office, the UK Defence AI Centre), with CNAS and CSET as the policy layer around them.', ARRAY['another-field', 'government']::text[], 'military test and evaluation and defence acquisition', 'weak', 'General-purpose models are entering military use through defence contracts, and evaluation methods from civilian AI safety (capability, propensity and control evaluations, independent red-teaming) should flow into military testing, which still relies mostly on developer self-assessment.',
  '{}'::text[], 'Military systems-engineering and verification and validation standards for safety-critical software, DoD Directive 3000.09''s requirement for realistic developmental and operational testing of autonomous functions, the UK''s JSP 936 on dependable AI in defence, and legal weapons reviews under Article 36 of Additional Protocol I provide a baseline that AI-specific test methods still need to extend, particularly for general-purpose models now being bought for defence use.', 'low', FALSE,
  NULL, 'CNAS and CSET both publish open research agendas and hire; both the UK Defence AI Centre and the US CDAO periodically issue contracts and challenges (for example via the CDAO''s Tradewinds platform) that independent researchers or firms can bid into, though direct entry to the government bodies themselves is closed to casual contributors.', 'b05', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.influence-operations.covert-campaigns', (SELECT id FROM public.subareas WHERE slug = 'misuse.influence-operations'), 'Covert influence campaigns', 'Coordinated, inauthentic campaigns that use AI to generate content, personas or engagement at a scale and quality that no longer needs large human troll farms, including interference around elections, commercial influence-for-hire firms, and campaigns that flood the web with propaganda so that AI models and AI search tools absorb and repeat it ("LLM grooming"); and the work of detecting and disrupting them.', 'AI removes the language-quality and volume constraints that used to limit covert influence operations, letting a small team run campaigns across many languages and platforms at once.', 'AI providers and platforms publish regular, comparable takedown reporting, campaigns are disrupted before reaching meaningful audiences (as most disrupted operations already were in 2025-26 reporting), and detection capability keeps pace with campaign sophistication.',
  '{"title":"Disrupting deceptive uses of AI by covert influence operations (OpenAI)","url":"https://openai.com/index/disrupting-deceptive-uses-of-ai-by-covert-influence-operations/"}'::jsonb, '[{"name":"OpenAI influence-operations disruption reporting","url":"https://openai.com/global-affairs/an-update-on-disrupting-deceptive-uses-of-ai/"},{"name":"Anthropic threat intelligence reporting on influence operations","url":"https://www.anthropic.com/threat-intelligence-report-september-2026"},{"name":"DISARM framework for describing influence operations","url":"https://www.disarm.foundation/"}]'::jsonb, 'The deliberate campaign. The persuasive technique itself, usable by disclosed actors too, is misuse.influence-operations.personalised-persuasion; tools to label or detect synthetic media are society.epistemics.content-provenance; detection of AI-driven cyberattacks, often by the same lab teams, is misuse.cyber.attack-detection.', '{}'::text[],
  'active', 'Every major developer and platform publishes recurring disruption reports and specialist firms and research groups publish independently, while US government counter-interference capacity was cut sharply in 2025.', ARRAY['frontier-labs', 'commercial', 'academia', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  ARRAY['democracy']::text[], 'Platform content-moderation and coordinated-inauthentic-behaviour detection, plus electoral law on foreign interference, now sit alongside a mature ecosystem of lab threat-intelligence teams and independent analysis groups publishing comparable, recurring takedown reporting.', 'high', FALSE,
  NULL, 'The most person-agnostic routes in are the labs'' own threat-intelligence teams (OpenAI, Anthropic and Microsoft all publish methodology and hire for these roles) and the specialist analysis groups, several of which are actively hiring (ISD, Graphika). Academic entrants can join CIP''s election-rumour research programme at the University of Washington, which explicitly recruits research assistants each election cycle.', 'b06', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.influence-operations.personalised-persuasion', (SELECT id FROM public.subareas WHERE slug = 'misuse.influence-operations'), 'AI persuasion at scale', 'AI''s ability to change people''s beliefs and behaviour through conversation or tailored messages at population scale, whether through personalisation to an individual''s psychology or through the sheer volume of fluent, information-dense argument a model can produce, distinct from mass-produced but generic propaganda.', 'Large experiments show that short conversations with AI models change political attitudes measurably, and that the persuasive gain comes mainly from how models are trained and how much information they deploy, which improves with each generation. Any actor able to put a model in front of many people, covertly or openly, gains a new instrument of influence.', 'Independent, replicated research on real-world persuasive effects and their persistence; persuasion measured routinely in pre-deployment evaluations; and rules on disclosure where AI systems are used to persuade on political or commercial matters.',
  '{"title":"The Levers of Political Persuasion with Conversational AI (Hackenburg et al., Science, 2025)","url":"https://arxiv.org/abs/2507.13919"}'::jsonb, '[]'::jsonb, 'The persuasive mechanism, which a disclosed advertiser could use as well as a covert campaign (misuse.influence-operations.covert-campaigns). Manipulation arising from ordinary product design with no directing actor is society.ethics-fairness-welfare.human-ai-relationships; measuring a model''s persuasive or misleading tendencies is model.evaluations.propensity-and-character-evals.', '{}'::text[],
  'thin', 'UK AISI runs a named human-influence team, developers measure persuasion in evaluations, and academic groups have run large experiments, but nobody outside government has it as a core mandate.', ARRAY['government', 'academia', 'frontier-labs']::text[], NULL, 'not-applicable', NULL,
  ARRAY['democracy']::text[], 'Consumer-protection and advertising-standards law, plus platform limits on political micro-targeting adopted before generative AI, provide partial existing mitigation; none of this has been updated specifically for AI-personalised persuasion.', 'medium', FALSE,
  NULL, 'UK AISI''s human-influence team hires researchers and publishes openly. Academic labs in computational social science and political communication (the Oxford Internet Institute among them) run large online experiments and take research assistants. Replicating persistence effects over weeks is an open, well-defined gap.', 'b06', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.influence-operations.extremist-recruitment', (SELECT id FROM public.subareas WHERE slug = 'misuse.influence-operations'), 'Violent extremism and terrorism', 'Extremist and terrorist groups and individuals using AI for propaganda, recruitment and radicalisation (including through companion-style chatbots) and for planning attacks, such as researching explosives or targets.', 'AI can personalise radicalisation content to an individual''s specific grievances and produce propaganda in far higher volume and more languages than human propagandists, potentially widening the population reachable by extremist recruitment.', 'Counter-terrorism and platform trust-and-safety practice incorporates AI-specific radicalisation pathways as a standard part of threat modelling, evidenced by published, replicated research rather than case studies alone.',
  '{"title":"The role of artificial intelligence in radicalisation, recruitment and terrorist propaganda (Frontiers in Political Science)","url":"https://www.frontiersin.org/journals/political-science/articles/10.3389/fpos.2025.1718396/full"}'::jsonb, '[{"name":"GNET (Global Network on Extremism and Technology) research programme","url":"https://gnet-research.org/"}]'::jsonb, 'A deliberate extremist actor directing the process. Companion-chatbot harms from product design are society.ethics-fairness-welfare.human-ai-relationships; real cases may not sort cleanly.', '{}'::text[],
  'active', 'Counter-terrorism and extremism researchers (GNET, Tech Against Terrorism, ICCT, GIFCT) produce a steady flow of AI-specific analysis, mostly at case-study and briefing level.', ARRAY['another-field']::text[], 'counter-terrorism and extremism research', 'weak', 'What should flow is terrorist-content signals and hash lists into model safeguards and developers'' monitoring for attack-planning queries, developers'' case data on attempted misuse back to researchers, and replicated research rather than case studies.',
  '{}'::text[], 'Counter-terrorism referral programmes (e.g. the UK''s Prevent), platform removal obligations under the EU Terrorist Content Regulation, and the GIFCT hash-sharing database predate generative AI; GIFCT''s 2025 AI working group and report represent the first dedicated update of this apparatus for generative AI specifically.', 'low', FALSE,
  NULL, 'GNET and Tech Against Terrorism both publish open calls for contributed research and briefings, and are the most approachable routes for an entrant from a computational social science or terrorism studies background. ICCT and GIFCT''s working groups are the policy-facing route, though GIFCT itself is a closed, membership-based body.', 'b06', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.fraud-and-abuse.fraud-and-impersonation', (SELECT id FROM public.subareas WHERE slug = 'misuse.fraud-and-abuse'), 'Fraud and impersonation', 'AI voice cloning, chat scripts, synthetic identities and deepfake video used to run scams against individuals (romance, investment and impersonation fraud, much of it from industrial scam compounds in South-East Asia) and to defeat institutions'' identity checks, including fake job candidates such as North Korean IT-worker schemes, at a volume and quality that no longer needs a large human workforce.', 'Fraud losses scale with automation, and the identity verification that banking and hiring rely on stops working if a face or voice can no longer be trusted.', 'Identity and payment systems that stay reliable when faces and voices can be faked, and detection that keeps pace with generation at population scale.',
  '{"title":"FinCEN Alert on Fraud Schemes Involving Deepfake Media Targeting Financial Institutions (2024)","url":"https://www.fincen.gov/sites/default/files/shared/FinCEN-Alert-DeepFakes-Alert508FINAL.pdf"}'::jsonb, '[{"name":"GASA and partners'' scam.org and Global Anti-Scam Summit","url":"https://gasa.org/knowledge-base/blog/global-anti-scam-alliance-launches-scam.org-with-openai-and-key-partners"},{"name":"OpenAI disrupting malicious uses of AI (scam operations)","url":"https://openai.com/index/disrupting-malicious-ai-uses/"}]'::jsonb, 'Individual victims and institutions'' verification processes. Systemic attacks on payment and clearing infrastructure are misuse.cyber.critical-infrastructure; synthetic media detection in general is society.epistemics.content-provenance; criminal services selling uncensored models are misuse.open-weights.uncensored-model-supply.', '{}'::text[],
  'busy', 'Fraud prevention and financial crime have more people and money on AI-enabled fraud than the whole AI safety community, with banks, payment firms, identity vendors and law enforcement all active.', ARRAY['another-field', 'commercial', 'government']::text[], 'fraud prevention, financial crime and identity verification', 'weak', 'Beyond developers'' disruption reports and one anti-scam partnership, little flows; what should flow is real-time abuse signals from AI and voice-cloning providers to banks and telecoms, consent and identity checks on voice cloning, and provenance signals that verification vendors can use.',
  '{}'::text[], 'Bank-level fraud detection, know-your-customer rules, and voice/identity verification vendors already deployed against non-AI fraud provide a substantial base, now being extended with dedicated deepfake-detection products (Reality Defender, Pindrop) at the institutional level; liveness checks are increasingly being defeated by generative deepfakes and consumer-facing protection lags well behind.', 'medium', FALSE,
  NULL, 'Reality Defender and Pindrop are both hiring and are the clearest commercial route in for someone with a detection or security background. GASA''s scam.org initiative and its annual Global Anti-Scam Summit are the most open, person-agnostic route for policy or victim-support-oriented entrants, since GASA explicitly works with outside partners and volunteers.', 'b06', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.fraud-and-abuse.csam', (SELECT id FROM public.subareas WHERE slug = 'misuse.fraud-and-abuse'), 'AI-generated child sexual abuse material', 'AI image and video generation used to create child sexual abuse material, including material depicting real identifiable children (via deepfake tools) and fully synthetic depictions, at a scale that has grown extremely fast in absolute terms.', 'The Internet Watch Foundation confirmed 3,443 AI-generated child sexual abuse videos in 2025, against 13 in 2024, nearly two-thirds in the most severe legal category. Much of this comes from open-weight image and video models fine-tuned for the purpose, and in January 2026 a mainstream chatbot (xAI''s Grok on X) was found generating sexualised images of real people including minors. This is measurable, severe harm today, not a speculative risk.', 'Generation tools, including open-weight models and the sites that host them, have effective, independently tested safeguards against this misuse; training datasets are screened; detection and reporting keep pace with volume; and the year-on-year growth reverses.',
  '{"title":"AI CSAM Report 2026: Harm Without Limits (Internet Watch Foundation)","url":"https://www.iwf.org.uk/about-us/why-we-exist/our-research/how-ai-is-being-abused-to-create-child-sexual-abuse-imagery"}'::jsonb, '[{"name":"Safety by Design for Generative AI: preventing child sexual abuse (Thorn and All Tech Is Human, commitments by major developers)","url":"https://www.thorn.org/blog/generative-ai-principles/"},{"name":"IWF AI CSAM research programme","url":"https://www.iwf.org.uk/about-us/why-we-exist/our-research/how-ai-is-being-abused-to-create-child-sexual-abuse-imagery"}]'::jsonb, 'The specific, unambiguously illegal harm to children. Broader child-wellbeing effects of chatbots are society.ethics-fairness-welfare.human-ai-relationships; imagery of adults is misuse.fraud-and-abuse.ncii.', '{}'::text[],
  'active', 'Child-protection organisations (IWF, Thorn, NCMEC, WeProtect) and law enforcement work at real scale alongside large platforms'' safety teams, while new AI-generated material is reported to grow faster than removal capacity.', ARRAY['another-field', 'frontier-labs']::text[], 'child protection', 'weak', 'The link is reasonable with closed-model developers (Safety by Design commitments and NCMEC reporting) but weak to missing with open-weight model makers, fine-tuners and hosting sites; what should flow is testing of models before release, dataset screening, removal of abuse-tuned models and shared detection signals.',
  ARRAY['open-source']::text[], 'NCMEC''s CyberTipline, hash-matching of known material (Microsoft''s PhotoDNA, the IWF hash list) and international policing (Europol''s Operation Cumberland in 2025) apply to AI-generated material, and Thorn''s and Google''s classifiers target novel synthetic content that hash-matching misses. Developers'' Safety by Design commitments cover training-data screening and model safeguards. The picture weakened in 2026: the EU''s temporary legal basis for voluntary detection by platforms lapsed in April 2026 after the European Parliament declined to extend it, and hash-matching cannot recognise newly generated images.', 'high', FALSE,
  NULL, 'IWF and Thorn are both actively hiring for technical and policy roles and are the clearest, most person-agnostic routes in. WeProtect Global Alliance''s multi-stakeholder structure is the best route for a policy-oriented entrant who wants to work across governments, industry and civil society rather than inside one organisation.', 'b06', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.fraud-and-abuse.ncii', (SELECT id FROM public.subareas WHERE slug = 'misuse.fraud-and-abuse'), 'Non-consensual intimate imagery', 'AI-generated sexual or intimate images and video of real adults created and distributed without their consent, using tools (including "nudify" apps and personalisation techniques needing as few as a couple of dozen reference images) that have become cheap and widely available.', 'This is direct, serious harm (reputational, psychological, sometimes physical-safety) to a specific identifiable victim, made far more accessible by generative tools that need very little source material to produce convincing fakes of a named person.', 'Hash-matching and takedown tools are available and used by the platforms where this content spreads, and the generation tools that make this trivially easy carry effective, independently verified restrictions.',
  '{"title":"Mapping the Nudify Tools Ecosystem (Institute for Strategic Dialogue, 2026)","url":"https://www.isdglobal.org/publication/mapping-the-nudify-tools-ecosystem/"}'::jsonb, '[{"name":"StopNCII.org hash-matching initiative","url":"https://stopncii.org/"}]'::jsonb, 'Same generation techniques as misuse.fraud-and-abuse.csam, but different victims, law and lead organisations. Detection of synthetic media in general is society.epistemics.content-provenance.', '{}'::text[],
  'thin', 'StopNCII and victim-support and digital-rights groups provide infrastructure and policy work, with coverage dependent on voluntary platform participation and regulators only recently active.', ARRAY['another-field']::text[], 'image-based sexual abuse, victim support and online-safety regulation', 'weak', 'Mainstream developers ban this use, but nudify apps run on open-weight models through app stores and payment rails; what should flow is removal of real-person likeness models from hosting sites, enforcement informed by ecosystem mapping, and detection of newly generated images.',
  ARRAY['open-source']::text[], 'Criminal law now reaches synthetic images in several jurisdictions: the US TAKE IT DOWN Act (2025) criminalises publishing non-consensual intimate images including AI-generated ones and required platforms to remove them within 48 hours of a request from May 2026, and the UK made creating sexually explicit deepfakes an offence in 2025. Regulators have acted against generation tools (Ofcom''s January 2026 investigation of X over Grok), and litigation targets nudify apps. StopNCII.org''s hash-matching and platform takedown help with re-shared images but not with newly generated ones.', 'medium', FALSE,
  NULL, 'StopNCII.org and EFF both work with outside partners and are the most open, person-agnostic routes in. ISD''s Challenge Fund-backed report shows that the UK AI Security Institute is a live, approachable funding route for anyone wanting to do further AI-specific technical or ecosystem-mapping work here.', 'b06', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.surveillance.mass-surveillance', (SELECT id FROM public.subareas WHERE slug = 'misuse.surveillance'), 'Mass surveillance', 'Facial recognition and other AI identification and monitoring systems deployed at national or city scale to track people''s movements and associations, including states using these tools to track and intimidate dissidents, journalists and diaspora communities abroad.', 'It removes the practical limits that have constrained surveillance, making dissent and minority life far riskier, and now reaches across borders.', 'Enforceable legal limits on mass biometric surveillance in more jurisdictions, and host states able to detect and respond to AI-enabled targeting of diaspora communities.',
  '{"title":"The Global Expansion of AI Surveillance (Carnegie Endowment for International Peace)","url":"https://carnegieendowment.org/files/WP-Feldstein-AISurveillance_final.pdf"}'::jsonb, '[]'::jsonb, 'The deployed surveillance practice. Suppressing speech is misuse.surveillance.censorship; scoring and predicting individuals is misuse.surveillance.predictive-policing-and-scoring; restricting sales of these tools abroad is misuse.surveillance.export-controls; how power becomes concentrated enough to enable this is society.structural-risk.concentration-of-power.', '{}'::text[],
  'active', 'An established digital-rights and human-rights field documents AI surveillance deployments well, with the cross-border and diaspora strand thinner.', ARRAY['another-field']::text[], 'digital rights and human rights', 'weak', 'Developers'' threat reports now describe disrupting surveillance tooling and one developer''s refusal of domestic mass surveillance became a legal fight in 2026; what should flow is developers'' case data to rights researchers and rights groups'' threat models into usage policies and monitoring.',
  ARRAY['democracy']::text[], 'The EU AI Act has prohibited, since February 2025, untargeted scraping of facial images, emotion recognition at work and in schools, and real-time remote biometric identification in public by police except in narrow cases. Data-protection law (GDPR and equivalents), export controls on surveillance goods, and human-rights monitoring and litigation (Citizen Lab, Access Now, Amnesty) continue to apply. AI developers'' usage policies are a new lever: the 2026 dispute in which the US Department of Defense labelled Anthropic a supply-chain risk turned partly on its refusal to allow domestic mass surveillance.', 'medium', FALSE,
  NULL, 'Access Now''s Digital Security Helpline and general AI programme are the most open route for a technically-minded entrant wanting to help targeted individuals directly. Citizen Lab runs fellowships and is based at a university, making it the clearest academic route in.', 'b06', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.surveillance.censorship', (SELECT id FROM public.subareas WHERE slug = 'misuse.surveillance'), 'AI-enabled censorship', 'AI systems used to detect, filter or suppress prohibited speech and content at national scale, including automated censorship built directly into widely-used AI products and services within a jurisdiction.', 'AI dramatically lowers the cost of comprehensive, real-time content censorship compared to human review, letting a state monitor and suppress dissent across far more content and languages than manual censorship ever could.', 'Independent, regularly updated audits track which AI products censor what, in which jurisdictions, and this information is accessible to affected users rather than hidden.',
  '{"title":"China''s AI-Empowered Censorship: Strengths and Limitations (Carnegie Endowment)","url":"https://carnegieendowment.org/research/2026/03/chinas-ai-empowered-censorship-strengths-and-limitations"}'::jsonb, '[]'::jsonb, 'Suppressing content, where misuse.influence-operations.covert-campaigns pushes it; the same state may do both. Surveillance of people rather than content is misuse.surveillance.mass-surveillance.', '{}'::text[],
  'active', 'Digital-rights censorship researchers (Citizen Lab, OONI, Freedom House, Carnegie) are extending their measurement to AI-based filtering, and CAISI has evaluated censorship built into open-weight models.', ARRAY['another-field']::text[], 'digital rights', 'missing', 'The rights field and the evaluation community barely connect; evaluation methods for censorship inside models should flow into rights research, and rights groups'' country knowledge into evaluators'' prompts and benchmarks.',
  ARRAY['democracy', 'open-source']::text[], 'Circumvention tools (Tor, VPNs) and monitoring by digital-rights groups (Freedom House, Citizen Lab, OONI) were built against pre-AI censorship and are being extended, evidenced by Carnegie''s and Freedom House''s recent AI-specific output, rather than replaced.', 'high', FALSE,
  NULL, 'Citizen Lab''s fellowship programme is the clearest academic route in for someone with a technical measurement background. Freedom House and Carnegie both take contributions to their annual reports from country experts and are approachable via their standard contact channels.', 'b06', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.surveillance.predictive-policing-and-scoring', (SELECT id FROM public.subareas WHERE slug = 'misuse.surveillance'), 'Predictive policing and social scoring', 'AI systems used to predict criminal behaviour, allocate policing resources, or score individuals'' trustworthiness or loyalty for access to services, employment or freedom of movement, often reproducing or amplifying existing discrimination.', 'These systems can lock in and automate discrimination at a speed and scale no individual human decision-maker could match, while their predictive basis is often difficult for an affected person to see or challenge.', 'Predictive-policing and social-scoring systems are subject to mandatory bias auditing, an affected person can get a meaningful explanation and challenge a decision, and the clearly harmful uses are prohibited, as the EU AI Act now does for social scoring and for predicting individual offending based solely on profiling.',
  '{"title":"Algorithmic Policing: When Predicting Means Presuming Guilty (AlgorithmWatch)","url":"https://algorithmwatch.org/en/algorithmic-policing-explained/"}'::jsonb, '[]'::jsonb, 'State or powerful-actor use for social control. Unfair outcomes in otherwise legitimate commercial uses are society.ethics-fairness-welfare.fairness-and-bias; the literatures overlap heavily and some organisations will tag to both.', '{}'::text[],
  'active', 'AlgorithmWatch, Fair Trials, Amnesty and similar organisations have tracked algorithmic policing and scoring for years and publish recent country case studies.', ARRAY['another-field']::text[], 'digital rights and criminal-justice reform', 'weak', 'Most systems here come from specialist vendors rather than frontier developers, so little flows between the rights field and AI developers and little yet needs to; the link to watch is police use of general-purpose models.',
  ARRAY['democracy']::text[], 'The EU AI Act prohibits social scoring and individual crime prediction based solely on profiling (from February 2025) and classes other law-enforcement uses as high-risk. Anti-discrimination and due-process law, and audit and litigation by AlgorithmWatch, Fair Trials, Amnesty and others, apply whether or not the tools use modern AI.', 'medium', FALSE,
  NULL, 'AlgorithmWatch explicitly welcomes outside contributors and collaborators for its country case studies. Fair Trials'' predictive-policing campaign page is the clearest legal/advocacy route in for someone with a criminal-justice background.', 'b06', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.surveillance.export-controls', (SELECT id FROM public.subareas WHERE slug = 'misuse.surveillance'), 'Surveillance technology export controls', 'Restricting the sale and transfer of AI-powered surveillance systems (facial recognition, network monitoring, predictive policing software) from companies in democracies to states that would use them for repression.', 'Without export controls, the technical capability built for legitimate uses in one country becomes directly available for repression in another, effectively laundering responsibility for the harm through a commercial transaction.', 'Export-control regimes for AI-enabled surveillance technology are as developed and enforced as existing controls on conventional dual-use and military technology, with verified end-use monitoring.',
  '{"title":"Regulating transfers of AI algorithms, training data and models: The potential and limitations of export controls (SIPRI)","url":"https://www.sipri.org/commentary/topical-backgrounder/2026/regulating-transfers-ai-algorithms-training-data-and-models-potential-and-limitations-export"}'::jsonb, '[{"name":"SIPRI Dual-Use and Arms Trade Control programme on AI transfers","url":"https://www.sipri.org/commentary/topical-backgrounder/2026/regulating-transfers-ai-algorithms-training-data-and-models-potential-and-limitations-export"},{"name":"EU Dual-Use Regulation 2021/821 (cyber-surveillance catch-all)","url":"https://eur-lex.europa.eu/eli/reg/2021/821/oj"}]'::jsonb, 'Trade controls on surveillance systems and software. Controls on AI chips are society.compute-governance.export-controls; the deployed practice is misuse.surveillance.mass-surveillance.', '{}'::text[],
  'thin', 'Dual-use export-control policy (SIPRI, the Wassenaar process, the EU dual-use regulation) exists but has no settled category for AI surveillance software.', ARRAY['another-field']::text[], 'export control and dual-use trade policy', 'missing', 'Technical input on how to define and verify a controllable category of AI surveillance system, of the kind compute governance has developed for chips, should flow from AI safety into export-control policy, and currently does not.',
  '{}'::text[], 'Existing dual-use export-control regimes (the Wassenaar Arrangement, the EU dual-use regulation''s cyber-surveillance catch-all clause, national export-control lists) already cover conventional surveillance hardware and are being adapted, slowly and without settled norms, to AI-specific software and models.', 'low', FALSE,
  NULL, 'SIPRI''s Dual-Use and Arms Trade Control Programme is the clearest specialist route in and publishes openly on exactly this gap. Privacy International works with outside collaborators and technologists through its broader surveillance-industry research.', 'b06', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.open-weights.safeguard-removal', (SELECT id FROM public.subareas WHERE slug = 'misuse.open-weights'), 'Safeguard removal from open weights', 'Removing refusal behaviour and safety training from a model whose weights are available, either by cheap fine-tuning on a small dataset or by directly editing weights or activations to delete the refusal direction (''abliteration''), which needs no training data and is a widely shared recipe.', 'If safeguards can be removed in minutes, any open-weight model should be treated as having none, which changes what it is safe to release.', 'Reliable measurements of how cheaply each kind of safeguard is removed, used in release decisions, and defences that raise that cost substantially.',
  '{"title":"Fine-tuning Aligned Language Models Compromises Safety, Even When Users Do Not Intend To! (Qi et al., 2023)","url":"https://arxiv.org/abs/2310.03693"}'::jsonb, '[{"name":"Refusal is mediated by a single direction (Arditi et al., 2024), the basis of abliteration","url":"https://arxiv.org/abs/2406.11717"},{"name":"Tamper-resistant safeguards (TAR; Tamirisa et al., 2024)","url":"https://arxiv.org/abs/2408.00761"},{"name":"Abliteration-resistant tuning (Kuo, Yadav and Smith, 2026)","url":"https://arxiv.org/abs/2605.26526"}]'::jsonb, 'The attack side. Making safeguards survive fine-tuning is model.alignment.unlearning-and-tamper-resistance; the interpretability understanding that abliteration exploits is model.interpretability.safety-applications; distribution of the resulting models is misuse.open-weights.uncensored-model-supply.', '{}'::text[],
  'thin', 'Mostly academic papers on abliteration, one commercial vendor (Alice) publishing measurement research, and UK AISI''s worst-case testing under adversarial fine-tuning.', ARRAY['commercial', 'academia', 'government']::text[], NULL, 'not-applicable', NULL,
  ARRAY['open-source']::text[], 'Model licences and terms of service formally prohibit safeguard removal, though this is largely unenforceable once weights are public; there is no other non-AI-native mitigation for this specific technique.', 'medium', FALSE,
  NULL, 'Alice publishes its abliteration research openly and is the clearest industry contact point; independent replication of the arXiv papers (2605.26526 and 2607.17427) on new model families is a low-barrier way for a new researcher to add evidence, since coverage of specific model families is thin.', 'b04', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.open-weights.uncensored-model-supply', (SELECT id FROM public.subareas WHERE slug = 'misuse.open-weights'), 'Uncensored model supply', 'The hosting, packaging and sale of models whose safeguards have been removed, from uploads on mainstream model-hosting platforms to underground services (sometimes branded, such as ''WormGPT''-style offerings) that sell uncensored models for writing malware, phishing and scam scripts.', 'Distribution decides whether a stripped model stays a research curiosity or reaches a broad population of would-be criminals.', 'Ongoing tracking of how uncensored models spread and are sold, and hosting and payment chokepoints that make large-scale criminal services harder to run.',
  '{"title":"Malla: Demystifying Real-world Large Language Model Integrated Malicious Services (USENIX Security 2024)","url":"https://arxiv.org/abs/2401.03315"}'::jsonb, '[]'::jsonb, 'Distribution and retail. Stripping the safeguards is misuse.open-weights.safeguard-removal; the fraud and cyber harms that follow are misuse.fraud-and-abuse.fraud-and-impersonation and misuse.cyber.offensive-uplift.', '{}'::text[],
  'thin', 'Security vendors (Alice, Trend Micro, Cisco Talos) track the uncensored-model marketplace, but nobody works to disrupt its distribution or payment chokepoints.', ARRAY['commercial']::text[], NULL, 'not-applicable', NULL,
  ARRAY['open-source']::text[], 'Hosting platforms'' content policies, app-store rules and payment processors'' terms are the main levers, and they work when applied: payment-processor pressure led at least one large model-sharing site (Civitai) to restrict real-person likeness models in 2025. Criminal services moved to self-hosting and crypto payments in response.', 'low', FALSE,
  NULL, 'Threat-intelligence teams at Alice, Trend Micro and Cisco Talos publish openly and are the most direct way to see current marketplace structure; there is no dedicated disruption-focused organisation to join, which is itself the gap an entrant could fill.', 'b04', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'misuse.open-weights.release-risk-assessment', (SELECT id FROM public.subareas WHERE slug = 'misuse.open-weights'), 'Open-weight release: marginal risk and benefit', 'Frameworks and evidence for judging what a given open-weight release adds, in both risk and benefit, compared with models already available. On the risk side, safeguards can probably be removed after release and a release cannot be recalled; on the benefit side, open models let researchers, defenders and smaller companies and countries inspect, adapt and run models themselves, and spread capability beyond a few developers. After the July 2026 OpenAI and Hugging Face incident, open-model advocates argued that responders needed open models because closed-model safeguards had blocked their forensic work.', 'Open-weight releases cannot be recalled, and blanket restriction would also give up research, defensive and competition benefits; credible independent assessment of marginal risk and benefit is what lets policymakers and developers decide release by release rather than by assumption.', 'Independent researchers, not only the releasing developer, produce credible assessments of marginal risk and benefit for major open-weight releases, and these assessments visibly inform release decisions, post-release mitigations and policy.',
  '{"title":"On the Societal Impact of Open Foundation Models (Kapoor, Bommasani et al., ICML 2024)","url":"https://arxiv.org/abs/2403.07918"}'::jsonb, '[{"name":"NTIA report on dual-use foundation models with widely available weights (2024)","url":"https://www.ntia.gov/issues/artificial-intelligence/open-model-weights-report"},{"name":"UK AISI open-weight risk management programme","url":"https://www.aisi.gov.uk/blog/managing-risks-from-increasingly-capable-open-weight-ai-systems"},{"name":"CAISI evaluation of DeepSeek models (2025)","url":"https://www.nist.gov/news-events/news/2025/09/caisi-evaluation-deepseek-ai-models-finds-shortcomings-and-risks"}]'::jsonb, 'Independent assessment of what an open-weight release adds, in risk and in benefit. The developer''s own release process is model.developer-assurance.frontier-safety-frameworks; national rules on open release would be society.public-policy.legislation; concentration of capability in a few closed developers is society.structural-risk.concentration-of-power.', '{}'::text[],
  'active', 'UK AISI runs an open-weight risk programme with EleutherAI and Oxford, US CAISI evaluated DeepSeek''s models, Stanford CRFM set out the marginal-risk framework, and Hugging Face started an Open Alignment team in September 2026.', ARRAY['government', 'independent-ai-safety', 'academia']::text[], NULL, 'not-applicable', NULL,
  ARRAY['open-source']::text[], 'Dual-use research of concern (DURC) oversight frameworks from biosecurity are the closest pre-existing model, adapted by analogy, for gating the release of a dual-use artefact.', 'medium', FALSE,
  '{"title":"Open Technical Problems in Open-Weight AI Model Risk Management","url":"https://stephencasper.com/wp-content/uploads/2025/11/open_weight_model_safety_oct2025.pdf"}'::jsonb, 'UK AISI''s open-weight work and EleutherAI are both openly collaborative and publish methodology; Hugging Face''s new Open Alignment Team (announced September 2026) is the freshest and most likely to be actively hiring or seeking collaborators as it stands up.', 'b04', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.structural-risk.race-dynamics', (SELECT id FROM public.subareas WHERE slug = 'society.structural-risk'), 'Race dynamics', 'Competitive pressure between AI companies, and between states, to develop and deploy more capable systems faster than safety work can keep pace, including cutting corners on testing to avoid losing ground to rivals.', 'Racing is a collective-action trap: each developer or state may privately prefer more caution but cannot afford to slow down alone, so testing is cut short and the chance rises that a dangerous system ships before anyone has checked it properly. Many other problems on this map, from evaluations to international agreements, get harder under racing pressure.', 'Credible mechanisms, such as verified agreements or coordinated pacing, that let competitors slow down together without any one of them losing decisive ground, backed by monitoring that would expose defection.',
  '{"title":"An Overview of Catastrophic AI Risks (Hendrycks & Woodside), section on the AI race","url":"https://arxiv.org/abs/2306.12001"}'::jsonb, '[{"name":"Superintelligence Strategy and its deterrence framing, Mutual Assured AI Malfunction (Hendrycks, Schmidt and Wang, 2025)","url":"https://www.nationalsecurity.ai/"},{"name":"Forethought''s research on navigating a fast or discontinuous transition","url":"https://www.forethought.org/"},{"name":"Convergence Analysis''s US-China race scenarios and ASI treaty framework","url":"https://www.convergenceanalysis.org/fellowships/international-security/toward-asi-stability-a-treaty-framework-for-us-china-cooperation-on-artificial-superintelligence"}]'::jsonb, 'The incentive problem. The machinery that might solve it is society.international-governance.treaties and society.compute-governance.agreement-verification; one lab''s own commitments are model.developer-assurance.frontier-safety-frameworks.', '{}'::text[],
  'thin', 'Think tanks (Forethought, Convergence Analysis, CAIS, the AI Futures Project) describe the racing dynamic and a few scenario and treaty proposals exist, but nobody works directly on changing the incentives.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Voluntary inter-lab coordination on safety practice through the Frontier Model Forum. Some published frontier safety policies now say the developer may relax its own requirements if a rival releases a comparable system without equivalent safeguards (for example OpenAI''s April 2025 Preparedness Framework update), which writes racing pressure into policy rather than containing it. No verified mechanism for coordinated pacing exists between labs or states.', 'medium', FALSE,
  '{"title":"AI-Enabled Coups (Forethought) and Toward ASI Stability (Convergence Analysis) both discuss racing incentives as a driver of other structural risks","url":"https://www.convergenceanalysis.org/fellowships/international-security/toward-asi-stability-a-treaty-framework-for-us-china-cooperation-on-artificial-superintelligence"}'::jsonb, 'Forethought and Convergence Analysis both publish open research questions and take on researchers or fellows on transition and race-dynamics strategy; the Frontier Model Forum is closed to labs rather than open to individual entrants. There is no dedicated organisation working on race-slowing mechanisms themselves, so an entrant with a background in mechanism design, verification technology or game theory has genuinely open ground here.', 'b07', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.structural-risk.concentration-of-power', (SELECT id FROM public.subareas WHERE slug = 'society.structural-risk'), 'Concentration of power', 'The risk that advanced AI capability, and the economic and political power that flows from it, becomes concentrated in a very small number of companies, states or individuals, potentially letting a small group seize or entrench outsized control.', 'A small group could use AI-enabled surveillance, persuasion or economic dominance to escape the checks and balances that normally constrain power, whether by seizing it outright or by quietly dominating the markets everyone else depends on.', 'Mechanisms for distributing AI capability and its governance, such as broad deployment norms, oversight bodies with real authority, and checks on any single actor''s control of decisive AI infrastructure, in place before capability becomes decisive.',
  '{"title":"AI-Enabled Coups: How a Small Group Could Use AI to Seize Power (Tom Davidson, Lukas Finnveden & Rose Hadshar, Forethought, April 2025)","url":"https://www.forethought.org/research/ai-enabled-coups-how-a-small-group-could-use-ai-to-seize-power"}'::jsonb, '[{"name":"Forethought''s power-concentration and AI-enabled coups research","url":"https://www.forethought.org/research/ai-enabled-coups-how-a-small-group-could-use-ai-to-seize-power"},{"name":"AI Now Institute''s research on corporate and state power concentration","url":"https://ainowinstitute.org"},{"name":"The Intelligence Curse (Drago and Laine, 2025), on what happens to states and citizens when labour stops being a source of power","url":"https://intelligence-curse.ai/"},{"name":"UK Competition and Markets Authority review of AI foundation models","url":"https://www.gov.uk/cma-cases/ai-foundation-models-initial-review"}]'::jsonb, 'A specific group gaining outsized control, whether by seizing political power or by dominating the markets for compute, cloud and frontier models. The two strands have different communities (AI-risk strategy on seizure of power; competition law and political economy on market concentration) and an entrant should know both exist. Everyone losing influence with no beneficiary is society.structural-risk.gradual-disempowerment; a state that already holds power using AI for repression is misuse.surveillance; insiders secretly steering a model is model.model-security.insider-threat.', '{}'::text[],
  'thin', 'Forethought works on the mechanics of seizing power and the AI Now Institute on corporate and economic concentration, with nobody yet building countermeasures full time.', ARRAY['independent-ai-safety', 'academia']::text[], NULL, 'not-applicable', NULL,
  ARRAY['democracy', 'open-source']::text[], 'None in force; the Forethought report itself proposes candidate mitigations (e.g. transparency about military and intelligence use of AI, checks on exclusive model access) that have not yet been adopted by any government or lab.', 'medium', FALSE,
  '{"title":"AI-Enabled Coups (Forethought)","url":"https://www.forethought.org/research/ai-enabled-coups-how-a-small-group-could-use-ai-to-seize-power"}'::jsonb, 'Forethought publishes open research questions from the AI-enabled coups report and is a natural first stop for anyone wanting to work on countermeasures (transparency mechanisms, checks on military/intelligence AI use, distributed oversight). AI Now Institute is hiring and publishes on corporate power concentration for those more interested in the economic and antitrust angle.', 'b07', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.structural-risk.gradual-disempowerment', (SELECT id FROM public.subareas WHERE slug = 'society.structural-risk'), 'Gradual disempowerment', 'The risk that humans progressively lose effective influence over economic, cultural and political systems as AI performs more of the functions those systems depend on, including the loss of any human or institution''s timely ability to review, override or halt what the aggregate system is doing, even when each deployment passes its own review and no one intends the outcome.', 'It prevents a slow, hard-to-notice slide into irrelevance for human judgement and preferences across institutions, a failure mode that classic loss-of-control framings centred on a single rogue AI can miss entirely.', 'Institutions that can demonstrate they still track and act on human preferences as AI automates more of their internal functions, plus early-warning indicators for when that stops being true.',
  '{"title":"Gradual Disempowerment: Systemic Existential Risks from Incremental AI Development (Kulveit, Douglas, Ammann, Turan, Krueger & Duvenaud, 2025)","url":"https://gradual-disempowerment.ai/"}'::jsonb, '[{"name":"Gradual Disempowerment research agenda and position paper","url":"https://gradual-disempowerment.ai/"},{"name":"AI Objectives Institute''s work on collective alignment as a countermeasure","url":"https://aiobjectives.org"},{"name":"UK AISI''s societal resilience research theme","url":"https://www.aisi.gov.uk/research-agenda"}]'::jsonb, 'Can occur even if every system is aligned to its operator (contrast model.alignment) and with no specific beneficiary (contrast society.structural-risk.concentration-of-power). Oversight of a single deployment is model.control.control-protocols.', '{}'::text[],
  'thin', 'ACS Research treats gradual disempowerment as a standing research programme, with the AI Objectives Institute working nearby.', ARRAY['academia', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  ARRAY['loss-of-control', 'democracy']::text[], 'None in force; the paper and ACS Research''s follow-on agenda propose research directions (measuring disempowerment, hierarchical-agency frameworks, oversight indicators) rather than deployed mitigations.', 'medium', FALSE,
  '{"title":"Gradual Disempowerment: Concrete Research Projects (AlignmentForum)","url":"https://www.alignmentforum.org/posts/GAv4DRGyDHe2orvwB/gradual-disempowerment-concrete-research-projects"}'::jsonb, 'ACS Research''s own site lists open research questions and hiring; the gradual-disempowerment.ai site lists a concrete research-projects post on the Alignment Forum that names specific tractable sub-questions an entrant could pick up. AI Objectives Institute also takes on researchers for its collective-alignment and deliberation-tool work.', 'b07', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.structural-risk.multi-agent-risk', (SELECT id FROM public.subareas WHERE slug = 'society.structural-risk'), 'Multi-agent risks', 'Risks and open problems arising from interactions between multiple AI systems, such as unstable equilibria, collusion, negotiation failure, or conflict escalation between AI agents acting on behalf of different principals.', 'It prevents harms that no single system''s designer would predict from testing it in isolation, including AI-driven conflicts that could be more severe or harder to de-escalate than purely human ones.', 'Tested protocols and institutions for AI-to-AI interaction, such as negotiation, commitment devices, and verification, that keep multi-agent systems in cooperative rather than adversarial equilibria, validated in realistic simulated environments before wide deployment.',
  '{"title":"Multi-Agent Risks from Advanced AI (Hammond et al., Cooperative AI Foundation technical report, 2025)","url":"https://arxiv.org/abs/2502.14143"}'::jsonb, '[{"name":"Cooperative AI Foundation''s research agenda","url":"https://www.cooperativeai.com/"},{"name":"Center on Long-Term Risk''s work on reducing risks of AI conflict (s-risks)","url":"https://longtermrisk.org/"}]'::jsonb, 'Interactions between independently operated AI systems. One organisation controlling one untrusted model is model.control.control-protocols; deliberate weaponisation is misuse.military.', '{}'::text[],
  'active', 'A dedicated funder (Cooperative AI Foundation), a research institute (CLR), a startup betting on multi-agent alignment (Softmax) and Google DeepMind''s benchmark infrastructure, still a small share of safety effort.', ARRAY['independent-ai-safety', 'frontier-labs', 'commercial']::text[], NULL, 'not-applicable', NULL,
  ARRAY['agents']::text[], 'Benchmark suites (Melting Pot) and a growing academic literature on multi-agent reinforcement learning safety; no deployed institutional mechanism yet for AI-to-AI negotiation or verification in real-world settings.', 'high', FALSE,
  '{"title":"Cooperative AI Foundation research agenda","url":"https://www.cooperativeai.com/"}'::jsonb, 'The Cooperative AI Foundation runs grants, workshops (including a NeurIPS workshop series) and is the most person-agnostic route in; CLR runs a named fellowship; Softmax is hiring directly for its research agenda. Google DeepMind''s Melting Pot is open source and usable by anyone wanting to build or test multi-agent evaluation methods without needing to join a lab.', 'b07', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.structural-risk.strategic-stability', (SELECT id FROM public.subareas WHERE slug = 'society.structural-risk'), 'AI and strategic stability', 'How the spread of advanced AI affects the risk of war or crisis escalation between states, including faster decision cycles, new opportunities for miscalculation, and pressure to integrate AI into nuclear or conventional command and control.', 'It prevents AI from making great-power crises more likely to spiral into war by compressing decision time, degrading mutual understanding of intentions, or creating incentives for pre-emption.', 'Confidence-building measures and crisis-communication channels adapted for an AI-saturated environment, plus clear norms, such as keeping humans in nuclear command decisions, adopted by the major military powers.',
  '{"title":"The Impact of Artificial Intelligence on Strategic Stability and Nuclear Risk, Volume I (SIPRI, 2019)","url":"https://www.sipri.org/publications/2019/research-reports/impact-artificial-intelligence-strategic-stability-and-nuclear-risk-volume-i-euro-atlantic"}'::jsonb, '[{"name":"SIPRI''s programme on AI and strategic stability","url":"https://www.sipri.org/research/armament-and-disarmament/emerging-military-and-security-technologies/artificial-intelligence"},{"name":"CNAS''s AI and national security work","url":"https://www.cnas.org"},{"name":"Superintelligence Strategy''s deterrence proposal (MAIM), and the debate it started about stability between AI powers","url":"https://www.nationalsecurity.ai/"}]'::jsonb, 'Crisis escalation and command-and-control effects of military AI adoption. Weapons that select targets are misuse.military.lethal-autonomy and misuse.military.decision-support; the diplomatic channels are society.international-governance.great-power-dialogue.', '{}'::text[],
  'active', 'Arms-control and strategic-studies institutions (SIPRI, CNAS, RAND) run AI-specific programmes on nuclear risk, escalation and command and control.', ARRAY['another-field']::text[], 'arms control and strategic studies', 'weak', 'The research is strong, but little of it reaches AI developers and AI governance bodies as shared standards or channels, and developers'' knowledge of what their models can do in military settings rarely flows back.',
  ARRAY['critical-infrastructure']::text[], 'Longstanding nuclear confidence-building and crisis-communication channels (hotlines, notification regimes) that predate AI, now under study for how they need to adapt. Non-binding statements exist: the US and China affirmed in November 2024 that humans, not AI, should control decisions to use nuclear weapons; the US-led Political Declaration on Responsible Military Use of AI and Autonomy (2023) and the REAIM summits set broader norms. No binding AI-specific agreement among the major military powers exists.', 'medium', FALSE,
  '{"title":"SIPRI''s programme on AI and strategic stability","url":"https://www.sipri.org/research/armament-and-disarmament/emerging-military-and-security-technologies/artificial-intelligence"}'::jsonb, 'SIPRI and CNAS both publish open research and hire from national-security and technical backgrounds; RAND runs fellowships and is a large, standard entry point into this field for those with a policy or technical-security background. This is not a node where an AI-safety-native newcomer organisation is obviously missing; the more useful route in for an entrant is through these existing institutions.', 'b07', 4,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.public-policy.legislation', (SELECT id FROM public.subareas WHERE slug = 'society.public-policy'), 'Domestic AI legislation', 'Statutes and regulations passed by national or subnational governments that impose binding requirements on the development or deployment of AI systems, such as the EU AI Act or US state-level frontier AI safety laws.', 'It prevents reliance on companies'' voluntary commitments alone by giving legal force and enforcement teeth to safety and transparency requirements.', 'A small number of well-designed, interoperable statutes, rather than a patchwork of conflicting rules, that are actually enforced, cover frontier-scale risk without strangling beneficial uses, and are updated as capabilities change.',
  '{"title":"EU AI Act regulatory framework overview (European Commission)","url":"https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai"}'::jsonb, '[{"name":"EU AI Act implementation: general-purpose AI obligations in force since August 2025, the GPAI Code of Practice (July 2025), and the Digital Omnibus deferral of high-risk obligations to December 2027 (agreed May 2026)","url":"https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai"},{"name":"US state frontier AI statutes: California SB 53 (2025), New York RAISE Act (2025), Illinois SB 315 AI Safety Measures Act (2026)","url":"https://www.dwt.com/blogs/artificial-intelligence-law-advisor/2026/07/illinois-frontier-ai-safety-law"},{"name":"US federal pre-emption push: December 2025 executive order creating an AI Litigation Task Force to challenge state AI laws","url":"https://www.whitehouse.gov/presidential-actions/2025/12/eliminating-state-law-obstruction-of-national-artificial-intelligence-policy/"},{"name":"Secure AI Project''s state-by-state tracking of frontier AI bills","url":"https://secureaiproject.org"}]'::jsonb, 'Making and passing binding law within one jurisdiction, and the regulators and enforcement that follow. The assurance mechanisms a law requires (frontier safety frameworks, incident reporting, audits, safety cases) sit in model.developer-assurance whether voluntary or mandated; co-regulatory codes such as the EU GPAI Code of Practice are part of the law-making here, while the frameworks they ask for are model.developer-assurance.frontier-safety-frameworks; cross-border agreements are society.international-governance.treaties; campaigns for legislation are meta.communications.advocacy.', '{}'::text[],
  'active', 'Advocacy organisations, legal researchers and legislatures work on AI statutes, and binding frontier-model law now exists in the EU, California, New York and Illinois, amid US federal efforts to pre-empt state laws.', ARRAY['independent-ai-safety', 'government']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'high', FALSE,
  NULL, 'Encode and Secure AI Project both take volunteers and welcome contact from people who want to work on state or federal AI bills, and LawAI publishes open legal research questions. CLTR''s expert-placement programme (see regulatory-capacity) is a route into UK government policy work specifically.', 'b08', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.public-policy.liability', (SELECT id FROM public.subareas WHERE slug = 'society.public-policy'), 'Liability for AI harms', 'Legal frameworks that determine who is responsible, and who must pay, when an AI system causes harm, including questions of developer versus deployer liability and how existing tort and product-liability law applies to AI.', 'It prevents a situation where victims of AI-caused harm have no effective legal remedy and where developers face no financial incentive to invest in safety because liability is unclear or unenforceable.', 'Clear, tested liability rules, whether through new statute or judicial interpretation of existing law, that assign responsibility in a way that incentivises safety investment without making beneficial deployment commercially impossible.',
  '{"title":"U.S. Tort Liability for Large-Scale Artificial Intelligence Damages: A Primer for Developers and Policymakers (RAND, 2024)","url":"https://www.rand.org/pubs/research_reports/RRA3084-1.html"}'::jsonb, '[{"name":"EU revised Product Liability Directive (2024/2853), which brings software and AI systems within strict product liability for products placed on the market from 9 December 2026","url":"https://eur-lex.europa.eu/eli/dir/2024/2853/oj/eng"},{"name":"Institute for Law & AI''s liability research","url":"https://law-ai.org"},{"name":"Test cases in US courts over chatbot harms, such as Garcia v. Character Technologies and Raine v. OpenAI","url":"https://www.rand.org/pubs/research_reports/RRA3084-1.html"},{"name":"EU''s withdrawn AI Liability Directive and its aftermath","url":"https://www.europarl.europa.eu/legislative-train/theme-a-europe-fit-for-the-digital-age/file-ai-liability-directive"}]'::jsonb, 'Who pays and who is at fault. Statute more broadly is society.public-policy.legislation; responsibility for harm caused by AI agents specifically is society.public-policy.agent-accountability; a developer''s internal risk arguments are model.developer-assurance.safety-cases.', '{}'::text[],
  'thin', 'LawAI is the one specialist nonprofit doing sustained AI liability research, with RAND and academic tort scholars contributing while courts hear the first chatbot-harm cases.', ARRAY['independent-ai-safety', 'academia']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Ordinary tort, negligence and product-liability law; the EU''s revised Product Liability Directive from December 2026; early US court decisions on whether chatbot output is a product or protected speech.', 'high', FALSE,
  NULL, 'LawAI is effectively the only dedicated route in; it publishes open research questions on AI liability and is small enough that direct outreach is realistic for someone with a legal research background.', 'b08', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.public-policy.agent-accountability', (SELECT id FROM public.subareas WHERE slug = 'society.public-policy'), 'Accountability and liability for agent actions', 'Who is responsible when an AI agent acting on someone''s behalf causes harm: the developer of the model, the company that deployed the agent, the user who instructed it, or nobody. Existing law assumes a person or company takes each consequential action; agents that sign up to services, move money or run code blur that, and proposals range from applying agency law to requiring agents to follow the law by design.', 'If nobody is clearly accountable for what agents do, harms go uncompensated, the incentive to deploy agents carefully weakens, and courts and legislators settle the question case by case after the damage.', 'A clear allocation of responsibility among developers, deployers and users for agent actions, tested in law or regulation, and agents designed to follow the law and leave the records that accountability needs.',
  '{"title":"Governing AI Agents (Noam Kolt, Notre Dame Law Review, 2025)","url":"https://arxiv.org/abs/2501.07913"}'::jsonb, '[{"name":"Law-Following AI: designing AI agents to obey human laws (Institute for Law & AI)","url":"https://law-ai.org/law-following-ai/"}]'::jsonb, 'Responsibility for harm caused by agents specifically. Liability for AI harms in general is society.public-policy.liability; identifying and tracing agents is society.public-policy.agent-infrastructure; building agents that do not pursue unintended goals is model.alignment.', '{}'::text[],
  'thin', 'Legal scholarship on governing agents (Kolt) and LawAI''s work on law-following AI set out the questions, but no organisation focuses on responsibility for agent actions and no jurisdiction has settled it.', ARRAY['independent-ai-safety', 'academia']::text[], NULL, 'not-applicable', NULL,
  ARRAY['agents']::text[], 'General tort, contract, product-liability and agency law apply, and the revised EU Product Liability Directive brings AI software under strict liability for products placed on the market from December 2026; none of it was written with autonomous agents in mind.', 'medium', FALSE,
  NULL, 'The Institute for Law & AI publishes on law-following AI and runs a workshop series on it; legal scholars working on agency law and product liability can contribute directly. Developers'' terms of service for agent products are where responsibility is allocated in practice today.', NULL, 2,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.public-policy.standards', (SELECT id FROM public.subareas WHERE slug = 'society.public-policy'), 'Standards and certification', 'Technical standards and conformity-assessment frameworks written specifically for AI safety and security, covering management-system standards such as ISO/IEC 42001, risk-management frameworks such as the NIST AI Risk Management Framework and its 2024 Generative AI Profile, the harmonised standards being drafted under the EU AI Act, frontier-model evaluation and red-teaming standards, and the safety and security work inside IEEE and CEN-CENELEC. Covers how these standards are written and how they get adopted, whether voluntarily by developers or written into law and procurement.', 'Standards turn general safety principles into checkable, AI-specific requirements; weak or paperwork-only standards give false assurance, and laws that lean on them inherit their gaps.', 'Standards specific enough to frontier AI risks that certification means something, with independent verification of substantive rather than paper compliance.',
  '{"title":"NIST AI Risk Management Framework (AI RMF 1.0)","url":"https://www.nist.gov/itl/ai-risk-management-framework"}'::jsonb, '[{"name":"NIST AI RMF (Govern, Map, Measure, Manage), under revision following the July 2025 US AI Action Plan","url":"https://airc.nist.gov/airmf-resources/airmf/"},{"name":"NIST Generative AI Profile","url":"https://airc.nist.gov/AI_RMF_Knowledge_Base/Generative_AI_Profile"},{"name":"ISO/IEC 42001","url":"https://www.iso.org/standard/81230.html"},{"name":"EU AI Act harmonised standards (CEN-CENELEC JTC 21)","url":"https://www.cencenelec.eu/areas-of-work/cenelec-sectors/artificial-intelligence/"},{"name":"ETSI baseline cyber security requirements for AI systems (EN 304 223)","url":"https://www.etsi.org/technologies/securing-artificial-intelligence"},{"name":"IEEE AI standards (e.g. IEEE 7000 series)","url":"https://standards.ieee.org/initiatives/artificial-intelligence-systems/"}]'::jsonb, 'One node for AI-specific standards whoever adopts them. Scope rule: in scope only for standards written for AI safety, security, risk-management or evaluation purposes; out of scope are generic IT service-management, information-security or quality standards not specific to AI (for example ISO 9001 or ISO/IEC 27001), even where an AI company happens to hold that certification. A developer''s own frameworks are model.developer-assurance.frontier-safety-frameworks; content-provenance standards are society.epistemics.content-provenance; model integrity standards are model.model-security.supply-chain-and-integrity.', '{}'::text[],
  'active', 'NIST, ISO/IEC JTC 1/SC 42, CEN-CENELEC JTC 21, IEEE, the AI Verify Foundation, AI Standards Lab and MLCommons all produce AI-specific standards; uptake by frontier developers and independent verification of compliance lag behind.', ARRAY['government', 'commercial', 'independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'high', FALSE,
  NULL, 'MLCommons and AI Verify Foundation both explicitly invite outside contributors to their open frameworks, and AI Standards Lab is small enough for direct contact. The formal standards bodies (NIST, ISO, CEN-CENELEC, IEEE) work through public comment periods and technical committee membership rather than informal entry.', 'b08', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.public-policy.whistleblower-protection', (SELECT id FROM public.subareas WHERE slug = 'society.public-policy'), 'Whistleblower protection', 'Legal and organisational mechanisms that let employees or contractors at AI companies safely report safety-relevant concerns, near-misses or violations, including protection from retaliation and channels for right-to-warn disclosures.', 'It prevents safety-relevant information from staying trapped inside a company because employees fear losing their job, equity, or facing legal action for speaking up.', 'Statutory protections, not just company policy, covering AI-sector employees specifically, tested in practice by real cases, plus safe and credible external channels that a whistleblower can actually use.',
  '{"title":"How to Design AI Whistleblower Legislation (Institute for Law & AI)","url":"https://law-ai.org/how-to-design-ai-whistleblower-legislation/"}'::jsonb, '[{"name":"California''s frontier AI whistleblower protections (SB 53, 2025)","url":"https://www.gtlaw.com/en/insights/2025/10/california-expands-whistleblower-retaliation-protections-for-employees-in-the-ai-sector"},{"name":"EU AI Act Article 87: the EU Whistleblower Directive applies to AI Act breaches","url":"https://artificialintelligenceact.eu/article/87/"},{"name":"Connecticut SB 5 and Illinois SB 315 (2026)","url":"https://www.dwt.com/blogs/artificial-intelligence-law-advisor/2026/05/ct-ai-transparency-safety-consumer-protection-law"},{"name":"Proposed US federal AI Whistleblower Protection Act","url":"https://www.whistleblowers.org/news/the-future-of-ai-regulation-the-ai-whistleblower-protection-act/"}]'::jsonb, 'Legal protection created and enforced by government. Practical legal, financial and reputational support from outside organisations is meta.watchdogs.whistleblower-support; internal channels are model.developer-assurance.internal-safety-governance.', '{}'::text[],
  'thin', 'Statutory protection now exists in California, Connecticut, Illinois and the EU but is untested, and only a handful of organisations work on the law itself.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'medium', FALSE,
  NULL, 'LawAI (legal design), the National Whistleblower Center (federal campaign and support for individuals) and the AI Whistleblower Initiative (policy advocacy alongside its support work) are all small enough to contact directly. Anyone with employment-law experience can usefully track how the new state and EU protections are being used.', 'b08', 4,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.public-policy.regulatory-capacity', (SELECT id FROM public.subareas WHERE slug = 'society.public-policy'), 'Government technical capacity', 'The technical staff, compute, tools and institutional knowledge a government needs to understand frontier AI, test it and act on what it finds. That might sit in a regulator with enforcement powers (such as the EU AI Office) or in a non-regulatory technical institute that advises ministers and tests models by agreement (such as the UK AI Security Institute or the US Center for AI Standards and Innovation). This is separate from the text of the law itself.', 'It prevents a situation where good laws exist on paper but regulators lack the technical expertise or resources to tell whether a company is actually complying, letting enforcement become theatre.', 'Regulatory bodies with in-house technical staff able to run their own evaluations, interpret companies'' safety claims critically, and keep pace with the state of the art, comparable to how financial regulators employ their own quants.',
  '{"title":"Regulating AI in the UK (Ada Lovelace Institute, 2023)","url":"https://www.adalovelaceinstitute.org/report/regulating-ai-in-the-uk/"}'::jsonb, '[{"name":"US Center for AI Standards and Innovation (CAISI) capacity-building","url":"https://www.nist.gov/caisi"},{"name":"UK AISI''s pre-deployment evaluation capacity","url":"https://www.aisi.gov.uk"}]'::jsonb, 'Technical capacity inside one government. Coordination between national institutes is society.international-governance.institutions; the independent auditors a regulator might rely on are model.developer-assurance.third-party-auditing; public grant funding for independent research is meta.funding.funding-concentration.', '{}'::text[],
  'active', 'The EU AI Office, UK AISI, US CAISI and a network of national institutes give some governments real technical capacity, while most governments, sector regulators and US states have little.', ARRAY['government']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'high', FALSE,
  NULL, 'UK AISI and CAISI both post job openings for technical staff evaluating frontier models. CLTR runs an expert-placement route into UK government for people with a relevant policy or technical background.', 'b08', 5,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.public-policy.agent-infrastructure', (SELECT id FROM public.subareas WHERE slug = 'society.public-policy'), 'Agent identity, visibility and protocols', 'The shared infrastructure that would let people, companies and governments know which AI agents are acting, on whose behalf and with what permissions: identifiers and authentication for agents, logs and disclosure of agent activity, and the protocols agents use to call tools and talk to each other. Most of this is being built now by companies and standards bodies, and whether it supports accountability depends on choices made early.', 'Without identity and visibility, harms caused by agents cannot be traced, rules for agents cannot be enforced, and an incident involving many agents cannot be reconstructed or stopped.', 'Widely adopted open standards for agent identity and authorisation, activity records that incident investigators and regulators can use, and protocols that carry accountability information by default.',
  '{"title":"Infrastructure for AI Agents (Chan et al., 2025)","url":"https://arxiv.org/abs/2501.10114"}'::jsonb, '[{"name":"AI Agent Standards Initiative (NIST Center for AI Standards and Innovation, February 2026)","url":"https://www.nist.gov/news-events/news/2026/02/announcing-ai-agent-standards-initiative-interoperable-and-secure"},{"name":"IDs for AI Systems (GovAI)","url":"https://www.governance.ai/research-paper/ids-for-ai-systems"},{"name":"The 2025 AI Agent Index: technical and safety features of deployed agents","url":"https://arxiv.org/abs/2602.17753"}]'::jsonb, 'Rules and shared infrastructure for identifying and tracing agents across developers and deployers. Securing a particular agent against attack is model.model-security.agent-security; who is liable when an agent causes harm is society.public-policy.agent-accountability; standards for AI in general are society.public-policy.standards; interactions between agents as a systemic risk are society.structural-risk.multi-agent-risk.', '{}'::text[],
  'thin', 'NIST launched an AI Agent Standards Initiative in February 2026 and GovAI publishes the core research on agent IDs and visibility, while the protocols themselves are being built by companies with little accountability design.', ARRAY['government', 'independent-ai-safety', 'commercial']::text[], NULL, 'not-applicable', NULL,
  ARRAY['agents']::text[], 'Early standards work, including NIST''s AI Agent Standards Initiative (launched February 2026, with a workstream on agent identity and authorisation), industry protocols for tool use and agent-to-agent communication, and research proposals for agent IDs and activity logs; no identity scheme is yet widely adopted.', 'medium', FALSE,
  NULL, 'NIST''s initiative has sought public input, and GovAI publishes the core research. Engineers working on agent protocols and authentication in industry are building the infrastructure itself, and proposing accountability features there is open ground.', NULL, 6,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.international-governance.treaties', (SELECT id FROM public.subareas WHERE slug = 'society.international-governance'), 'International agreements', 'Proposed and existing multilateral agreements that set shared rules for AI. The only binding treaty so far is the Council of Europe Framework Convention on AI (2024), which covers human rights, democracy and the rule of law, not frontier-model risk. It has been signed by the US, UK and EU and ratified by the EU. Everything aimed at frontier risk is non-binding (summit commitments) or proposed (red lines, draft treaties limiting frontier development).', 'It prevents a situation where safety measures adopted by one country are undercut by another country''s more permissive rules, recreating race dynamics at the international level.', 'At least one substantive, verifiable agreement among the states that host frontier AI development, with real consequences for non-compliance, rather than a non-binding communique.',
  '{"title":"International AI Institutions: A Literature Review of Models, Examples, and Proposals (Maas and Villalobos, LawAI, 2023)","url":"https://law-ai.org/international-ai-institutions/"}'::jsonb, '[{"name":"The summit series: Bletchley AI Safety Summit 2023, Seoul 2024, Paris AI Action Summit 2025, India AI Impact Summit 2026","url":"https://www.gov.uk/government/topical-events/ai-safety-summit-2023"},{"name":"Council of Europe Framework Convention on AI (CETS 225)","url":"https://www.coe.int/en/web/artificial-intelligence/the-framework-convention-on-artificial-intelligence"},{"name":"Global Call for AI Red Lines (launched at the UN General Assembly, September 2025)","url":"https://red-lines.ai/"},{"name":"MIRI Technical Governance Team''s draft international agreement to prevent premature superintelligence (2025)","url":"https://techgov.intelligence.org/research/an-international-agreement-to-prevent-the-premature-creation-of-artificial-superintelligence"},{"name":"ControlAI''s campaign for a binding international agreement","url":"https://controlai.com"}]'::jsonb, 'Negotiating and keeping agreements between states. Checking compliance is society.compute-governance.agreement-verification; the incentive problem is society.structural-risk.race-dynamics; unilateral company commitments are model.developer-assurance.frontier-safety-frameworks.', '{}'::text[],
  'active', 'Advocacy and research on red lines and draft treaties has grown (AI Red Lines, MIRI, ControlAI, The Future Society, CeSIA), but government treaty-making on frontier risk has not started.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'medium', FALSE,
  NULL, 'ControlAI and The Future Society both campaign and research openly for binding international agreements and take on volunteers and researchers; this is one of the more advocacy-shaped, less technical entry points in the map.', 'b08', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.international-governance.institutions', (SELECT id FROM public.subareas WHERE slug = 'society.international-governance'), 'International institutions', 'Standing multilateral bodies that convene governments, and sometimes industry and civil society, on AI on an ongoing basis. Examples are the OECD (which now hosts the Global Partnership on AI), the UN''s Independent International Scientific Panel on AI and Global Dialogue on AI Governance, and the network of national AI safety and security institutes, renamed the International Network for Advanced AI Measurement, Evaluation and Science, through which national institutes coordinate testing methods.', 'Without standing venues, coordination depends on one-off summits and technical findings stay national.', 'Institutions with clear mandates and enough technical capacity to produce joint outputs, such as shared evaluation methods, that members actually adopt.',
  '{"title":"Governing AI for Humanity: final report of the UN High-Level Advisory Body on AI","url":"https://www.un.org/en/ai-advisory-body"}'::jsonb, '[{"name":"OECD.AI Policy Observatory, OECD AI Principles and the integrated Global Partnership on AI","url":"https://oecd.ai"},{"name":"UN Independent International Scientific Panel on AI and the Global Dialogue on AI Governance (established August 2025)","url":"https://www.un.org/independent-international-scientific-panel-ai/en"},{"name":"International Network for Advanced AI Measurement, Evaluation and Science (formerly the International Network of AI Safety Institutes)","url":"https://www.aisi.gov.uk/blog/international-evaluation-best-practice-and-open-questions-in-ai-measurement"},{"name":"G7 Hiroshima AI Process reporting framework, run by the OECD","url":"https://transparency.oecd.ai/"}]'::jsonb, 'The standing bodies. Capacity inside any one government is society.public-policy.regulatory-capacity; who gets a seat is society.international-governance.inclusive-participation; the evaluations institutes run are model.evaluations.dangerous-capability-evals.', '{}'::text[],
  'active', 'The OECD, the UN''s Scientific Panel and Global Dialogue, and the renamed network of national institutes meet regularly and produce joint outputs; whether members adopt them is the open question.', ARRAY['government']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'high', FALSE,
  NULL, 'OECD.AI and the UN Scientific Panel are government-run and not open to informal outside contribution; WEF''s AI Governance Alliance is comparatively more open to non-governmental participants, and the Simon Institute (see inclusive-participation) is the more realistic non-governmental route into this space generally.', 'b08', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.international-governance.great-power-dialogue', (SELECT id FROM public.subareas WHERE slug = 'society.international-governance'), 'US-China and cross-bloc dialogue', 'Official and unofficial channels between the states most central to frontier AI, above all the United States and China, covering competition (export controls, chip restrictions) and cooperation (safety dialogues, crisis communication), including track-two dialogue between researchers and policy communities where government channels are thin.', 'Any serious limit on dangerous AI development needs the leading powers to trust each other enough to agree and verify; without channels, misunderstandings escalate.', 'Durable government-to-government safety dialogue backed by sustained researcher-level exchanges that survive political shocks, extended to other country pairs.',
  '{"title":"A Path Forward on AI Safety for the United States and China (Carnegie Endowment, 2026)","url":"https://carnegieendowment.org/emissary/2026/07/ai-safety-parallel-us-china"}'::jsonb, '[{"name":"Concordia AI''s bridging research and State of AI Safety in China report","url":"https://concordia-ai.com"},{"name":"IDAIS consensus statements from the International Dialogues on AI Safety (Safe AI Forum)","url":"https://idais.ai/"},{"name":"Proposed US-China AI safety notification channel between Treasury Secretary Bessent and Vice Premier He Lifeng (September 2026)","url":"https://www.cnn.com/2026/09/20/business/us-china-trade-talks-ai-intl-hnk"}]'::jsonb, 'The relationship and dialogue. The instrument of chip controls is society.compute-governance.export-controls; the military crisis risk is society.structural-risk.strategic-stability; formal treaty negotiation is society.international-governance.treaties.', '{}'::text[],
  'active', 'Track-1.5 and track-2 dialogues (IDAIS, Concordia AI, Carnegie) continue and US-China government talks in September 2026 discussed a notification mechanism, with other country pairs thinly served.', ARRAY['independent-ai-safety', 'academia']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'high', FALSE,
  NULL, 'Concordia AI publishes an open, English-language State of AI Safety in China report and welcomes outside researchers; Safe AI Forum''s IDAIS series is the most direct route into being part of a future dialogue.', 'b08', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.international-governance.inclusive-participation', (SELECT id FROM public.subareas WHERE slug = 'society.international-governance'), 'Inclusive participation in global governance', 'Efforts to ensure that countries outside the small group hosting frontier AI development, especially in the Global South, can meaningfully participate in shaping international AI governance rather than having rules set without them.', 'It prevents international AI governance from being written by and for a handful of wealthy states, which risks rules that ignore other countries'' interests and undermines the legitimacy and durability of any agreement reached.', 'Diplomats and technical experts from a broad range of countries actively shaping, not just receiving briefings on, major international AI governance processes, backed by their own domestic technical capacity.',
  '{"title":"Governing AI for Humanity, final report of the UN High-Level Advisory Body on AI (2024), especially its finding that 118 countries were party to none of the major non-UN AI governance initiatives","url":"https://www.un.org/en/ai-advisory-body"}'::jsonb, '[{"name":"Simon Institute''s diplomatic capacity-building programme","url":"https://simoninstitute.ch"},{"name":"UN AI Advisory Body''s attention to global representation","url":"https://www.un.org/en/ai-advisory-body"},{"name":"Global Index on Responsible AI (Global Center on AI Governance)","url":"https://www.global-index.ai/"}]'::jsonb, 'Who gets a real voice in society.international-governance.institutions. Cyber defensive capacity in the same countries is misuse.cyber.defensive-capacity-gaps; local safety communities are meta.convenings.regional-hubs.', '{}'::text[],
  'thin', 'A few dedicated organisations (Simon Institute, ILINA, the Global Center on AI Governance) serve a widely acknowledged need, with growing interest from larger think tanks.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'medium', FALSE,
  NULL, 'Simon Institute runs fellowships placing people into Geneva-based diplomatic capacity-building; ILINA runs an African-led AI safety and policy talent programme. Both are realistic entry points for non-technical contributors.', 'b08', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.compute-governance.export-controls', (SELECT id FROM public.subareas WHERE slug = 'society.compute-governance'), 'Chip export controls and diversion', 'Government restrictions on selling advanced AI chips and chip-making equipment to specific countries or entities, and the technical and administrative means of tracking where chips end up so that smuggling and diversion around the rules can be detected.', 'It prevents states of concern from rapidly closing the compute gap with leading AI developers, one of the few concrete levers governments currently have over the pace of frontier AI development elsewhere.', 'Export rules that are well-targeted, restricting genuinely risk-relevant compute without needlessly harming unrelated trade, consistently enforced across allied countries, and hard to circumvent through smuggling or shell entities.',
  '{"title":"Computing Power and the Governance of Artificial Intelligence (Sastry, Heim et al., 2024)","url":"https://arxiv.org/abs/2402.08797"}'::jsonb, '[{"name":"US Bureau of Industry and Security''s AI chip export rules","url":"https://www.bis.gov"},{"name":"CSET''s compute and export-control policy analysis","url":"https://cset.georgetown.edu"},{"name":"CNAS''s AI chip supply chain security work","url":"https://www.cnas.org/publications/reports/technology-to-secure-the-ai-chip-supply-chain-a-primer"}]'::jsonb, 'The rule and its enforcement. Verifying what chips are computing, for agreements, is society.compute-governance.agreement-verification; the wider US-China relationship is society.international-governance.great-power-dialogue; export controls on surveillance tools are misuse.surveillance.export-controls.', '{}'::text[],
  'active', 'CSET, CSIS, IAPS, CNAS, RAND and Epoch AI analyse rule design, chokepoints and diversion and BIS enforces, while the policy itself has swung back and forth since 2025.', ARRAY['independent-ai-safety', 'government']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'high', FALSE,
  '{"title":"IAPS compute governance research (tag page, updated continuously)","url":"https://www.iaps.ai/research/tag/Compute+governance"}'::jsonb, 'IAPS publishes the most open, hands-on compute-governance research agenda; Epoch AI is hiring and publishes open problems in compute forecasting and diversion tracking.', 'b08', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.compute-governance.agreement-verification', (SELECT id FROM public.subareas WHERE slug = 'society.compute-governance'), 'Verifying AI agreements', 'The technical mechanisms and protocols that let one party check that a state or developer is complying with an agreement about AI development: hardware features in chips, such as secure enclaves and cryptographic attestation, that report how much compute was used and for what, plus the inspection and protocol design that would make such evidence usable between rivals, by analogy with nuclear arms-control verification.', 'Agreements that cannot be verified are unlikely to be made between rivals, and unlikely to hold if made.', 'Chips shipping with agreed, privacy-preserving verification features and a tested protocol that two rival states could actually use.',
  '{"title":"What Does It Take to Catch a Chinchilla? Verifying Rules on Large-Scale Neural Network Training via Compute Monitoring (Shavit, 2023)","url":"https://arxiv.org/abs/2303.11341"}'::jsonb, '[{"name":"IAPS compute governance and verification research","url":"https://www.iaps.ai/research/tag/Compute+governance"},{"name":"CNAS''s hardware-enabled mechanisms and on-chip governance framework","url":"https://www.cnas.org/publications/reports/secure-governable-chips"},{"name":"Flexible Hardware-Enabled Guarantees (flexHEG) design reports","url":"https://flexheg.com"},{"name":"MIRI Technical Governance Team''s work on verifying international agreements","url":"https://techgov.intelligence.org/research"},{"name":"Hardware-Level Governance of AI Compute feasibility taxonomy","url":"https://arxiv.org/html/2604.04712v1"}]'::jsonb, 'Verification for governance. Integrity checks on a single model are model.model-security.supply-chain-and-integrity; the agreements themselves are society.international-governance.treaties; tracking where chips physically go for export enforcement is society.compute-governance.export-controls.', ARRAY['Agreement verification technology']::text[],
  'active', 'Research momentum grew through 2026 with several substantive papers and a small open-source hardware project (FlexHEG), though nothing is fielded.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  ARRAY['defensive-technology']::text[], NULL, 'medium', FALSE,
  '{"title":"Near-Term Verification Methods for AI Chip Exports (Avellar and Grunewald, arXiv, September 2026)","url":"https://arxiv.org/abs/2609.07637"}'::jsonb, 'FlexHEG is an open-source community that takes outside contributors directly; IAPS publishes a full open compute-governance research agenda and is often hiring. This is one of the more tractable technical entry points in compute governance for someone with a hardware or cryptography background.', 'b08', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.compute-governance.cloud-kyc', (SELECT id FROM public.subareas WHERE slug = 'society.compute-governance'), 'Cloud compute know-your-customer', 'Know-your-customer obligations and usage-reporting requirements placed on cloud infrastructure providers, so that governments can see who is renting large amounts of AI-relevant compute and for what.', 'It prevents actors from bypassing chip export controls entirely by renting compute in the cloud from a provider based in an unrestricted jurisdiction.', 'Cloud providers reliably identifying and reporting large training runs and high-risk customers to relevant regulators, implemented in a way that is technically enforceable and does not simply push activity to non-compliant providers.',
  '{"title":"Oversight for Frontier AI through a Know-Your-Customer Scheme for Compute Providers (Egan and Heim, 2023)","url":"https://arxiv.org/abs/2310.13625"}'::jsonb, '[{"name":"US BIS proposed IaaS know-your-customer rule","url":"https://www.bis.gov"},{"name":"IAPS compute governance research on threshold-based reporting","url":"https://www.iaps.ai/research/tag/Compute+governance"}]'::jsonb, 'Rented access to compute that never crosses a border as a physical good. Hardware sales are society.compute-governance.export-controls.', '{}'::text[],
  'thin', 'IAPS and GovAI researchers have done most of the design work, with the US know-your-customer rule for cloud providers still unfinalised.', ARRAY['independent-ai-safety', 'government']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'medium', FALSE,
  NULL, 'IAPS is the clearest entry point, publishing openly on this exact gap and generally open to outside researchers.', 'b08', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.economic-transition.labour-disruption', (SELECT id FROM public.subareas WHERE slug = 'society.economic-transition'), 'Labour market disruption', 'The disruption to jobs, wages and skill demand as AI automates tasks, and research modelling how fast and unevenly this could happen, so that policymakers get lead time rather than reacting after the fact.', 'It prevents a transition that is fast enough, or concentrated enough in specific sectors and regions, to cause serious social and political instability before adaptation mechanisms such as retraining or safety nets can catch up.', 'Reliable, early data on which jobs and sectors are actually being automated and how fast, feeding into retraining and social-support programmes that are ready before mass displacement rather than after.',
  '{"title":"Canaries in the Coal Mine? Six Facts about the Recent Employment Effects of Artificial Intelligence (Brynjolfsson, Chandar and Chen, Stanford Digital Economy Lab, 2025)","url":"https://digitaleconomy.stanford.edu/publication/canaries-in-the-coal-mine-six-facts-about-the-recent-employment-effects-of-artificial-intelligence/"}'::jsonb, '[{"name":"Stanford Digital Economy Lab''s AI Economic Indicators","url":"https://digitaleconomy.stanford.edu/project/indicators/"},{"name":"Anthropic Economic Index","url":"https://www.anthropic.com/economic-index"},{"name":"OECD AI and Work programme and Employment Outlook","url":"https://www.oecd.org/en/topics/ai-and-work.html"}]'::jsonb, 'Who loses work and how fast. Who captures the gains is society.economic-transition.sharing-gains; how income support adapts is society.economic-transition.safety-nets; general capability timelines are meta.evidence.capability-forecasting.', '{}'::text[],
  'active', 'Labour economists (Stanford Digital Economy Lab, MIT, Brookings, the OECD, the IMF) track AI''s effects on work in close to real time, helped by developers'' usage data.', ARRAY['another-field']::text[], 'labour economics', 'strong', 'Developers now publish occupation-level usage data (Anthropic''s Economic Index) that economists use and economists'' analyses reach labs'' policy teams; what flows less is AI safety''s fast-scenario thinking into mainstream labour forecasts.',
  '{}'::text[], 'Real-time measurement infrastructure now exists (Stanford''s dashboards, Anthropic''s index) that did not a year ago; substantive policy mitigations (retraining pipelines, portable benefits) remain mostly proposals rather than adopted programmes, per Brookings'' and Windfall Trust''s own framing.', 'medium', FALSE,
  '{"title":"Research on AI and the labor market is still in the first inning (Brookings/PIIE)","url":"https://www.brookings.edu/articles/research-on-ai-and-the-labor-market-is-still-in-the-first-inning/"}'::jsonb, 'Stanford Digital Economy Lab and the Anthropic Economic Index both publish open data and methodology that a researcher can build on without an insider connection; Epoch AI is hiring for forecasting work including GATE; Brookings and OECD publish open calls for policy fellows. This node has moved from thin to genuinely well-populated in the last twelve months.', 'b07', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.economic-transition.sharing-gains', (SELECT id FROM public.subareas WHERE slug = 'society.economic-transition'), 'Sharing the gains from AI', 'Proposed mechanisms, such as windfall clauses, sovereign wealth-style funds, or new tax instruments, for ensuring the economic gains from transformative AI are shared broadly rather than captured almost entirely by a small number of AI developers and investors.', 'It prevents extreme wealth concentration from advanced AI, which could itself become a driver of the power-concentration and social-instability risks covered elsewhere in this layer.', 'At least one credible, tested mechanism, such as a windfall clause signed by a major lab or a state-level sovereign fund tied to AI-driven growth, actually in force before the bulk of AI-driven gains materialise, rather than proposed only after the fact.',
  '{"title":"The Windfall Clause: Distributing the Benefits of AI for the Common Good (O''Keefe et al., GovAI)","url":"https://www.governance.ai/research-paper/the-windfall-clause-distributing-the-benefits-of-ai-for-the-common-good"}'::jsonb, '[{"name":"Windfall Trust''s Windfall Policy Atlas","url":"https://windfalltrust.org/policy-atlas"},{"name":"OpenAI''s 2025 recapitalisation, which gave the nonprofit OpenAI Foundation a large equity stake in the for-profit company, as a live test of developer-side benefit sharing","url":"https://openai.com/index/built-to-benefit-everyone/"}]'::jsonb, 'What happens to the surplus AI generates. Job loss itself is society.economic-transition.labour-disruption; conventional welfare machinery is society.economic-transition.safety-nets; power that flows from the same concentration of gains is society.structural-risk.concentration-of-power.', '{}'::text[],
  'thin', 'Essentially one dedicated organisation (Windfall Trust) plus GovAI''s original proposal, with no mechanism yet adopted by a developer or government.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'No windfall clause has been adopted. Partial precedents exist but were not designed for broad sharing: the OpenAI Foundation''s equity stake after the October 2025 recapitalisation, and US government equity and revenue-share arrangements with chip firms in 2025. The Windfall Policy Atlas remains a catalogue of mostly unadopted options.', 'high', FALSE,
  '{"title":"Windfall Policy Atlas (Windfall Trust)","url":"https://windfalltrust.org/policy-atlas"}'::jsonb, 'Windfall Trust accepts contact through its site and publishes open research; it is effectively the single organisation to approach for anyone wanting to work on this problem specifically, alongside Forethought for the wider macrostrategy angle.', 'b07', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.economic-transition.safety-nets', (SELECT id FROM public.subareas WHERE slug = 'society.economic-transition'), 'Adapting safety nets', 'How existing welfare, healthcare, retraining and income-support systems need to change to remain functional if AI causes faster or larger-scale economic disruption than they were designed to handle.', 'It prevents a gap opening between when displacement happens and when support systems, built for a slower and more localised pace of technological change, catch up, which is when the sharpest social harm occurs.', 'Pilot programmes and policy proposals, such as portable benefits, faster retraining pipelines, and contingency funding triggers tied to measurable displacement indicators, tested and ready to scale before a crisis rather than designed reactively.',
  '{"title":"Gen-AI: Artificial Intelligence and the Future of Work (IMF Staff Discussion Note, 2024)","url":"https://www.imf.org/en/Publications/Staff-Discussion-Notes/Issues/2024/01/14/Gen-AI-Artificial-Intelligence-and-the-Future-of-Work-542379"}'::jsonb, '[{"name":"Windfall Trust''s broader policy-option catalogue","url":"https://windfalltrust.org"}]'::jsonb, 'The welfare-state machinery that must flex regardless of where the money comes from. Capturing and redirecting the surplus is society.economic-transition.sharing-gains.', '{}'::text[],
  'thin', 'Welfare economists and policy institutions study AI and work, and Windfall Trust covers safety-net redesign as one strand, but almost nobody designs for fast, economy-wide disruption.', ARRAY['another-field']::text[], 'social policy and welfare economics', 'weak', 'Fast-scenario assumptions from AI safety, and indicators of displacement from developers'' usage data, should flow into mainstream welfare design, which still assumes adoption spread over many years.',
  '{}'::text[], 'No AI-disruption-specific safety-net redesign has been adopted anywhere; existing welfare systems remain built for slower, more localised technological change.', 'medium', FALSE,
  NULL, 'Windfall Trust is the most direct entry point given its dedicated policy-option catalogue; Brookings publishes fellowships and open workforce-policy research for those coming from a more conventional social-policy background.', 'b07', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.epistemics.collective-reasoning', (SELECT id FROM public.subareas WHERE slug = 'society.epistemics'), 'AI and collective reasoning', 'How the growing use of AI to summarise, filter and mediate information changes society''s capacity to reason accurately and reach shared understanding, for better or worse.', 'It prevents a slow degradation of society''s ability to identify true claims and make sound collective decisions, which would undermine the basis for almost all other governance responses to AI risk.', 'Measurable evidence that AI-mediated information systems improve, rather than degrade, people''s calibration and shared understanding of contested facts, tracked over time rather than assumed.',
  '{"title":"How Will Advanced AI Systems Impact Democracy? (Summerfield et al., 2024)","url":"https://arxiv.org/abs/2409.06729"}'::jsonb, '[{"name":"AI Objectives Institute''s work on AI for collective sense-making","url":"https://aiobjectives.org"},{"name":"Forecasting Research Institute''s work on improving judgement quality","url":"https://forecastingresearch.org"}]'::jsonb, 'The diagnostic question of what ordinary AI use does to shared reasoning. Deliberate manipulation is misuse.influence-operations; tools that actively help are society.epistemics.deliberation-tools and society.epistemics.decision-quality.', '{}'::text[],
  'thin', 'The AI Objectives Institute and Forecasting Research Institute research it, and deployed systems such as Community Notes and Full Fact are studied for their effects.', ARRAY['independent-ai-safety', 'commercial']::text[], NULL, 'not-applicable', NULL,
  ARRAY['democracy']::text[], 'Community Notes and Full Fact''s tools are deployed, evidence-backed interventions at meaningful scale, though neither was designed with AI-safety framing; both are best read as existing real-world evidence about whether AI-mediated systems can help rather than purpose-built safety interventions.', 'medium', FALSE,
  NULL, 'AI Objectives Institute and Forecasting Research Institute both publish open research and take on researchers; Full Fact publishes technical detail on its claim-matching pipeline and is a plausible place to contribute for someone from an NLP or civic-tech background. Community Notes'' bridging algorithm is open source (birdwatch/Community Notes GitHub), a low-friction way to study or extend a real deployed system without joining X.', 'b07', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.epistemics.deliberation-tools', (SELECT id FROM public.subareas WHERE slug = 'society.epistemics'), 'Deliberation tools', 'AI-assisted tools designed to help large groups of people deliberate, express nuanced views, and reach legitimate collective decisions, such as AI-mediated public consultation platforms.', 'It prevents democratic and civic institutions from becoming purely reactive to AI-driven change, by giving them AI-assisted means to actually incorporate broad public input into fast-moving decisions.', 'Deliberation tools used by real governments or institutions at meaningful scale, with independent evidence that they improve, rather than merely simulate, legitimate collective decision-making.',
  '{"title":"AI Can Help Humans Find Common Ground in Democratic Deliberation (Tessler et al., Science, 2024)","url":"https://www.science.org/doi/10.1126/science.adq2852"}'::jsonb, '[{"name":"AI Objectives Institute''s Talk to the City deliberation tool","url":"https://ai.objectives.institute/talk-to-the-city"},{"name":"Polis, the open-source deliberation platform (Computational Democracy Project)","url":"https://compdemocracy.org"},{"name":"Collective Intelligence Project''s Global Dialogues and Alignment Assemblies","url":"https://www.cip.org/"}]'::jsonb, 'Tools for publics and large groups to deliberate. Tools for specific high-stakes institutional decisions are society.epistemics.decision-quality; the diagnostic question is society.epistemics.collective-reasoning.', '{}'::text[],
  'active', 'The AI Objectives Institute, the Collective Intelligence Project and the Computational Democracy Project run tools with real government and institutional use, with limited independent evidence that they improve decisions.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  ARRAY['democracy']::text[], 'Polis has demonstrated adoption at national scale in Taiwan and reported use in the UK; Talk to the City and CIP''s Global Dialogues have been used in specific consultation pilots; none yet has the kind of routine, large-scale institutional adoption the node''s ''progress looks like'' criterion describes.', 'medium', FALSE,
  NULL, 'The Computational Democracy Project is open source (github.com/compdemocracy) and welcomes external contributors and researchers directly; the Collective Intelligence Project runs an annual research fellowship; AI Objectives Institute takes on researchers for Talk to the City. This is one of the more approachable nodes for a technically-minded entrant.', 'b07', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.epistemics.content-provenance', (SELECT id FROM public.subareas WHERE slug = 'society.epistemics'), 'Content provenance and deepfake detection', 'Standards and tools for marking AI-generated or manipulated content at creation (provenance, watermarking, authentication) and for detecting it afterwards, so that people and platforms can tell synthetic media from authentic recordings whatever the intent behind it.', 'If authentic and synthetic media cannot be told apart, evidence, journalism and identity checks lose their value, and genuine recordings can be dismissed as fake.', 'Provenance widely adopted across capture devices, generators and platforms, and detection that keeps pace with the newest generators.',
  '{"title":"Reducing Risks Posed by Synthetic Content: An Overview of Technical Approaches to Digital Content Transparency (NIST AI 100-4, 2024)","url":"https://nvlpubs.nist.gov/nistpubs/ai/NIST.AI.100-4.pdf"}'::jsonb, '[{"name":"C2PA content provenance standard","url":"https://c2pa.org"},{"name":"EU AI Act Article 50 marking and disclosure duties (applying from August 2026) and the Commission''s code of practice on labelling AI-generated content","url":"https://artificialintelligenceact.eu/article/50/"},{"name":"China''s measures for labelling AI-generated content (in force September 2025)","url":"https://digichina.stanford.edu/"},{"name":"Google DeepMind''s SynthID watermarking","url":"https://deepmind.google/models/synthid/"},{"name":"Partnership on AI''s guidance on synthetic media","url":"https://partnershiponai.org"}]'::jsonb, 'General-purpose infrastructure. Its use against covert campaigns is misuse.influence-operations.covert-campaigns and against fraud is misuse.fraud-and-abuse.fraud-and-impersonation; AI management standards are society.public-policy.standards.', '{}'::text[],
  'active', 'An industry standards coalition (C2PA), Partnership on AI and a growing set of detection vendors work here, with uneven adoption and detection lagging the newest generators.', ARRAY['commercial']::text[], NULL, 'not-applicable', NULL,
  ARRAY['democracy', 'defensive-technology']::text[], 'C2PA provenance metadata is now supported by some capture devices and generative tools; commercial detection tools such as GetReal Security''s platform are deployed for fraud and impersonation defence; neither keeps pace fully with the newest generation models.', 'medium', FALSE,
  NULL, 'C2PA''s specification and working groups are open to join; GetReal Security is a commercial employer for anyone with a detection or biometrics background; Partnership on AI publishes open guidance documents anyone can build on.', 'b07', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.epistemics.decision-quality', (SELECT id FROM public.subareas WHERE slug = 'society.epistemics'), 'Decision quality in key institutions', 'Whether the governments, regulators, courts and company boards that will make the most consequential decisions about AI can reason well under uncertainty and resist being overwhelmed or manipulated, including purpose-built AI tools that help with specific high-stakes decisions.', 'The most important decisions about AI will be made quickly by a small number of institutions; if their reasoning is poor, good evidence elsewhere is wasted.', 'Decision-makers routinely using well-tested forecasting and AI decision-support tools, with evidence that they improve decisions.',
  '{"title":"AI Tools for Existential Security (Vaintrob and Cotton-Barratt, Forethought, 2025)","url":"https://www.forethought.org/research/ai-tools-for-existential-security"}'::jsonb, '[{"name":"Effective Institutions Project''s work on institutional capacity","url":"https://effectiveinstitutionsproject.org"},{"name":"Quantified Uncertainty Research Institute''s tools for reasoning under uncertainty","url":"https://quantifieduncertainty.org"},{"name":"AI for decision-makers (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#ai-for-decision-makers"}]'::jsonb, 'The decision-makers and tools for them. Producing the evidence is meta.evidence; group deliberation by the public is society.epistemics.deliberation-tools.', ARRAY['AI for decision-makers']::text[],
  'thin', 'The Effective Institutions Project and QURI work on it, with Metaculus''s forecasting infrastructure nearby, but decision support for AI-related decisions is rarely anyone''s named mandate.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  ARRAY['defensive-technology']::text[], 'Forecasting tournaments and probabilistic-reasoning tools exist and are used by some institutions on an ad hoc basis; no routine, institutionalised use of these tools by governments or regulators for AI-specific decisions was found.', 'medium', FALSE,
  NULL, 'Effective Institutions Project and QURI both publish open problems and are small enough that direct outreach is realistic; the Tailwind initiative ''AI for decision-makers'' (Coefficient Giving) is an explicit funding call for anyone wanting to build AI tools for high-stakes institutional decisions, and is probably the single most concrete entry point in this node.', 'b07', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.ethics-fairness-welfare.fairness-and-bias', (SELECT id FROM public.subareas WHERE slug = 'society.ethics-fairness-welfare'), 'Fairness and bias', 'Ensuring AI systems do not produce discriminatory or systematically unfair outcomes for people, whether in allocating things like jobs, credit, healthcare or bail, or in how generative systems represent groups (stereotyping, erasure, unequal quality of service across languages and dialects). Includes the accountability side: whether affected people can find out that an AI system was used, contest its decision and get redress.', 'It prevents AI systems from automating and scaling up existing societal discrimination, or introducing new forms of it, often invisibly and at a scale no individual human decision-maker could match.', 'Standard, independently audited fairness testing built into deployment practice for high-stakes AI applications, with legal recourse for people harmed by biased outcomes.',
  '{"title":"Fairness and Machine Learning: Limitations and Opportunities (Barocas, Hardt, Narayanan)","url":"https://fairmlbook.org/"}'::jsonb, '[{"name":"Algorithmic Justice League''s bias research and campaigns","url":"https://ajl.org"},{"name":"Humane Intelligence''s structured bias bounty programmes","url":"https://humane-intelligence.org"},{"name":"ACM FAccT conference and community","url":"https://facctconference.org/"},{"name":"Anti-discrimination rules for AI in law: EU AI Act high-risk regime, New York City Local Law 144 bias audits, Connecticut SB 5 employment provisions","url":"https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai"}]'::jsonb, 'Discriminatory harm to ordinary people. Catastrophic-risk evaluations are model.evaluations; deliberate state control is misuse.surveillance.predictive-policing-and-scoring.', '{}'::text[],
  'active', 'A mature field with its own conference (FAccT), advocacy organisations and a decade of methods, now facing a weaker legal backstop and the open problem of evaluating fairness in general-purpose systems.', ARRAY['another-field']::text[], 'algorithmic fairness and accountability (ML ethics, HCI, law)', 'weak', 'The fairness field works mostly on deployed systems and with regulators, and its methods for representational harm and contestability reach frontier developers and the AI safety community only patchily.',
  '{}'::text[], 'Academic fairness metrics and toolkits, bias bounty programmes (Humane Intelligence), disparate-impact and bias audits (mandatory for hiring tools in New York City), and AI-specific anti-discrimination law in the EU and some US states, some of it deferred or narrowed in 2025-2026.', 'high', FALSE,
  NULL, 'The most approachable route is ACM FAccT itself (open calls for papers and a large annual community) or applying to Algorithmic Justice League''s campaigns and research. Humane Intelligence runs structured bias bounty programmes that welcome outside participants without requiring an existing academic post.', 'b09', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.ethics-fairness-welfare.ai-welfare-and-moral-status', (SELECT id FROM public.subareas WHERE slug = 'society.ethics-fairness-welfare'), 'AI welfare and moral status', 'Whether AI systems could have morally relevant experiences, interests, or a form of wellbeing, and what follows for how they should be developed, deployed and treated if so.', 'It prevents society from either causing large-scale suffering to systems that do turn out to matter morally, or wasting significant resources and credibility on systems that do not, given how much uncertainty currently exists either way.', 'Credible, widely accepted methods for assessing indicators of morally relevant experience in AI systems, feeding into concrete guidance for labs on how to act under that uncertainty.',
  '{"title":"Taking AI Welfare Seriously (Long, Sebo et al., 2024)","url":"https://arxiv.org/abs/2411.00986"}'::jsonb, '[{"name":"Eleos AI''s research programme on AI welfare and moral status","url":"https://eleosai.org/research/"},{"name":"Indicator-properties approach: Consciousness in Artificial Intelligence (Butlin, Long et al., 2023)","url":"https://arxiv.org/abs/2308.08708"},{"name":"Sentient Futures'' incubation of AI welfare projects","url":"https://www.sentientfutures.ai"}]'::jsonb, 'Whether the AI itself is a moral patient. Building ethical reasoning into AI is society.ethics-fairness-welfare.machine-ethics; the human''s wellbeing is society.ethics-fairness-welfare.human-ai-relationships.', '{}'::text[],
  'active', 'A small number of dedicated organisations (Eleos AI, the NYU Center for Mind, Ethics, and Policy, Sentient Futures) and one frontier lab''s programme, in a debate where some senior figures argue that encouraging belief in AI consciousness is itself harmful.', ARRAY['independent-ai-safety', 'frontier-labs', 'academia']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Model welfare assessments in system cards (Anthropic with Eleos), low-cost interventions such as letting a model end persistently abusive conversations (Anthropic, August 2025), published research agendas, and indicator-based frameworks from the science of consciousness for assessing AI systems.', 'high', FALSE,
  '{"title":"Eleos AI Research agenda","url":"https://eleosai.org/research/"}'::jsonb, 'Eleos AI publishes an open research agenda and takes outside collaborators; the NYU Center for Mind, Ethics, and Policy is an academic route in via NYU. Anthropic''s model welfare team is a route for people already able to get hired at a frontier lab.', 'b09', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.ethics-fairness-welfare.machine-ethics', (SELECT id FROM public.subareas WHERE slug = 'society.ethics-fairness-welfare'), 'Machine ethics', 'Building explicit ethical reasoning, values or constraint capability into AI systems, so that they can navigate genuinely ambiguous moral situations rather than only following narrow rules or optimising a fixed objective.', 'It prevents AI systems from making harmful decisions in situations their designers never anticipated and did not write an explicit rule for, by giving them some capacity for principled ethical judgement rather than blind rule-following.', 'AI systems whose ethical reasoning in novel situations can be inspected, predicted and shown to track widely shared moral intuitions, rather than being an unpredictable side-effect of general training.',
  '{"title":"Ethics of Artificial Intelligence and Robotics (Stanford Encyclopedia of Philosophy)","url":"https://plato.stanford.edu/entries/ethics-ai/"}'::jsonb, '[{"name":"Published model specifications and constitutions that state the values a model should reason from (OpenAI Model Spec; Anthropic''s constitution for Claude)","url":"https://model-spec.openai.com/"},{"name":"Academic machine ethics benchmarks and models, such as the ETHICS dataset (Hendrycks et al., 2020) and Delphi (Jiang et al., 2021)","url":"https://arxiv.org/abs/2008.02275"},{"name":"Meaning Alignment Institute''s moral-graph approach to eliciting and aligning to values","url":"https://meaningalignment.substack.com/p/introducing-democratic-fine-tuning"}]'::jsonb, 'Equipping a model to reason about moral trade-offs. Matching developer intent generally is model.alignment; a specific class of harm is society.ethics-fairness-welfare.fairness-and-bias. Much live work sits inside labs'' model-character efforts, measured in model.evaluations.propensity-and-character-evals.', '{}'::text[],
  'thin', 'The live work on how frontier models reason about moral trade-offs happens inside labs under names such as Constitutional AI and model character, while a small academic machine-ethics field works on formal and multi-agent questions.', ARRAY['frontier-labs', 'academia']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Constitutional AI and similar value-based training methods used inside frontier labs to give models explicit constitutions or principles to reason from.', 'medium', FALSE,
  NULL, 'There is no dedicated independent organisation to join. The most concrete entry points are academic: submit to the AAAI Machine Ethics Workshop (MEW), or pursue this inside a frontier lab''s alignment or model-character team (Anthropic, OpenAI, Google DeepMind all publish related work).', 'b09', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'society.ethics-fairness-welfare.human-ai-relationships', (SELECT id FROM public.subareas WHERE slug = 'society.ethics-fairness-welfare'), 'Human-AI relationships and wellbeing', 'The effects of AI systems, especially companion apps, chatbots and highly persuasive assistants, on human mental health, relationships and autonomy, including risks of unhealthy attachment or dependency.', 'It prevents widely deployed, highly engaging AI products from causing diffuse but large-scale harm to mental health and social relationships, a risk that is easy to miss because no single interaction looks catastrophic.', 'Independent, longitudinal evidence on how different types of AI interaction affect wellbeing, feeding into design norms or regulation for companion and highly persuasive AI products, comparable to how social-media wellbeing research eventually informed platform design debates.',
  '{"title":"How AI and Human Behaviors Shape Psychosocial Effects of Chatbot Use: A Longitudinal Randomized Controlled Study (MIT Media Lab and OpenAI, 2025)","url":"https://arxiv.org/html/2503.17473v1"}'::jsonb, '[{"name":"MIT Media Lab and OpenAI''s joint research on chatbot psychosocial effects","url":"https://www.media.mit.edu/articles/chatgpt-might-be-making-its-most-frequent-users-more-lonely-study-by-openai-and-mit-media-lab-suggests/"},{"name":"California SB 243 and state companion-chatbot laws","url":"https://www.techpolicy.press/where-state-ai-legislation-stands-half-way-into-2026/"},{"name":"US FTC 6(b) inquiry into AI chatbots acting as companions (September 2025)","url":"https://www.ftc.gov/news-events/news/press-releases/2025/09/ftc-launches-inquiry-ai-chatbots-acting-companions"}]'::jsonb, 'Harms from ordinary, intended use of companion and assistant products. Deliberate manipulation is misuse.influence-operations.personalised-persuasion; extremist recruitment is misuse.influence-operations.extremist-recruitment; child sexual abuse material is misuse.fraud-and-abuse.csam.', '{}'::text[],
  'active', 'Much busier since 2025: chatbot-harm litigation, an FTC inquiry and new state companion-chatbot laws, with child-safety organisations, HCI and psychology researchers and lab studies all working on it.', ARRAY['another-field', 'frontier-labs']::text[], 'child online safety, psychology and human-computer interaction', 'weak', 'The child-safety side now reaches developers through litigation, regulators and risk assessments, but research on adult dependency, emotional reliance and sycophancy-driven harm flows between HCI, psychology and developers only through scattered studies.',
  '{}'::text[], 'Companion-chatbot statutes (California SB 243 and a wave of 2026 state laws) requiring disclosure that the user is talking to an AI, crisis-referral protocols and protections for minors; age restrictions and parental controls introduced by some providers in 2025; lab-run studies of affective use. Independent verification that these work is still lacking.', 'medium', FALSE,
  NULL, 'For child safety: Common Sense Media, and state legislative and attorney-general offices now drafting and enforcing companion-chatbot rules. For the adult autonomy and dependency question: HCI and psychology labs, and lab research teams working on affective use and sycophancy. A standing independent research programme on adult wellbeing effects would be genuinely new.', 'b09', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.funding.funding-concentration', (SELECT id FROM public.subareas WHERE slug = 'meta.funding'), 'Concentration and diversity of funding', 'Most money for independent AI safety and security work comes from a few philanthropic funders, above all Coefficient Giving (formerly Open Philanthropy). Government money mostly funds national institutes'' own programmes rather than the wider independent ecosystem, and investor capital for safety-focused startups is small and unproven. The node covers how concentrated the funder base is and how far it has diversified.', 'If one or two funders change strategy, whole sub-fields can lose most of their money in a single grant cycle, as happened in 2024 when Good Ventures stopped funding several areas it had previously supported. Concentration also shapes the work itself: organisations drift towards what the dominant funder favours and avoid positions it might dislike, and in policy work a single funder''s name can be used to discredit everyone it funds.', 'A larger and more varied set of funders, including public grant programmes and a proven venture market for safety products, so that no single funder''s exit or pivot is existential for the field.',
  '{"title":"AI Safety and Security Need More Funders (Open Philanthropy, now Coefficient Giving, October 2025)","url":"https://coefficientgiving.org/research/ai-safety-and-security-need-more-funders/"}'::jsonb, '[{"name":"Navigating Transformative AI fund","url":"https://coefficientgiving.org/funds/navigating-transformative-ai/"},{"name":"ARIA Safeguarded AI","url":"https://www.aria.org.uk/programme-safeguarded-ai/"}]'::jsonb, 'Where the money comes from and how varied its sources are. The mechanisms that turn money into working organisations (fiscal sponsors, prizes, incubators) are meta.funding.funding-infrastructure; research on where money should go is meta.evidence.macrostrategy-and-prioritisation. Whether a funder is philanthropic, governmental or venture is recorded on each organisation''s record rather than as separate nodes.', '{}'::text[],
  'active', 'The funder base is widening (safety-focused venture funds, UK AISI''s Alignment Project, ARIA, FLI, AISTOF, SFF, Longview, Manifund, and the Transformative AI Fund after the Long-Term Future Fund closed), but Coefficient Giving and Good Ventures remain dominant.', ARRAY['independent-ai-safety', 'government', 'commercial']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'A widening set of VC funds, government grant programmes (ARIA, UK AISI, NSF) and independent regranting platforms (Manifund, AISTOF) that reduce, but do not eliminate, reliance on a single funder.', 'medium', FALSE,
  '{"title":"Project Tailwind: 36 initiatives","url":"https://coefficientgiving.org/tailwind/initiatives/"}'::jsonb, 'To work on the problem itself, join or advise a donor-advisory team (Longview Philanthropy, Founders Pledge, or Coefficient Giving''s team for partner funders) or become a regrantor on Manifund. For grant seekers: the Long-Term Future Fund closed in August 2026 and the Transformative AI Fund at EA Funds now takes rolling applications for early-stage AI risk projects; SFF runs structured rounds; Manifund is the quickest route for small projects. AISTOF and Longview mostly fund by referral rather than open application.', 'b09', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.funding.funding-infrastructure', (SELECT id FROM public.subareas WHERE slug = 'meta.funding'), 'Funding infrastructure', 'The mechanisms that turn money into working organisations and results: fiscal sponsors and shared back-office services that let a new project operate within weeks, prizes and competitions that pay for verified results, and incubators that find and support founders for identified gaps, including labs built around agendas that have no team. Each exists in the AI safety field, but none has kept pace with the number of gaps funders now name.', 'Money alone does not create organisations. Without sponsorship and back-office capacity founders lose months to compliance; without incubation, well-specified gaps sit unfilled because too few people will found and run something; and without prizes the field has no way to pay for results from people outside the grant-writing community.', 'A funded new project can be operational within weeks, every high-priority gap without an owner has a credible path to a founding team within a year or two, and recurring, well-funded prizes exist for several concretely specified safety problems.',
  '{"title":"Project Tailwind initiatives, Coefficient Giving","url":"https://coefficientgiving.org/tailwind/initiatives/"}'::jsonb, '[{"name":"Fiscal sponsors (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#fiscal-sponsors"},{"name":"Grand awards for AI safety (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#awards-for-ai-safety"},{"name":"Philanthropic startup incubator (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#philanthropic-startup-incubator"},{"name":"Unclaimed research labs (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#unclaimed-research-labs"}]'::jsonb, 'Mechanisms that turn money into organisations and results. Where the money comes from, and how concentrated it is, is meta.funding.funding-concentration; the benchmarks a prize might use are model.evaluations.benchmarks-and-tooling; people joining existing organisations are meta.talent.experienced-professionals.', ARRAY['Fiscal sponsors', 'Grand awards for AI safety', 'Philanthropic startup incubator', 'Unclaimed research labs']::text[],
  'active', 'Several fiscal sponsors and shared-services providers, two incubators and recurring prize arenas operate, and Coefficient Giving still names sponsorship, incubation and large prizes as open gaps.', ARRAY['independent-ai-safety', 'commercial']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Several fiscal sponsors with AI safety sponsees (BERI, Ashgro, Rethink Priorities Special Projects) and shared-services providers such as Impact Ops; two operating incubators (Catalyze Impact and Constellation''s incubator); recurring jailbreak and red-teaming arenas with cash prizes (Gray Swan) and occasional prize-backed competitions (CAIS, Apart Research, Humane Intelligence).', 'medium', FALSE,
  '{"title":"Project Tailwind: 36 initiatives","url":"https://coefficientgiving.org/tailwind/initiatives/"}'::jsonb, 'To add capacity, join the operations team of an existing sponsor (Ashgro, Rethink Priorities Special Projects, BERI) or a shared-services provider such as Impact Ops. Would-be founders can apply to Catalyze Impact''s or Constellation''s incubator cohorts, both of which run open rounds. Gray Swan''s arenas and Apart Research''s sprints are open to anyone and sometimes pay prizes; a standing, large-prize programme for hard problems is the open gap that Coefficient Giving''s ''Grand awards'' initiative describes.', 'b09', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.talent.early-career-bottleneck', (SELECT id FROM public.subareas WHERE slug = 'meta.talent'), 'Early-career pipeline capacity', 'Early-career programmes (MATS, ARENA, SPAR, BlueDot, Pivotal, PIBBSS, ERA, CBAI, Iliad and others) have multiplied; Kairos and Constellation estimate that about 2,000 AI safety research fellows will be trained in 2026. The binding constraint is no longer applicant interest but the field''s capacity to absorb them. Each senior researcher can mentor only a few people, and organisations mostly hire experienced people who need little supervision, so many graduates have nowhere to go next.', 'If programmes grow faster than mentoring capacity and entry-level jobs, quality dilutes, graduates stall after their first fellowship, and the funding and goodwill that built the pipeline are wasted. Programmes also compete for the same mentors instead of dividing the work between them.', 'Programmes coordinate on who serves which stage and specialism, the number of people able and willing to mentor rises measurably, and most fellowship graduates move into safety roles or funded independent work within a year.',
  '{"title":"AI Safety Talent Needs in 2026: Insights for Field-Building, MATS","url":"https://forum.effectivealtruism.org/posts/jwwrC4n9H53doRjRH/ai-safety-talent-needs-in-2026-insights-for-field-building"}'::jsonb, '[]'::jsonb, 'The structural bottleneck across early-career programmes, not a directory of them. Experienced career-changers are meta.talent.experienced-professionals; matching people to roles is meta.talent.matchmaking; senior and specialist hiring is meta.talent.senior-and-specialist-recruitment.', '{}'::text[],
  'active', 'Many fellowships (MATS, ARENA, SPAR, BlueDot and others) are expected to train about 2,000 research fellows in 2026, but work on the binding constraint, mentor bandwidth and jobs for graduates, is limited to MATS''s research and Kairos''s coordination.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Some differentiation by format (bootcamp vs mentored research vs part-time), but largely unaddressed as a shared mentor-capacity problem across programmes.', 'medium', FALSE,
  NULL, 'Newcomers should still start with MATS, ARENA or BlueDot''s courses, with SPAR (run by Kairos) and Apart Research sprints as lower-commitment ways to test fit. For someone who wants to work on the bottleneck itself, the scarce contributions are mentoring, programme operations, and placing people after fellowships, which 80,000 Hours'' fieldbuilding review names as neglected.', 'b09', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.talent.experienced-professionals', (SELECT id FROM public.subareas WHERE slug = 'meta.talent'), 'On-ramps for experienced professionals', 'Experienced professionals (senior engineers, security specialists, policy veterans, operators) who want to move into AI safety have few structured on-ramps, and those already senior in adjacent fields lack the context, relationships and credibility to lead in this one; almost all fellowship infrastructure is built for students and early-career people.', 'The field most needs people who already know how to build, secure and govern things, and it currently turns many of them away or leaves them on the margins.', 'Several well-run programmes that move experienced people into both staff and leadership roles each year, with a track record of placements.',
  '{"title":"SteadRise","url":"https://steadrise.org/"}'::jsonb, '[{"name":"Mid-career entry points (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#mid-career-entry-points"},{"name":"AI context accelerator (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#ai-context-accelerator"}]'::jsonb, 'General on-ramps for experienced people. Active search for named senior specialists is meta.talent.senior-and-specialist-recruitment; early-career programmes are meta.talent.early-career-bottleneck.', ARRAY['Mid-career entry points', 'AI context accelerator']::text[],
  'active', 'SteadRise, Successif, Arcadia Impact and the Horizon Institute run programmes for experienced people, still a handful of small programmes against what Tailwind says is needed.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'A small set of dedicated transition programmes (Successif, SteadRise, BlueDot''s grants, the Generator Residency) that did not exist a few years ago.', 'high', FALSE,
  '{"title":"Mid-career entry points, Project Tailwind","url":"https://coefficientgiving.org/tailwind/initiatives/#mid-career-entry-points"}'::jsonb, 'SteadRise is the most direct route for an experienced professional wanting a structured, one-to-one path in; Successif is the equivalent for people aiming specifically at AI governance. BlueDot''s Career Transition Grant is a lighter-weight option for someone who already has a specific plan.', 'b09', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.talent.senior-and-specialist-recruitment', (SELECT id FROM public.subareas WHERE slug = 'meta.talent'), 'Senior and specialist capacity', 'Safety organisations, frontier projects and lab safety teams struggle to get senior or narrowly specialised expertise, such as security engineers with the nation-state threat experience needed to reach RAND security levels SL4 and SL5, policy veterans with legislative drafting experience, or legal and technical specialists for a one-off question. Ordinary recruiting channels and pay do not reach these people, and small organisations cannot justify keeping every specialist on staff, so the field needs both a way to hire them and a way to borrow them on demand.', 'Some of the most important gaps, weight security above all, cannot be filled by training newcomers, and without a shared pool of on-call experts every team either duplicates scarce hires or makes specialist decisions without specialist advice.', 'A dedicated search function and specialist pipelines, above all for security talent, fill senior and specialist roles within months, and a credible advisory body exists that safety teams, including small independent ones, routinely call on for specialist input.',
  '{"title":"AI safety field-building survey: Talent needs, infrastructure needs, and relationship to EA (CEA, 2023)","url":"https://forum.effectivealtruism.org/posts/vzuqnPyfDFjtbCpgv/ai-safety-field-building-survey-talent-needs-infrastructure"}'::jsonb, '[{"name":"Senior talent headhunting (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#senior-talent-headhunting"},{"name":"Think tank for AI labs (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#think-tank-for-ai-labs"}]'::jsonb, 'Getting scarce senior and specialist expertise into the field, by hiring it or borrowing it. Broad matching of people to roles is meta.talent.matchmaking; general on-ramps are meta.talent.experienced-professionals; the security work itself, and Tailwind''s ''Security capacity buildout'' initiative, sit with model.model-security.weights-security; the lab functions this expertise feeds are model.developer-assurance.', ARRAY['Senior talent headhunting', 'Think tank for AI labs']::text[],
  'thin', 'Impact Ops headhunts for high-impact organisations, Heron and security bootcamps build security pipelines, and GovAI, the Frontier Model Forum and METR supply advice informally, but nobody reliably finds nation-state-grade security engineers or runs an on-demand advisory service.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Impact Ops'' recruitment and headhunting service; Heron, the AI Security Bootcamp and the Frontier AI Security Residency for security professionals; SteadRise introductions for leadership and operations roles; labs'' own security recruiting. On the advisory side, GovAI, the Frontier Model Forum and METR each supply part of an on-demand function informally.', 'medium', FALSE,
  '{"title":"Project Tailwind: 36 initiatives","url":"https://coefficientgiving.org/tailwind/initiatives/"}'::jsonb, 'A security specialist can join Heron''s community or fellowship, or the AI Security Bootcamp, to build context and contacts; a senior policy or operations person can go through SteadRise. Someone who wants to build the missing capacity could join Impact Ops'' AI-safety recruitment team, or pitch a dedicated search function or an on-demand advisory body to Coefficient Giving under its ''Senior talent headhunting'' and ''Think tank for AI labs'' initiatives.', 'b09', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.talent.matchmaking', (SELECT id FROM public.subareas WHERE slug = 'meta.talent'), 'Talent matchmaking', 'With hundreds of organisations and a fragmented set of job boards, mailing lists and personal networks, a qualified person and a role that needs them frequently fail to find each other; Coefficient Giving names ''talent matchmaking'' as a distinct gap even though 80,000 Hours, BlueDot and Kairos already do parts of this.', 'Every unfilled role that could have been filled by an existing qualified person is a wasted opportunity cost on top of the field''s stated talent bottleneck, and duplicated, incompatible matchmaking systems make it worse rather than better.', 'Important roles across the ecosystem are filled quickly by the best available person, because someone actively matches candidates to roles using shared talent directories and referrals, rather than relying on who happens to see a job advert.',
  '{"title":"Talent matchmaking, Project Tailwind","url":"https://coefficientgiving.org/tailwind/initiatives/#talent-matchmaking"}'::jsonb, '[{"name":"Talent matchmaking (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#talent-matchmaking"}]'::jsonb, 'Systematic matching of people to roles across the ecosystem. Bespoke search for senior and specialist people is meta.talent.senior-and-specialist-recruitment; people meeting in person is meta.convenings.convenings-and-events.', ARRAY['Talent matchmaking']::text[],
  'thin', '80,000 Hours'' job board and advising, BlueDot, Kairos and the AISafety.com jobs board each do part of this, without ecosystem-wide active matching.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], '80,000 Hours'' job board and advising line already provide a large, general-purpose matching mechanism; Kairos, BlueDot and Constellation each provide narrower, programme-specific matching.', 'medium', TRUE,
  '{"title":"Project Tailwind: 36 initiatives","url":"https://coefficientgiving.org/tailwind/initiatives/"}'::jsonb, '80,000 Hours'' job board and free 1-on-1 advising calls are the single most accessible entry point for anyone, regardless of experience level, looking to be matched to a role.', 'b09', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.evidence.capability-forecasting', (SELECT id FROM public.subareas WHERE slug = 'meta.evidence'), 'Capability forecasting', 'Estimating how fast AI capabilities, compute use and algorithmic efficiency will grow, and when specific dangerous capabilities are likely to arrive, so that safety and policy work can be sequenced against a realistic timeline rather than guesswork.', 'Almost every other safety and governance decision (how urgently to fund something, when a regulation needs to bind, when a lab''s safeguards need to be ready) depends on some implicit timeline; bad forecasts lead to safety work arriving after the capability it was meant to precede.', 'Forecasts of capability and compute trends are track-recorded, calibrated and specific enough that policymakers and safety researchers can cite a number with a stated confidence interval rather than a vibe.',
  '{"title":"Trends in Artificial Intelligence, Epoch AI","url":"https://epoch.ai/trends"}'::jsonb, '[{"name":"Epoch AI trends","url":"https://epoch.ai/trends"},{"name":"Measuring AI Ability to Complete Long Tasks (task time horizons), METR","url":"https://metr.org/blog/2025-03-19-measuring-ai-ability-to-complete-long-tasks/"},{"name":"AI Futures Project timelines forecasting","url":"https://ai-futures.org"}]'::jsonb, 'Producing forecasts of capability, compute and timelines. Using them for scenario reasoning is meta.evidence.macrostrategy-and-prioritisation; the benchmarks forecasts rest on are model.evaluations.benchmarks-and-tooling; economy-specific forecasting is society.economic-transition.labour-disruption.', '{}'::text[],
  'active', 'Epoch AI, METR''s time horizons, Metaculus, the Forecasting Research Institute and the AI Futures Project work on this with public track records.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'high', FALSE,
  NULL, 'Metaculus is the lowest-friction way in: anyone can start forecasting AI questions today and build a public track record. Epoch AI and Forecasting Research Institute both list open roles and publish their methods openly, and the AI Futures Project is small enough that direct outreach with a concrete forecasting or scenario contribution is plausible.', 'b10', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.evidence.incident-tracking', (SELECT id FROM public.subareas WHERE slug = 'meta.evidence'), 'Incident tracking', 'A structured, ongoing record of AI-caused or AI-involved harms and near-misses (deployment failures, agent misbehaviour, misuse cases) that researchers, journalists and policymakers can query, analogous to aviation incident databases.', 'Without a shared record, each new incident is analysed from scratch, patterns across incidents (which failure modes recur, which safeguards actually prevented harm) go unnoticed, and policy debates rely on anecdote rather than a queryable base rate.', 'A single widely-trusted incident database is comprehensive, current and used as a standard citation in policy and research documents, the way aviation''s incident databases are used in that industry.',
  '{"title":"Welcome to the Artificial Intelligence Incident Database","url":"https://incidentdatabase.ai/"}'::jsonb, '[]'::jsonb, 'The public catalogue of reported incidents. Investigating a specific incident''s root cause is meta.evidence.incident-investigation; a lab''s own disclosure is model.developer-assurance.incident-reporting; live detection of attacks is misuse.cyber.attack-detection.', '{}'::text[],
  'active', 'The AI Incident Database, AIAAIC and the OECD''s monitor maintain public catalogues, with frontier-model and agent incidents less well catalogued.', ARRAY['independent-ai-safety', 'government']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'high', FALSE,
  NULL, 'The AI Incident Database accepts public incident submissions from anyone, the most direct way in. The OECD AI Incidents Monitor is a government-run tool rather than an entry route for individuals, but its methodology page is a good technical reference for anyone wanting to build a similar tracker.', 'b10', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.evidence.incident-investigation', (SELECT id FROM public.subareas WHERE slug = 'meta.evidence'), 'Incident investigation', 'When an AI system behaves dangerously or unexpectedly in the wild, someone needs to do the equivalent of an air-accident investigation: reconstruct what happened, why, and what would have prevented it, independently of the company whose system was involved.', 'Without independent investigation, the public and other developers only get the account the involved company chooses to publish, which may understate causes uncomfortable for the company and misses lessons other developers need in order to avoid the same failure.', 'A recognised, resourced independent investigation capacity exists that can be triggered quickly after a significant incident and produces a public report with the credibility of, say, an aviation safety board.',
  '{"title":"Brief independent investigation of agents'' behavior, reasoning and collaboration in the OpenAI / Hugging Face hacking incident, METR","url":"https://metr.org/blog/2026-08-26-openai-hugging-face-incident-investigation/"}'::jsonb, '[{"name":"AI incident investigations (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#ai-incident-investigations"},{"name":"How independent researchers could investigate AI propensities after misalignment incidents, METR","url":"https://metr.org/blog/2026-07-28-investigating-ai-propensities-after-incidents/"}]'::jsonb, 'Independent root-cause investigation of a specific incident, like an air-accident investigation. Whether a lab kept its promises is meta.watchdogs.lab-accountability; a lab''s own disclosure is model.developer-assurance.incident-reporting; the catalogue of incidents is meta.evidence.incident-tracking.', ARRAY['AI incident investigations']::text[],
  'thin', 'The METR and Redwood Research investigation of the August 2026 OpenAI and Hugging Face incident is the first concrete example, a joint, ad hoc effort rather than a standing capacity.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'high', FALSE,
  '{"title":"AI incident investigations, Project Tailwind","url":"https://coefficientgiving.org/tailwind/initiatives/#ai-incident-investigations"}'::jsonb, 'Coefficient Giving''s Tailwind page names this a funding gap and explicitly invites teams to pitch a standing investigation capacity; METR and Redwood Research are both hiring and demonstrated exactly this kind of work in August 2026, making them the natural people to approach or apply to first.', 'b10', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.evidence.state-of-risk', (SELECT id FROM public.subareas WHERE slug = 'meta.evidence'), 'Living reviews of AI risk', 'A canonical, regularly updated synthesis of the evidence on AI risks (capability, misuse, misalignment, structural) that a policymaker or new researcher can read to get an accurate, current picture, rather than reconstructing it from scattered papers, blog posts and lab claims.', 'Fragmented evidence means policymakers and new entrants either rely on whichever single source they encountered first (which may be outdated or one-sided) or spend large amounts of time reconstructing a synthesis that should be a shared public good.', 'A single or small number of reports are recognised across the field and by governments as the current best synthesis, updated on a predictable schedule, the way the IPCC reports function for climate science.',
  '{"title":"International AI Safety Report 2026","url":"https://internationalaisafetyreport.org/publication/international-ai-safety-report-2026"}'::jsonb, '[{"name":"State of AI risk (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#state-of-ai-risk"},{"name":"International AI Safety Report","url":"https://internationalaisafetyreport.org/"}]'::jsonb, 'Synthesis of what is known about the risks. Synthesis of the field''s own structure, and what to prioritise, is meta.evidence.macrostrategy-and-prioritisation; policy documents that use this evidence to argue for rules sit in society.public-policy.', ARRAY['State of AI risk']::text[],
  'thin', 'The annual International AI Safety Report and the MIT AI Risk Repository exist, without a continuously updated synthesis of the kind Tailwind describes.', ARRAY['government', 'academia']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'medium', FALSE,
  '{"title":"State of AI risk, Project Tailwind","url":"https://coefficientgiving.org/tailwind/initiatives/#state-of-ai-risk"}'::jsonb, 'The International AI Safety Report process periodically calls for nominated expert contributors through national governments, which is not a direct-application route; the MIT AI Risk Repository team and Coefficient Giving''s Tailwind page are more approachable starting points for someone wanting to build or contribute to a living synthesis.', 'b10', 3,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.evidence.capability-demonstrations', (SELECT id FROM public.subareas WHERE slug = 'meta.evidence'), 'Capability demonstrations for decision-makers', 'Producing clear, credible, hands-on demonstrations of specific dangerous or surprising frontier model capabilities (autonomous cyber intrusion, self-exfiltration, deception) for an audience of policymakers and executives who otherwise only see capabilities through a company''s own marketing or a dry benchmark score.', 'Abstract benchmark numbers rarely change minds the way a concrete, watchable demonstration does; without this translation layer, decision-makers underestimate or overestimate risk based on impressions rather than evidence.', 'Decision-makers routinely have access to credible, independently produced demonstrations of current frontier capabilities before making major policy or investment decisions, rather than relying solely on lab-provided materials.',
  '{"title":"Shutdown Resistance in Reasoning Models, Palisade Research","url":"https://palisaderesearch.org/research/shutdown-resistance"}'::jsonb, '[{"name":"Frontier capabilities observatory (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#frontier-capabilities-observatory"}]'::jsonb, 'Translating results into hands-on demonstrations for decision-makers. The measurement is model.evaluations.dangerous-capability-evals; bio-specific demonstrations for policymakers sit with misuse.bio-chem.knowledge-uplift; material for the general public is meta.communications.public-explanation.', ARRAY['Frontier capabilities observatory']::text[],
  'thin', 'Palisade Research and CivAI show demonstrations to lawmakers and AI Digest builds interactive explainers, without a systematic, regularly updated view across capability areas.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'medium', FALSE,
  '{"title":"Frontier capabilities observatory, Project Tailwind","url":"https://coefficientgiving.org/tailwind/initiatives/#frontier-capabilities-observatory"}'::jsonb, 'Palisade Research publishes its methods openly and is the clearest model to emulate or join; Coefficient Giving''s Tailwind page is actively looking to fund a dedicated ''observatory'' along these lines, so a concrete proposal is a plausible route to funding.', 'b10', 4,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.evidence.threat-modelling', (SELECT id FROM public.subareas WHERE slug = 'meta.evidence'), 'Threat modelling', 'Systematically developing, comparing and curating explicit models of how catastrophic outcomes from AI could actually occur (which actors, which failure chains, which warning signs), as a discipline in its own right rather than an implicit assumption buried inside individual papers and proposals.', 'Different organisations currently operate on different, often unstated threat models, which makes it hard to compare the relative value of their work or spot a threat model that most of the field has neglected entirely.', 'A small number of institutions maintain and continuously update rigorous, explicit, comparable threat models that most of the field references, the way biosecurity has established threat-modelling conventions for pandemic risk.',
  '{"title":"An Overview of Catastrophic AI Risks (Hendrycks, Mazeika and Woodside, 2023)","url":"https://arxiv.org/abs/2306.12001"}'::jsonb, '[{"name":"Threat modeling institute (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#threat-modeling-institute"}]'::jsonb, 'Modelling the causal paths to catastrophe as a discipline. Specific mechanisms are nodes in society.structural-risk and the Harmful use layer; scenario work and judgements about where effort should go are meta.evidence.macrostrategy-and-prioritisation; what alignment means is model.alignment.conceptual-foundations.', ARRAY['Threat modeling institute']::text[],
  'thin', 'Forethought and Convergence Analysis do closely related work and labs publish risk taxonomies, but nobody maintains explicit, comparable threat models as a main mandate.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'medium', FALSE,
  '{"title":"Threat modeling institute, Project Tailwind","url":"https://coefficientgiving.org/tailwind/initiatives/#threat-modeling-institute"}'::jsonb, 'Forethought and Convergence Analysis both publish their research programmes openly and are realistic direct-application or collaboration targets; Coefficient Giving''s Tailwind page is explicitly seeking a founder to build a dedicated institute around this function.', 'b10', 5,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.evidence.macrostrategy-and-prioritisation', (SELECT id FROM public.subareas WHERE slug = 'meta.evidence'), 'Macrostrategy and prioritisation', 'Research that builds integrated scenarios of how transformative AI could unfold and uses them, together with evidence about the field itself, to judge which interventions, organisations and gaps deserve scarce money and talent. Scenario work stress-tests strategy rather than producing a single forecast; prioritisation compares interventions and studies the field as an ecosystem (which sub-problems are neglected, how organisations divide the work, how growth should be sequenced).', 'Point forecasts do not tell anyone what to do differently, and with scarce money and talent, misjudging which gaps matter most wastes years; without scenario work and field-level study, gaps like the empty nodes on this map stay invisible.', 'Several independent groups produce falsifiable scenario work that is revisited against what actually happens, and regular, public, evidence-based prioritisation of the field''s gaps is used by funders and entrants, with this map aiming to be one input.',
  '{"title":"AI 2027, AI Futures Project","url":"https://ai-2027.com/"}'::jsonb, '[{"name":"AI Futures Project scenario work","url":"https://ai-futures.org"},{"name":"80,000 Hours AI safety fieldbuilding career review","url":"https://80000hours.org/career-reviews/ai-safety-fieldbuilding/"},{"name":"Shallow review of technical AI safety, 2025","url":"https://shallowreview.ai/"},{"name":"Project Tailwind initiatives, Coefficient Giving","url":"https://coefficientgiving.org/tailwind/initiatives/"}]'::jsonb, 'Scenario reasoning and deciding where effort should go. Calibrated forecasts of measurable trends are meta.evidence.capability-forecasting; synthesis of what is known about the risks is meta.evidence.state-of-risk; explicit models of how catastrophes could unfold are meta.evidence.threat-modelling; moving money is meta.funding; economy-specific scenarios are society.economic-transition.labour-disruption.', '{}'::text[],
  'active', 'A few small, well-regarded groups build scenarios (the AI Futures Project, Forethought) and several organisations prioritise as part of wider mandates (Coefficient Giving, 80,000 Hours, Arb Research''s shallow review).', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'medium', FALSE,
  NULL, 'The AI Futures Project and Forethought both publish openly and are the natural first stops for scenario work. RAND''s AI and emerging-risk teams offer a more institutional route for someone with a policy or defence background. For prioritisation, 80,000 Hours'' career review and job board is the most accessible entry point and is kept current, and Coefficient Giving''s Tailwind page is a public list of prioritised gaps that doubles as a funding pitch for anyone wanting to found something in one of them.', 'b10', 6,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.watchdogs.lab-accountability', (SELECT id FROM public.subareas WHERE slug = 'meta.watchdogs'), 'Lab accountability tracking', 'Independent, recurring public ratings that compare frontier AI companies on safety practice, and ongoing tracking of changes to their published safety policies that flags when a promise is quietly weakened.', 'Without outside scrutiny, commitments can be walked back unnoticed and the public, investors and regulators cannot compare developers.', 'Sustained, well-funded scorecards and change-tracking covering all major developers, cited by regulators, investors and journalists.',
  '{"title":"AI Safety Index: Summer 2026, Future of Life Institute","url":"https://futureoflife.org/ai-safety-index-summer-2026/"}'::jsonb, '[{"name":"Frontier lab accountability (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#frontier-lab-accountability"}]'::jsonb, 'Outside scrutiny that needs no cooperation from the lab. The commitments being scored are model.developer-assurance.frontier-safety-frameworks; audits with privileged access are model.developer-assurance.third-party-auditing; investigating a specific incident is meta.evidence.incident-investigation.', ARRAY['Frontier lab accountability']::text[],
  'active', 'SaferAI, Guidelight, the Midas Project, FLI and Stanford''s Foundation Model Transparency Index publish recurring comparisons of lab safety practice.', ARRAY['independent-ai-safety', 'academia']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'high', FALSE,
  NULL, 'SaferAI, Guidelight and the Midas Project are small teams that publish their methods and are realistic outreach targets for someone wanting to contribute research or software to a scorecard or policy tracker. Anyone joining should know that AI Lab Watch, the best-known one-person scorecard, closed in September 2025, which shows the main risk in this space: keeping the work going.', 'b10', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.watchdogs.whistleblower-support', (SELECT id FROM public.subareas WHERE slug = 'meta.watchdogs'), 'Whistleblower support', 'Legal, financial and reputational support for employees of AI companies who want to raise safety concerns externally, separate from any internal reporting channel the company itself provides.', 'Internal-only reporting channels give a company control over which concerns become public; independent whistleblower support is what allows genuinely inconvenient information to reach regulators, journalists or the public when internal channels fail or are not trusted.', 'AI company employees with safety-relevant concerns know of, and can access, independent legal and practical support for coming forward, comparable to whistleblower protection infrastructure in finance or aviation.',
  '{"title":"The AI Whistleblower Initiative (AIWI)","url":"https://aiwi.org/"}'::jsonb, '[]'::jsonb, 'Practical legal, financial and reputational support from outside the company. Legal protection in statute is society.public-policy.whistleblower-protection; internal channels are model.developer-assurance.internal-safety-governance.', '{}'::text[],
  'thin', 'The AI Whistleblower Initiative is the one organisation dedicated to AI insiders, with general tech whistleblower groups (Psst.org, Whistleblower Aid, The Signals Network, the National Whistleblower Center) also helping.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], NULL, 'medium', FALSE,
  NULL, 'AIWI''s site is the direct route for AI company insiders with a concern, and for professionals who want to join the expert network behind its ''Third Opinion'' service. Lawyers and investigators can also volunteer with general tech whistleblower groups such as Psst.org or Whistleblower Aid, which take AI cases.', 'b10', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.communications.public-opinion', (SELECT id FROM public.subareas WHERE slug = 'meta.communications'), 'Public opinion and message research', 'Systematic research on what the public and particular constituencies think about AI risk and regulation, and on how they respond to different ways of describing it: rigorous, repeated polling on one side, and audience research and message testing on the other. Covers the overall picture that the field''s many communicators create, as opposed to occasional surveys run for one campaign''s needs.', 'Policymakers and advocates routinely make claims about what the public wants on AI without reliable evidence, and well-meaning messages from different organisations can add up to a confusing or self-undermining picture; measured opinion and tested framing let the field see both.', 'A few recognised, methodologically transparent, longitudinal series track opinion on AI risk and regulation across major countries, communicators share tested evidence on which framings inform rather than polarise, and independent research shows public understanding becoming more stable and accurate over time.',
  '{"title":"How the US Public and AI Experts View Artificial Intelligence, Pew Research Center (April 2025)","url":"https://www.pewresearch.org/internet/2025/04/03/how-the-us-public-and-ai-experts-view-artificial-intelligence/"}'::jsonb, '[{"name":"From Catastrophic to Concrete: message testing on AI risk (Seismic Foundation and co-authors, 2025)","url":"https://arxiv.org/abs/2511.06525"}]'::jsonb, 'Measuring what the public thinks and testing how it responds. Campaigning to change opinion or policy is meta.communications.advocacy; explaining AI risk to the public is meta.communications.public-explanation; the resulting policy debate is society.public-policy.', '{}'::text[],
  'active', 'Established pollsters run recurring AI attitude surveys and AIPI and Seismic Foundation commission AI-risk polling and message testing, without neutral, consistent tracking of questions on catastrophic risk and frontier regulation.', ARRAY['another-field', 'independent-ai-safety']::text[], 'survey research and public opinion polling', 'weak', 'Pollsters'' own AI series rarely ask about catastrophic risk or frontier regulation, and AI safety organisations'' polling is mostly advocacy-aligned; what should flow is consistent, neutral questions into established series and shared evidence on framing across communicators.',
  '{}'::text[], 'Established pollsters'' recurring series on attitudes to AI (Pew, Gallup, YouGov, Ipsos''s AI Monitor, the UK government''s public attitudes tracker); AIPI''s recurring US polls; Seismic Foundation''s audience research and narrative-strategy support for other organisations; informal coordination among communicators through venues such as The Curve and Constellation.', 'medium', FALSE,
  NULL, 'Someone with survey skills can do most by getting consistent questions on catastrophic risk and regulation into existing series, through partnerships with Pew, YouGov or Ipsos, or by building a neutral tracker outside the US. AIPI and Seismic Foundation both commission research and are small enough to approach directly, and Seismic publishes its message-testing work openly.', 'b11', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.communications.public-explanation', (SELECT id FROM public.subareas WHERE slug = 'meta.communications'), 'Explaining AI risk to the public', 'Journalism and standing explanatory material (explainers, FAQs, accessible summaries) that accurately translate AI safety and governance research for people with no background, as opposed to material written for people already planning to enter the field.', 'Public and political understanding of AI risk is shaped mostly by generalist coverage that oscillates between hype and dismissal; without accurate translation, good research does not reach the people who vote and legislate.', 'Specialist reporters and well-maintained general-audience explainers that are widely read outside the already-engaged community.',
  '{"title":"AISafety.info","url":"https://aisafety.info"}'::jsonb, '[]'::jsonb, 'Explaining to the public. The underlying synthesis is meta.evidence.state-of-risk; demonstrations for decision-makers are meta.evidence.capability-demonstrations; campaigning for a position is meta.communications.advocacy.', '{}'::text[],
  'active', 'Explainers for the already curious (AISafety.info, 80,000 Hours'' AI in Context, AI Digest) and outlets aimed at the public and press (Tarbell''s newsroom fellows, The AI Safety Foundation), while most mainstream AI coverage comes from reporters without a safety specialism.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Transformer''s daily coverage, AISafety.info''s FAQ database, and a handful of individual explainer projects.', 'medium', FALSE,
  NULL, 'Tarbell Center''s annual fellowship is the most structured route into AI journalism specifically. AISafety.info takes volunteer contributors and welcomes GitHub pull requests for its explainer database, and is the lowest-friction way to start writing public-facing AI safety explanations without founding anything new.', 'b11', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.communications.advocacy', (SELECT id FROM public.subareas WHERE slug = 'meta.communications'), 'Advocacy', 'Organisations that campaign directly for public and political action on catastrophic AI risk, from grassroots protest movements to Washington-style legislative advocacy shops, distinct from research organisations that merely publish findings.', 'Research findings do not become policy on their own; sustained public and political pressure is usually needed to move legislation. That pressure now meets well-funded opposition, including industry-backed super PACs formed in 2025 to fight state AI safety laws. On the safety side, campaigning is done by a few young organisations whose tactics, from street protest to formal lobbying, are themselves debated within the field.', 'Advocacy organisations exist with a track record of moving specific, named legislation or regulatory decisions, and enough diversity of tactic and constituency that the field is not dependent on one approach or one country''s political dynamics.',
  '{"title":"ControlAI","url":"https://controlai.com"}'::jsonb, '[]'::jsonb, 'Campaigning for public and political action. The laws campaigned for are society.public-policy.legislation; measuring opinion and testing messages is meta.communications.public-opinion; advocacy on bias sits with society.ethics-fairness-welfare.fairness-and-bias.', '{}'::text[],
  'active', 'Several organisations use different tactics (PauseAI, ControlAI, ARI, Encode, FLI, MIRI), while industry-funded counter-advocacy has grown faster since 2025.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'Direct policymaker engagement (ControlAI, Encode), public protest (PauseAI), large-scale campaigning (FLI), and trade-published public argument (MIRI''s book).', 'high', FALSE,
  NULL, 'PauseAI and ControlAI both explicitly recruit volunteers for protests and constituent meetings with almost no entry barrier; Encode and FLI both list open roles and internships for people wanting paid advocacy work. Someone wanting a lower-commitment start could join a PauseAI local chapter or ControlAI''s campaign email list.', 'b11', 2,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.convenings.convenings-and-events', (SELECT id FROM public.subareas WHERE slug = 'meta.convenings'), 'Convenings and events', 'The recurring events and shared event infrastructure that bring people working on AI safety, security and governance together: cross-sector gatherings of lab staff, officials, academics, journalists and civil society; focused forums for one technical or policy subfield; and the venues, logistics and event-running capacity that let any organisation host these without rebuilding that capacity each time.', 'Papers and briefs are slow to build the trust and shared context that coordination between labs, governments and civil society needs, young subfields develop slowly when practitioners cannot compare notes, and the small organisations that would benefit most from convening often lack the capacity to run a good event.', 'Enough well-run convenings exist, at different scales and specificities, that key relationships do not depend on a single annual guest list; every growing subfield has a recurring forum of its own; and any funded organisation can use shared venues and event support anywhere, not only in one city.',
  '{"title":"Reflections on The Curve, Second Thoughts","url":"https://secondthoughts.ai/p/reflections-on-the-curve"}'::jsonb, '[{"name":"Cross-sector convenings (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#cross-sector-convenings"},{"name":"Subfield forums (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#subfield-forums"},{"name":"Events as a service (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#events-as-a-service"}]'::jsonb, 'Bringing people together, whatever the topic, through events and the infrastructure behind them. Place-based communities outside the main hubs are meta.convenings.regional-hubs; dialogue between countries'' research and policy communities, including IDAIS, is society.international-governance.great-power-dialogue; government summits sit in society.international-governance; the technical content belongs to the relevant node in another layer.', ARRAY['Cross-sector convenings', 'Subfield forums', 'Events as a service']::text[],
  'active', 'Recurring subfield forums (ControlConf, the AI Security Forum, the Alignment Workshop series), a few cross-sector gatherings (The Curve, the Athens Roundtable) and one strong shared venue (Lighthaven), with no general events service usable anywhere.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'The Curve and The Future Society''s Athens Roundtable bring sectors together; ControlConf, the AI Security Forum, FAR.AI''s Alignment Workshop series and the ILIAD conferences serve particular subfields, alongside workshops at ICML and NeurIPS; Lighthaven offers a venue and event-running experience, and LISA and Constellation host events for their communities.', 'medium', FALSE,
  NULL, 'The Alignment Workshop and ControlConf take external applications and are the standard first technical events for someone entering control or alignment research, and the AI Security Forum is the equivalent for people from a security background. Cross-sector gatherings such as The Curve are invitation-based, so the practical route is to build a track record at open events first. An organisation wanting to run an event can book Lighthaven; someone wanting to build the general ''events as a service'' capacity Coefficient Giving describes would be filling a named gap.', 'b11', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.convenings.regional-hubs', (SELECT id FROM public.subareas WHERE slug = 'meta.convenings'), 'Regional community hubs', 'Physical or organisational hubs (shared offices, local meetup networks, national chapters) that let AI safety researchers and newcomers in a given city or country find each other and collaborate, as opposed to the field being concentrated in Berkeley, London and a few other hub cities.', 'Talent and useful perspectives exist outside the existing hub cities, especially in the Global South, but without local infrastructure they stay disconnected from the wider field and the field itself misses regional context it needs (e.g. how AI risk plays out in a different regulatory or economic setting).', 'Active, self-sustaining local hubs exist in a much wider set of cities and countries, each connected into the wider field rather than isolated, and specifically including hubs in the Global South alongside the existing North American and European concentration.',
  '{"title":"AI safety communities worldwide, AISafety.com","url":"https://www.aisafety.com/communities"}'::jsonb, '[]'::jsonb, 'Place-based community infrastructure outside the main hub cities. Individual career pipelines are meta.talent; participation of the same regions in global governance is society.international-governance.inclusive-participation.', '{}'::text[],
  'active', 'Outside Berkeley and London, small national and regional groups (ENAIS, CeSIA, AIGS Canada, Singapore, South Africa, ILINA, India, Brazil) run hubs with few paid staff, and much of Latin America, the Middle East and South and Southeast Asia has little.', ARRAY['independent-ai-safety']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'LISA and Constellation as the two main physical hubs; ENAIS, ILINA and national groups as newer regional infrastructure.', 'high', FALSE,
  NULL, 'LISA and Constellation both run fellowship or visiting-researcher programmes that are the standard route to a desk in the two main hub cities. Someone outside Berkeley or London is better served starting with ENAIS (Europe) or ILINA (Africa), both of which actively recruit through their own programmes rather than requiring relocation.', 'b11', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.tooling.shared-research-infrastructure', (SELECT id FROM public.subareas WHERE slug = 'meta.tooling'), 'Shared compute, data and environments', 'Shared compute (GPU clusters, cloud credits, remote access to the internals of large open models) and public datasets and test environments built to advance safety research, available to nonprofit and academic researchers who cannot build their own. Frontier labs have all of these in-house; outside them, empirical safety research is limited by what researchers can buy, borrow or rebuild from scratch.', 'If independent researchers cannot get the compute, model access and environments that lab teams take for granted, safety research outside the labs is capped at small models and duplicated effort, and the field''s independent check on lab claims weakens.', 'A dedicated, adequately sized compute resource for safety research exists, alongside maintained public libraries of safety-specific datasets and environments that any researcher can use, as ControlArena now is for control research.',
  '{"title":"Compute Cluster, Center for AI Safety","url":"https://safe.ai/work/compute-cluster"}'::jsonb, '[{"name":"Compute cluster for AI safety (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#compute-cluster-for-ai-safety"},{"name":"Datasets for AI safety (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#datasets-for-ai-safety"},{"name":"ControlArena, UK AI Security Institute''s open library of control environments","url":"https://control-arena.aisi.org.uk/"}]'::jsonb, 'Shared compute, data and environments for safety research. Benchmarks and harnesses built to measure models are model.evaluations.benchmarks-and-tooling; government rules on who can access compute are society.compute-governance; AI tools that speed up research are meta.tooling.ai-uplift.', ARRAY['Compute cluster for AI safety', 'Datasets for AI safety']::text[],
  'thin', 'The CAIS compute cluster (closed to new applicants), NDIF''s access to open-model internals and open environment libraries such as ControlArena exist, but nothing operates at the scale Tailwind describes.', ARRAY['independent-ai-safety', 'government']::text[], NULL, 'not-applicable', NULL,
  '{}'::text[], 'The CAIS compute cluster (paused for new applicants); NDIF for remote access to the internals of open models; open environment libraries that come out of individual research programmes (ControlArena, CAIS datasets such as WMDP, Redwood''s control settings); commercial environment-building for frontier labs (Trajectory Labs), which is related but not a public good; general national and commercial compute programmes with nothing earmarked for safety.', 'medium', FALSE,
  NULL, 'Researchers can contact CAIS about future access to its cluster, use NDIF for interpretability work on large open models, or apply to general schemes (NAIRR, Isambard-AI, Lambda, Prime Intellect). Contributors can add to open environment libraries such as ControlArena, which accept outside contributions, or build a dataset for a named gap. Someone with infrastructure experience could build the larger shared cluster Coefficient Giving says it wants to fund.', 'b11', 0,
  (SELECT id FROM public.actors WHERE agent_key = 'v2-build-2026-09-24'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.nodes (
  slug, subarea_id, name, definition, why_it_matters, progress_looks_like,
  canonical_reference, key_agendas, boundary_notes, tailwind_links,
  capacity, capacity_note, home, owner_field, connection, connection_note,
  lenses, existing_mitigations, confidence, reference_needs_replacing,
  open_problems_source, entry_points, legacy_batch, sort_order,
  created_by, created_method, created_at, last_checked_at, verification_state
) VALUES (
  'meta.tooling.ai-uplift', (SELECT id FROM public.subareas WHERE slug = 'meta.tooling'), 'AI uplift for safety research', 'Deliberately applying current frontier AI capabilities (coding assistance, literature synthesis, experiment automation) to speed up AI safety research itself, so that the safety ecosystem benefits from capability progress rather than being structurally slower than capabilities work that has no qualms about heavy AI-assisted development.', 'If capabilities research increasingly uses AI to accelerate itself while safety research does not, the gap between how fast capabilities and safety progress will widen for a reason that has nothing to do with the intrinsic difficulty of either.', 'Independent safety organisations routinely and effectively use frontier AI tools to accelerate their research pipelines, with measurable productivity gains comparable to what capabilities labs report internally.',
  '{"title":"Automated Alignment Researchers, Anthropic","url":"https://www.anthropic.com/research/automated-alignment-researchers"}'::jsonb, '[{"name":"AI uplift for AI safety (Tailwind initiative)","url":"https://coefficientgiving.org/tailwind/initiatives/#ai-uplift-for-ai-safety"}]'::jsonb, 'The independent ecosystem adopting frontier AI for its own work. Frontier labs'' plan to automate alignment research, and the problem of trusting its output, is model.alignment.automated-alignment-research; measuring AI research capability is model.evaluations; AI tools for policy decisions are society.epistemics.decision-quality.', ARRAY['AI uplift for AI safety']::text[],
  'thin', 'Transluce builds AI research tools that other safety teams use, and labs automate their own research internally, but no programme helps the independent ecosystem adopt frontier tools.', ARRAY['independent-ai-safety', 'frontier-labs']::text[], NULL, 'not-applicable', NULL,
  ARRAY['defensive-technology']::text[], 'Anthropic''s internal automated-alignment-researcher pipeline; ad hoc use of general coding/research assistants by independent researchers, not organised as a programme.', 'medium', FALSE,
  NULL, 'Transluce publishes its tools and hires research engineers, and independent researchers can adopt Docent and similar tools now. Someone who wants to close the gap could give the ecosystem shared agent scaffolds, model credits and training, which is what Coefficient Giving''s Tailwind initiative asks for.', 'b11', 1,
  (SELECT id FROM public.actors WHERE agent_key = 'compile-2026-09'), 'import', '2026-09-24T00:00:00Z', '2026-09-24T00:00:00Z', 'unverified'
) ON CONFLICT (slug) DO NOTHING;

